#!/usr/bin/env bash
# =====================================================================
#  APEX Security Automation v8.0.0  —  single-file distribution
#  Generated by build.sh from modular, unit-tested sources.
#  16-phase evidence-first recon & assessment pipeline.
#  LEGAL USE ONLY: authorized targets, local labs, and test environments.
# =====================================================================
set -uo pipefail
APEX_VERSION="8.0.0"

# ===== lib/core/log.sh =====
# APEX :: lib/core/log.sh
# Structured logging. FIX M-1: never write ANSI colors into log files;
# colors only on an interactive TTY. Console -> stderr, file -> plain/JSON.

: "${APEX_LOG_LEVEL:=INFO}"
: "${APEX_LOG_FILE:=}"
: "${APEX_LOG_JSON:=0}"
: "${APEX_LOG_COMPONENT:=apex}"

_apex_lvl_num() {
	case "$1" in
		DEBUG) printf '10' ;;
		INFO)  printf '20' ;;
		WARN)  printf '30' ;;
		ERROR) printf '40' ;;
		*)     printf '20' ;;
	esac
}

_apex_color_enabled() {
	[[ -z "${APEX_NO_COLOR:-}" && -t 2 ]]
}

_apex_log() {
	local level="$1"; shift
	local msg="$*"
	local threshold cur
	threshold="$(_apex_lvl_num "$APEX_LOG_LEVEL")"
	cur="$(_apex_lvl_num "$level")"
	(( cur < threshold )) && return 0

	local ts comp
	ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
	comp="${APEX_LOG_COMPONENT:-apex}"

	# Console (stderr) - colored only on a real TTY
	if _apex_color_enabled; then
		local c reset=$'\033[0m'
		case "$level" in
			DEBUG) c=$'\033[2m'  ;;
			INFO)  c=$'\033[36m' ;;
			WARN)  c=$'\033[33m' ;;
			ERROR) c=$'\033[31m' ;;
			*)     c=''          ;;
		esac
		printf '%s%s %-5s [%s] %s%s\n' "$c" "$ts" "$level" "$comp" "$msg" "$reset" >&2
	else
		printf '%s %-5s [%s] %s\n' "$ts" "$level" "$comp" "$msg" >&2
	fi

	# File (never colored). JSON is built with jq to guarantee valid escaping.
	if [[ -n "$APEX_LOG_FILE" ]]; then
		if [[ "$APEX_LOG_JSON" == "1" ]] && command -v jq >/dev/null 2>&1; then
			jq -cn --arg ts "$ts" --arg lvl "$level" --arg comp "$comp" --arg msg "$msg" \
				'{ts:$ts,level:$lvl,component:$comp,message:$msg}' >> "$APEX_LOG_FILE"
		else
			printf '%s %-5s [%s] %s\n' "$ts" "$level" "$comp" "$msg" >> "$APEX_LOG_FILE"
		fi
	fi
	return 0
}

log_debug() { _apex_log DEBUG "$@"; }
log_info()  { _apex_log INFO  "$@"; }
log_warn()  { _apex_log WARN  "$@"; }
log_error() { _apex_log ERROR "$@"; }

# ===== lib/core/errors.sh =====
# APEX :: lib/core/errors.sh
# Typed exit codes + controlled failure. FIX C-1: no silent '|| true'.

# Requires log.sh to be sourced first.
declare -grx APEX_E_OK=0
declare -grx APEX_E_GENERAL=1
declare -grx APEX_E_USAGE=2
declare -grx APEX_E_DEP=3
declare -grx APEX_E_CONFIG=4
declare -grx APEX_E_SCOPE=5
declare -grx APEX_E_TOOL=6

apex_die() {
	local code="$1"; shift
	if declare -F log_error >/dev/null 2>&1; then
		log_error "$*"
	else
		printf 'ERROR: %s\n' "$*" >&2
	fi
	exit "$code"
}

apex_require_cmd() {
	local c="$1"
	command -v "$c" >/dev/null 2>&1 || apex_die "$APEX_E_DEP" "required command not found: $c"
}

# Install a fail-loud ERR trap for the main script (opt-in via apex_enable_strict).
apex_enable_strict() {
	set -uo pipefail
	trap '_apex_on_err $? $LINENO' ERR
}

_apex_on_err() {
	local rc="$1" line="$2"
	if declare -F log_error >/dev/null 2>&1; then
		log_error "unhandled error rc=$rc at line $line (${BASH_SOURCE[1]:-?})"
	fi
}

# ===== lib/core/util.sh =====
# APEX :: lib/core/util.sh — small pure helpers (validation, uuid, hashing).

apex_uuid() {
	if [[ -r /proc/sys/kernel/random/uuid ]]; then
		cat /proc/sys/kernel/random/uuid
	elif command -v python3 >/dev/null 2>&1; then
		python3 -c 'import uuid;print(uuid.uuid4())'
	else
		printf '%s-%s' "$(date -u +%s%N)" "$RANDOM"
	fi
}

apex_sha256() {
	# hash of stdin -> hex
	if command -v sha256sum >/dev/null 2>&1; then
		sha256sum | awk '{print $1}'
	else
		python3 -c 'import sys,hashlib;print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())'
	fi
}

# Strict domain validation (RFC-ish). Returns 0 if valid.
is_valid_domain() {
	local d="${1,,}"
	[[ -n "$d" && ${#d} -le 253 ]] || return 1
	[[ "$d" =~ ^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$ ]]
}

# Extract lowercase host from a URL or bare host.
url_host() {
	local u="$1"
	u="${u#*://}"      # strip scheme
	u="${u%%/*}"       # strip path
	u="${u%%\?*}"      # strip query
	u="${u##*@}"       # strip userinfo
	u="${u%%:*}"       # strip port
	printf '%s' "${u,,}"
}

# Trim leading/trailing whitespace.
apex_trim() {
	local s="$1"
	s="${s#"${s%%[![:space:]]*}"}"
	s="${s%"${s##*[![:space:]]}"}"
	printf '%s' "$s"
}

