cfg_get()  { printf '%s' "${APEX_CFG[$1]:-}"; }
cfg_get_default() { local v="${APEX_CFG[$1]:-}"; [[ -n "$v" ]] && printf '%s' "$v" || printf '%s' "$2"; }
cfg_set()  { APEX_CFG["$1"]="$2"; }
cfg_bool() { [[ "${APEX_CFG[$1]:-false}" == "true" || "${APEX_CFG[$1]:-0}" == "1" ]]; }

cfg_load_file() {
	local f="$1"; [[ -f "$f" ]] || return 0
	local line key val
	while IFS= read -r line || [[ -n "$line" ]]; do
		line="${line%%#*}"
		[[ "$line" == *=* ]] || continue
		key="$(printf '%s' "${line%%=*}" | tr -d '[:space:]')"
		val="${line#*=}"
		val="$(apex_trim "$val")"
		[[ -n "$key" ]] || continue
		if [[ -z "${APEX_CFG_DESC[$key]:-}" ]]; then
			log_warn "config: unknown key '$key' ignored"
			continue
		fi
		APEX_CFG["$key"]="$val"
	done < "$f"
}

cfg_load_env() {
	local key envk
	for key in "${APEX_CFG_ORDER[@]}"; do
		envk="APEX_${key^^}"
		[[ -n "${!envk:-}" ]] && APEX_CFG["$key"]="${!envk}"
	done
}

# cfg_apply_cli --key=value ...  (unknown keys are rejected loudly)
cfg_apply_cli() {
	local arg key val
	for arg in "$@"; do
		case "$arg" in
			--*=*)
				key="${arg%%=*}"; key="${key#--}"; val="${arg#*=}"
				key="${key//-/_}"   # accept both --scope-allow-all and --scope_allow_all
				if [[ -z "${APEX_CFG_DESC[$key]:-}" ]]; then
					log_error "unknown option: --$key"; return 2
				fi
				APEX_CFG["$key"]="$val" ;;
			*) : ;;
		esac
	done
}

cfg_dump() {
	local key
	for key in "${APEX_CFG_ORDER[@]}"; do
		printf '%s=%s\n' "$key" "${APEX_CFG[$key]}"
	done
}

# Usage text generated from the schema — always reflects real defaults.
cfg_usage() {
	local key
	printf 'APEX Security Automation — configuration options\n\n'
	printf '  %-16s %-8s %s\n' "OPTION" "DEFAULT" "DESCRIPTION"
	for key in "${APEX_CFG_ORDER[@]}"; do
		printf '  --%-14s %-8s %s\n' "$key" "${APEX_CFG[$key]}" "${APEX_CFG_DESC[$key]}"
	done
}

# ===== lib/core/scope.sh =====
# APEX :: lib/core/scope.sh
# ScopeGuard. FIX H-2 (exact suffix match, not substring) + fail-closed safety.
#
# Supports bug-bounty realities:
#   example.com          -> apex + all sub-domains in scope
#   *.example.com        -> apex + all sub-domains in scope (wildcard entry)
#   *                    -> ALLOW-ALL (wildcard VDP programs with no scope limit)
#   !dev.example.com     -> EXCLUSION (out-of-scope; overrides any inclusion)
#   <file>               -> a file with one entry per line (# comments allowed)
#
# Allow-all can also be enabled via config: scope_allow_all=true.
# Even in allow-all mode, targets must be syntactically valid domains, and any
# exclusion still wins (fail-closed on excluded assets).

declare -ga APEX_SCOPE=()
declare -ga APEX_SCOPE_EXCLUDE=()
declare -g  APEX_SCOPE_ALLOW_ALL=0
# When 1, an EMPTY scope is treated as "any valid domain" instead of denying
# everything. This solves the real-world case of VDP/no-scope programs while
# keeping exclusions authoritative and requiring an explicit opt-in.
declare -g  APEX_SCOPE_DEFAULT_ALLOW=0
scope_set_default_allow() { APEX_SCOPE_DEFAULT_ALLOW="${1:-1}"; }

scope_reset() { APEX_SCOPE=(); APEX_SCOPE_EXCLUDE=(); APEX_SCOPE_ALLOW_ALL=0; APEX_SCOPE_DEFAULT_ALLOW=0; }

_scope_add_entry() {
	local e="$1"
	e="$(printf '%s' "$e" | tr -d '[:space:]')"
	[[ -z "$e" ]] && return 0
	e="${e,,}"                          # case-fold every entry
	[[ "$e" != "*" ]] && e="${e%.}"     # strip trailing dot (FQDN), keep '*' token
	case "$e" in
		'*'|'*.*') APEX_SCOPE_ALLOW_ALL=1 ;;
		'!'*)      APEX_SCOPE_EXCLUDE+=("${e#!}") ;;
		'*.'*)     APEX_SCOPE+=("${e#*.}") ;;      # *.example.com -> example.com
		*)         APEX_SCOPE+=("$e") ;;
	esac
}

scope_load() {
	scope_reset
	local a line
	for a in "$@"; do
		if [[ -f "$a" ]]; then
			while IFS= read -r line || [[ -n "$line" ]]; do
				line="${line%%#*}"
				_scope_add_entry "$line"
			done < "$a"
		else
			_scope_add_entry "$a"
		fi
	done
	# Normalise exclusions to lowercase.
	local i
	for i in "${!APEX_SCOPE_EXCLUDE[@]}"; do
		APEX_SCOPE_EXCLUDE[$i]="${APEX_SCOPE_EXCLUDE[$i],,}"
	done
}

# Enable allow-all from config (called by the CLI when scope_allow_all=true).
scope_enable_allow_all() { APEX_SCOPE_ALLOW_ALL=1; }

_host_matches() {
	local host="$1" d="$2"
	[[ "$host" == "$d" || "$host" == *".$d" ]]
}

# in_scope <host>: exclusion wins; then allow-all; then exact/suffix match.
# Fail-closed: empty host, or no scope and no allow-all => deny.
in_scope() {
	local host="${1,,}"
	host="${host%.}"          # FQDN normalization: strip trailing dot
	host="${host#.}"          # strip a stray leading dot
	[[ -n "$host" ]] || return 1

	# Exclusions always win (out-of-scope assets stay untouched).
	local d
	for d in "${APEX_SCOPE_EXCLUDE[@]}"; do
		_host_matches "$host" "$d" && return 1
	done

	# Allow-all mode: accept any syntactically valid domain.
	if (( APEX_SCOPE_ALLOW_ALL == 1 )); then
		if declare -F is_valid_domain >/dev/null 2>&1; then
			is_valid_domain "$host" && return 0 || return 1
		fi
		return 0
	fi

	# Empty scope: default-allow (opt-in) for no-scope / VDP programs, else deny.
	if (( ${#APEX_SCOPE[@]} == 0 )); then
		if (( ${APEX_SCOPE_DEFAULT_ALLOW:-0} == 1 )); then
			if declare -F is_valid_domain >/dev/null 2>&1; then
				is_valid_domain "$host" && return 0 || return 1
			fi
			return 0
		fi
		return 1
	fi
	for d in "${APEX_SCOPE[@]}"; do
		_host_matches "$host" "$d" && return 0
	done
	return 1
}

url_in_scope() {
	local h; h="$(url_host "$1")"
	in_scope "$h"
}

scope_filter_hosts() {
	local x
	while IFS= read -r x || [[ -n "$x" ]]; do
		[[ -z "$x" ]] && continue
		in_scope "$x" && printf '%s\n' "$x"
	done
}

# Human-readable scope summary for logs/reports.
scope_summary() {
	if (( APEX_SCOPE_ALLOW_ALL == 1 )); then
		printf 'ALLOW-ALL'
	else
		printf '%s' "${APEX_SCOPE[*]:-<none>}"
	fi
	(( ${#APEX_SCOPE_EXCLUDE[@]} > 0 )) && printf ' (exclude: %s)' "${APEX_SCOPE_EXCLUDE[*]}"
	printf '\n'
}

# ===== lib/core/exec.sh =====
# APEX :: lib/core/exec.sh
# Safe tool execution + parallel pool.
# FIX C-1: distinguish success-empty vs failure; never swallow errors with '|| true'.
# FIX C-2: run argv arrays only — never 'bash -c' with interpolated data.
# FIX H-5: correct parallel job accounting.

# apex_exec <label> <timeout_secs> <stdout_file> -- cmd [args...]
# Returns the real exit code. Logs failure with stderr context. Distinguishes:
#   rc!=0            -> failure (logged ERROR)
#   rc==0, 0 bytes   -> success but empty (logged DEBUG)
#   rc==0, >0 bytes  -> success
apex_exec() {
	local label="$1" tmo="$2" outf="$3"; shift 3
	[[ "${1:-}" == "--" ]] && shift
	(( $# > 0 )) || { log_error "apex_exec '$label': no command given"; return 2; }

	local errf; errf="$(mktemp)"
	local rc=0
	# Feed stdin from APEX_EXEC_STDIN when set (a file path), else /dev/null so
	# tools never block waiting on a terminal. This lets us pipe a target list to
	# stdin-reading tools (e.g. aquatone) WITHOUT a shell (FIX 3.5: no 'bash -lc').
	local _inf="${APEX_EXEC_STDIN:-/dev/null}"
	[[ -r "$_inf" ]] || _inf=/dev/null

	# Retry / Error Recovery: retry a transient failure up to APEX_EXEC_RETRIES
	# times with linear backoff. A timeout (124) or a clean success is never
	# retried; neither is a missing binary (127) — retrying those is pointless.
	local retries="${APEX_EXEC_RETRIES:-0}"; [[ "$retries" =~ ^[0-9]+$ ]] || retries=0
	local attempt=0
	while :; do
		rc=0
		if [[ "$tmo" =~ ^[0-9]+$ ]] && (( tmo > 0 )); then
			timeout --preserve-status "$tmo" "$@" <"$_inf" >"$outf" 2>"$errf" || rc=$?
		else
			"$@" <"$_inf" >"$outf" 2>"$errf" || rc=$?
		fi
		(( rc == 0 || rc == 124 || rc == 127 )) && break
		(( attempt >= retries )) && break
		attempt=$(( attempt + 1 ))
		log_warn "tool '$label' rc=$rc — retry $attempt/$retries"
		sleep "$attempt"
	done

	local bytes; bytes="$(wc -c < "$outf" | tr -d ' ')"
	if (( rc != 0 )); then
		local snippet; snippet="$(head -c 300 "$errf" | tr '\n' ' ')"
		# Redact secrets that a tool may have printed to stderr before logging (FIX: stderr leak).
		if [[ -n "${APEX_REDACT_SED:-}" ]] && declare -F redact_str >/dev/null 2>&1; then
			snippet="$(redact_str "$snippet")"
		fi
		if (( rc == 124 )); then
			log_warn "tool '$label' timed out after ${tmo}s"
		else
			log_error "tool '$label' failed rc=$rc: $snippet"
		fi
	elif (( bytes == 0 )); then
		log_debug "tool '$label' ok but produced no output"
	else
		log_debug "tool '$label' ok (${bytes} bytes)"
	fi

	# Structured run event, if the store is active.
	if declare -F store_event >/dev/null 2>&1 && [[ -n "${APEX_RUN_DIR:-}" ]]; then
		store_event "$label" "$rc" "$bytes" || true
	fi

	rm -f "$errf"
	return "$rc"
}

# apex_have <tool>: true if a tool exists on PATH.
apex_have() { command -v "$1" >/dev/null 2>&1; }

# apex_pmap <max> <worker_fn>: read items (one per line) on stdin, run worker with
# bounded concurrency. Correct accounting (FIX H-5). Returns 1 if any worker failed.
apex_pmap() {
	local max="$1" worker="$2"
	[[ "$max" =~ ^[0-9]+$ ]] || max=1
	(( max < 1 )) && max=1
	declare -F "$worker" >/dev/null 2>&1 || { log_error "apex_pmap: worker '$worker' is not a function"; return 2; }

	local running=0 item rc_any=0
	while IFS= read -r item || [[ -n "$item" ]]; do
		[[ -z "$item" ]] && continue
		"$worker" "$item" &
		running=$(( running + 1 ))
		if (( running >= max )); then
			if wait -n; then :; else rc_any=1; fi
			running=$(( running - 1 ))
		fi
	done
	while (( running > 0 )); do
		if wait -n; then :; else rc_any=1; fi
		running=$(( running - 1 ))
	done
	return "$rc_any"
}

# ===== lib/core/store.sh =====
# APEX :: lib/core/store.sh
# Data layer. FIX H-1: structured NDJSON store queried with jq (no fragile grep).
# FIX H-2: exact-match queries. FIX M-5: flock-guarded concurrent appends.
# Backend is dependency-light (jq only). A sqlite3 backend can be added later
# behind the same interface without touching callers.

: "${APEX_RUN_DIR:=}"

store_init() {
	local dir="$1"
	[[ -n "$dir" ]] || { log_error "store_init: empty dir"; return 2; }
	APEX_RUN_DIR="$dir"
	mkdir -p "$APEX_RUN_DIR/db" "$APEX_RUN_DIR/evidence" \
		"$APEX_RUN_DIR/reports" "$APEX_RUN_DIR/logs" "$APEX_RUN_DIR/raw" || return 1
	return 0
}

_store_file() { printf '%s/db/%s.ndjson' "$APEX_RUN_DIR" "$1"; }

# store_put <table> <json-object> -> prints generated id
store_put() {
	local table="$1" json="$2"
	[[ -n "${APEX_RUN_DIR:-}" ]] || { log_error "store_put: store not initialised"; return 2; }
	local f id ts rec
	f="$(_store_file "$table")"
	id="$(apex_uuid)"
	ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
	rec="$(jq -cn --arg id "$id" --arg ts "$ts" --argjson obj "$json" \
		'$obj + {id:$id,_ts:$ts}')" || { log_error "store_put: invalid json for table '$table'"; return 1; }

	local lockfd
	exec {lockfd}>>"$f" || { log_error "store_put: cannot open $f"; return 1; }
	flock -x "$lockfd"
	printf '%s\n' "$rec" >&"$lockfd"
	flock -u "$lockfd"
	exec {lockfd}>&-
	printf '%s\n' "$id"
}

# store_event <label> <rc> <bytes>: append a tool-run event (used by apex_exec).
store_event() {
	local label="$1" rc="$2" bytes="$3"
	local obj
	obj="$(jq -cn --arg label "$label" --argjson rc "${rc:-0}" --argjson bytes "${bytes:-0}" \
		'{tool:$label,rc:$rc,bytes:$bytes}')" || return 1
	store_put events "$obj" >/dev/null
}

# store_all <table>: emit every record (NDJSON). Empty if table absent.
store_all() {
	local f; f="$(_store_file "$1")"
	[[ -f "$f" ]] || return 0
	cat "$f"
}

# store_query <table> <jq_filter> [jq-args...]: run a jq filter over the table.
# Example: store_query hosts 'select(.host==$h)' --arg h api.example.com
store_query() {
	local table="$1" filter="$2"; shift 2
	local f; f="$(_store_file "$table")"
	[[ -f "$f" ]] || return 0
	jq -c "$@" "$filter" "$f"
}

# store_count <table>: number of records.
store_count() {
	local f; f="$(_store_file "$1")"
	[[ -f "$f" ]] || { printf '0'; return 0; }
	wc -l < "$f" | tr -d ' '
}

# store_upsert_host <host>: insert host if not already present (exact match).
store_upsert_host() {
	local host="${1,,}"
	[[ -n "$host" ]] || return 1
	local existing
	existing="$(store_query hosts 'select(.host==$h)|.id' --arg h "$host" | head -1)"
	if [[ -n "$existing" ]]; then
		printf '%s\n' "$existing"
		return 0
	fi
	store_put hosts "$(jq -cn --arg h "$host" '{host:$h}')"
}

# ===== lib/core/redact.sh =====
# APEX :: lib/core/redact.sh
# Secret redaction. FIX M-4: single compiled sed pass instead of O(lines x patterns).

: "${APEX_REDACT_SED:=}"

redact_init() {
	APEX_REDACT_SED="$(mktemp)"
	cat > "$APEX_REDACT_SED" <<'SEDEOF'
s/eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}/[REDACTED_JWT]/g
s/AKIA[0-9A-Z]{16}/[REDACTED_AWS_AKID]/g
s/sk_live_[0-9a-zA-Z]{20,}/[REDACTED_STRIPE_KEY]/g
s/rk_live_[0-9a-zA-Z]{20,}/[REDACTED_STRIPE_KEY]/g
s/SG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}/[REDACTED_SENDGRID]/g
s/key-[0-9a-zA-Z]{32}/[REDACTED_MAILGUN]/g
s/(gh[pousr])_[A-Za-z0-9]{20,}/[REDACTED_GH_TOKEN]/g
s/xox[baprs]-[A-Za-z0-9-]{10,}/[REDACTED_SLACK_TOKEN]/g
s/AIza[0-9A-Za-z_-]{35}/[REDACTED_GOOGLE_API_KEY]/g
s/sk-[A-Za-z0-9]{20,}/[REDACTED_OPENAI_KEY]/g
s/-----BEGIN[A-Z ]*PRIVATE KEY-----/[REDACTED_PRIVATE_KEY]/g
s/(api[_-]?key|secret|password|passwd|token)(["'"'"' :=]+)[^ "'"'"',;]+/\1\2[REDACTED]/gI
SEDEOF
}

# redact_stream: read stdin, write redacted stdout (single pass).
redact_stream() {
	[[ -n "$APEX_REDACT_SED" && -f "$APEX_REDACT_SED" ]] || redact_init
	sed -E -f "$APEX_REDACT_SED"
}

# redact_str <string>: redact a single string.
redact_str() { printf '%s' "$1" | redact_stream; }

redact_cleanup() {
	[[ -n "$APEX_REDACT_SED" && -f "$APEX_REDACT_SED" ]] && rm -f "$APEX_REDACT_SED"
	APEX_REDACT_SED=""
}

# ===== lib/core/findings.sh =====
# APEX :: lib/core/findings.sh
# Evidence-first findings with a strict schema:
# Evidence, Confidence, Reasoning, Validation Status, Impact, Reproduction, FP checks.

# _conf_tier <score 0-100> -> tier name
_conf_tier() {
	local s="$1"
	[[ "$s" =~ ^[0-9]+$ ]] || s=0
	if   (( s >= 90 )); then printf 'CONFIRMED'
	elif (( s >= 75 )); then printf 'HIGH_CONF'
	elif (( s >= 50 )); then printf 'MEDIUM_CONF'
	elif (( s >= 25 )); then printf 'LOW_CONF'
	else                    printf 'NEEDS_REVIEW'
	fi
}

# Multi-factor confidence model (FIX: reviewers asked for more than a manual
# number). Combines the base signal score with evidence quality and tool
# reliability. Only ever applied when there is at least one piece of evidence.
#   _confidence_model <base 0-100> <evidence_count> <validation_status>
_confidence_model() {
	local s="$1" evc="$2" val="$3"
	[[ "$s"   =~ ^[0-9]+$ ]] || s=0
	[[ "$evc" =~ ^[0-9]+$ ]] || evc=0
	# Evidence quality: multiple corroborating artifacts raise confidence.
	(( evc >= 2 )) && s=$(( s + 4 ))
	(( evc >= 3 )) && s=$(( s + 3 ))
	# Tool reliability / repeatability weighting by validation status.
	case "$val" in
		tool-verified|reproduced) s=$(( s + 5 )) ;;
		tool-matched|tool-observed) : ;;
		needs-human)  s=$(( s - 2 )) ;;
		not-reproduced) s=$(( s - 20 )) ;;
	esac
	(( s > 100 )) && s=100
	(( s < 0 )) && s=0
	printf '%d' "$s"
}

# record_evidence <kind> <summary> [raw-string]
# Stores evidence, returns its id. Raw is redacted before persistence.
record_evidence() {
	local kind="$1" summary="$2" raw="${3:-}"
	local red hash obj
	red="$(printf '%s' "$raw" | redact_stream)"
	hash="$(printf '%s' "$raw" | apex_sha256)"
	obj="$(jq -cn --arg kind "$kind" --arg summary "$summary" --arg raw "$red" --arg hash "$hash" \
		'{kind:$kind,summary:$summary,raw:$raw,sha256:$hash}')" || return 1
	store_put evidence "$obj"
}

# emit_finding: strict, evidence-first. All fields explicit; no fabricated defaults.
# Usage (positional):
#   emit_finding <category> <target> <severity> <score> <reasoning> <impact> \
#                <validation_status> <reproduction> <evidence_json> <fp_json>
# evidence_json / fp_json are JSON arrays (default []).
emit_finding() {
	local category="$1" target="$2" severity="$3" score="$4" reasoning="$5" impact="$6"
	local validation="${7:-needs-human}" reproduction="${8:-}" evidence="${9:-[]}" fp="${10:-[]}"
	[[ "$score" =~ ^[0-9]+$ ]] || { log_error "emit_finding: score must be 0-100"; return 2; }

	# Guardrail against hallucination: a finding with zero evidence cannot exceed NEEDS_REVIEW.
	local ev_count; ev_count="$(printf '%s' "$evidence" | jq 'length' 2>/dev/null || echo 0)"
	if (( ev_count == 0 )) && (( score > 24 )); then
		log_warn "emit_finding: no evidence supplied — capping confidence to NEEDS_REVIEW for '$category/$target'"
		score=0
	fi

	# Apply the multi-factor confidence model only when evidence exists
	# (the zero-evidence guardrail above already forced NEEDS_REVIEW otherwise).
	if (( ev_count > 0 )); then
		score="$(_confidence_model "$score" "$ev_count" "$validation")"
	fi
	local tier; tier="$(_conf_tier "$score")"

	# Content-based deduplication (FIX: reviewer asked for smart, content-based
	# dedup + fewer duplicate findings). A stable fingerprint over the semantic
	# identity of a finding (category + target + severity + reasoning). If the
	# same finding was already emitted in this run, suppress the duplicate and
	# return the existing id instead of appending a second record.
	local dedupe_key
	dedupe_key="$(printf '%s|%s|%s|%s' "$category" "$target" "$severity" "$reasoning" | apex_sha256)"
	if [[ -n "${APEX_RUN_DIR:-}" ]]; then
		local _dup
		_dup="$(store_query findings 'select(.dedupe_key==$k)|.id' --arg k "$dedupe_key" 2>/dev/null | head -1 | tr -d '"')"
		if [[ -n "$_dup" ]]; then
			log_debug "emit_finding: duplicate suppressed ($category/$target)"
			printf '%s\n' "$_dup"; return 0
		fi
	fi

	local obj
	obj="$(jq -cn \
		--arg category "$category" --arg target "$target" --arg severity "$severity" \
		--argjson score "$score" --arg tier "$tier" --arg reasoning "$reasoning" \
		--arg impact "$impact" --arg validation "$validation" --arg reproduction "$reproduction" \
		--argjson evidence "$evidence" --argjson fp "$fp" --arg dedupe_key "$dedupe_key" \
		'{category:$category,target:$target,severity:$severity,
		  confidence_score:$score,confidence_tier:$tier,reasoning:$reasoning,
		  impact:$impact,validation_status:$validation,reproduction:$reproduction,
		  evidence:$evidence,fp_checks:$fp,dedupe_key:$dedupe_key}')" || { log_error "emit_finding: json build failed"; return 1; }
	store_put findings "$obj"
}

# ===== lib/core/deps.sh =====
# APEX :: lib/core/deps.sh
# Dependency + version checker. FIX H-4: verify presence AND minimum version,
# so a stale tool with a changed JSON schema cannot silently corrupt results.

# _ver_ge <have> <min>: numeric-dotted version compare, returns 0 if have >= min.
_ver_ge() {
	local have="$1" min="$2"
	[[ "$have" == "$min" ]] && return 0
	local lower
	lower="$(printf '%s\n%s\n' "$have" "$min" | sort -V | head -1)"
	[[ "$lower" == "$min" ]]
}

# _extract_ver <string>: first x.y(.z) token.
_extract_ver() {
	grep -oE '[0-9]+\.[0-9]+(\.[0-9]+)?' <<<"$1" | head -1
}

# dep_check <tool> <version-flag> <min-version|-> : prints one status row, returns rc.
# rc 0 ok, 1 too-old, 2 missing.
dep_check() {
	local tool="$1" flag="$2" min="${3:--}"
	if ! command -v "$tool" >/dev/null 2>&1; then
		printf '  [MISSING] %-14s (not found on PATH)\n' "$tool"
		return 2
	fi
	local raw have
	if [[ "$flag" == "-" ]]; then
		printf '  [OK]      %-14s (present)\n' "$tool"; return 0
	fi
	raw="$("$tool" "$flag" 2>&1 | head -3)"
	have="$(_extract_ver "$raw")"
	if [[ -z "$have" ]]; then
		printf '  [OK?]     %-14s (present, version unknown)\n' "$tool"; return 0
	fi
	if [[ "$min" == "-" ]] || _ver_ge "$have" "$min"; then
		printf '  [OK]      %-14s v%s\n' "$tool" "$have"; return 0
	else
		printf '  [OLD]     %-14s v%s (< required %s)\n' "$tool" "$have" "$min"; return 1
	fi
}

# Core tools APEX cannot run without.
deps_check_core() {
	local rc=0
	dep_check bash    --version -   || rc=1
	dep_check jq      --version 1.6 || rc=1
	dep_check awk     -         -   || rc=1
	dep_check sed     --version -   || rc=1
	dep_check grep    --version -   || rc=1
	dep_check timeout --version -   || rc=1
	dep_check flock   --version -   || rc=1
	return "$rc"
}

# Optional recon/scan tools (missing => that stage is skipped, not fatal).
deps_check_optional() {
	dep_check subfinder -version - || true
	dep_check httpx     -version - || true
	dep_check dnsx      -version - || true
	dep_check naabu     -version - || true
	dep_check nuclei    -version - || true
	dep_check katana    -version - || true
	dep_check ffuf      -V       - || true
	dep_check curl      --version - || true
	dep_check dig       -v       - || true
	return 0
}

# ===== lib/core/report.sh =====
# APEX :: lib/core/report.sh
# Reporting engine. Builds report.json / report.md / report.html from the
# structured findings store. FIX M-2: reports are generated with jq from a
# validated store, never string-concatenated. Empty store => valid empty report
# (no fabricated results).

report_generate() {
	local scope="${1:-<none>}"
	local dir="${APEX_RUN_DIR:?report_generate: APEX_RUN_DIR unset}"
	local ff="$dir/db/findings.ndjson"
	local ef="$dir/db/evidence.ndjson"
	local out_json="$dir/reports/report.json"
	local out_md="$dir/reports/report.md"
	local out_html="$dir/reports/report.html"
	local gen; gen="$(date -u +%Y-%m-%dT%H:%M:%SZ)"

	# ---- JSON ----
	if [[ -f "$ff" ]]; then
		jq -s --arg scope "$scope" --arg gen "$gen" '
			. as $f |
			{ meta: { scope:$scope, generated_at:$gen, total: ($f|length),
			          by_severity: (reduce $f[] as $x ({}; .[$x.severity] = ((.[$x.severity]//0)+1))),
			          by_tier:     (reduce $f[] as $x ({}; .[$x.confidence_tier] = ((.[$x.confidence_tier]//0)+1))) },
			  findings: ($f | sort_by(-.confidence_score)) }' "$ff" > "$out_json"
	else
		jq -n --arg scope "$scope" --arg gen "$gen" \
			'{meta:{scope:$scope,generated_at:$gen,total:0,by_severity:{},by_tier:{}},findings:[]}' > "$out_json"
	fi

	local total; total="$(jq -r '.meta.total' "$out_json")"

	# ---- Markdown ----
	{
		printf '# APEX Security Report\n\n'
		printf '%s\n' "- **Scope:** $scope"
		printf '%s\n' "- **Generated:** $gen"
		printf '%s\n\n' "- **Total findings:** $total"
		printf '> Every finding below is backed by stored evidence. Items marked NEEDS_REVIEW\n'
		printf '> require human validation and must NOT be reported as confirmed.\n\n'
		printf '## Summary by severity\n\n'
		jq -r '.meta.by_severity | to_entries[] | "- \(.key): \(.value)"' "$out_json" 2>/dev/null || true
		printf '\n## Summary by confidence\n\n'
		jq -r '.meta.by_tier | to_entries[] | "- \(.key): \(.value)"' "$out_json" 2>/dev/null || true
		printf '\n## Findings\n\n'
		if [[ "$total" == "0" ]]; then
			printf '_No findings were produced. This is a truthful empty result, not a failure._\n'
		else
			jq -r '.findings[] |
				"### [\(.severity|ascii_upcase)] \(.category) — \(.target)\n" +
				"- **Confidence:** \(.confidence_score)/100 (\(.confidence_tier))\n" +
				"- **Validation:** \(.validation_status)\n" +
				"- **Reasoning:** \(.reasoning)\n" +
				"- **Impact:** \(.impact)\n" +
				"- **Reproduction:** \(.reproduction)\n" +
				"- **Evidence refs:** \(.evidence|length)\n"' "$out_json"
		fi
		printf '\n## Run metadata\n\n'
		if [[ -f "$dir/reports/phase_durations.tsv" ]]; then
			printf 'Phase durations:\n\n'
			awk -F'\t' '{printf "- %s: %ss (rc=%s)\n",$1,$2,$3}' "$dir/reports/phase_durations.tsv" 2>/dev/null || true
			printf '\n'
		fi
		printf 'Optional tools detected:'
		{ local _t _f=""; for _t in subfinder httpx nuclei dnsx katana gau waybackurls dalfox subzy jsluice dig curl jq wafw00f ffuf sqlmap; do apex_have "$_t" && _f="$_f $_t"; done; printf '%s\n' "${_f:- none}"; }
		if [[ -f "$dir/reports/metrics.json" ]]; then
			printf '\n### Metrics\n\n```json\n'
			cat "$dir/reports/metrics.json"
			printf '\n```\n'
		fi
		if [[ -f "$dir/reports/changes.md" ]]; then
			printf '\n---\n\n'
			cat "$dir/reports/changes.md"
		fi
	} > "$out_md"

	# ---- HTML (self-contained, escaped by jq) ----
	{
		cat <<'HHEAD'
<!doctype html><html lang="en"><head><meta charset="utf-8">
<title>APEX Security Report</title>
<style>
body{font:14px/1.5 system-ui,sans-serif;margin:2rem;color:#111;background:#fafafa}
h1{margin:0 0 .25rem} .meta{color:#555;margin-bottom:1rem}
.card{background:#fff;border:1px solid #e3e3e3;border-radius:10px;padding:1rem;margin:.75rem 0}
.sev{display:inline-block;padding:.1rem .5rem;border-radius:6px;color:#fff;font-weight:600;font-size:12px}
.critical{background:#b00020}.high{background:#d84315}.medium{background:#f9a825;color:#111}
.low{background:#2e7d32}.info{background:#546e7a}
.tier{color:#555;font-size:12px} pre{white-space:pre-wrap;background:#f4f4f4;padding:.5rem;border-radius:6px}
</style></head><body>
HHEAD
		printf '<h1>APEX Security Report</h1>\n'
		printf '<div class="meta">Scope: %s &middot; Generated: %s &middot; Total: %s</div>\n' \
			"$(printf '%s' "$scope" | sed 's/&/\&amp;/g;s/</\&lt;/g')" "$gen" "$total"
		if [[ "$total" == "0" ]]; then
			printf '<div class="card">No findings (truthful empty result).</div>\n'
		else
			jq -r '.findings[] |
				@html "<div class=\"card\"><span class=\"sev \(.severity)\">\(.severity|ascii_upcase)</span> " +
				"<b>\(.category)</b> — \(.target) <span class=\"tier\">[\(.confidence_score)/100 \(.confidence_tier)]</span>" +
				"<p><b>Reasoning:</b> \(.reasoning)</p>" +
				"<p><b>Impact:</b> \(.impact)</p>" +
				"<p><b>Validation:</b> \(.validation_status)</p>" +
				"<pre><b>Reproduction:</b>\n\(.reproduction)</pre></div>"' "$out_json"
		fi
		printf '</body></html>\n'
	} > "$out_html"

	log_info "reports written: $out_json | $out_md | $out_html (findings=$total)"
	declare -g APEX_LAST_REPORT_JSON="$out_json"
	declare -g APEX_LAST_REPORT_MD="$out_md"
	declare -g APEX_LAST_REPORT_HTML="$out_html"
}

# ===== lib/native.sh =====
# APEX :: lib/native.sh
# NATIVE ENGINE — real, evidence-based analysis that needs NO external tools
# (only curl / dig / jq / awk / sed / grep). This is what makes APEX more than
# an "orchestrator": even when subfinder/httpx/nuclei are absent, these phases
# still produce genuine, evidence-backed findings. Nothing here fabricates a
# vulnerability; heuristic surfaces are emitted as NEEDS_REVIEW candidates.

# ---------------------------------------------------------------------------
# PURE ANALYZERS (no network) — unit-tested in tests/unit/test_native.sh
# ---------------------------------------------------------------------------

# _header_issues <hdrfile> -> lines "sev<TAB>score<TAB>key<TAB>reason"
# Reads a raw HTTP response-header dump (curl -D -) and reports weaknesses.
_header_issues() {
  local f="$1"; [[ -f "$f" ]] || return 0
  local h; h="$(tr -d '\r' < "$f")"
  grep -qiE '^strict-transport-security:' <<<"$h" || printf 'low\t40\tHSTS\tMissing Strict-Transport-Security header\n'
  grep -qiE '^content-security-policy:'   <<<"$h" || printf 'low\t42\tCSP\tMissing Content-Security-Policy header\n'
  grep -qiE '^x-content-type-options:[[:space:]]*nosniff' <<<"$h" || printf 'low\t35\tXCTO\tMissing X-Content-Type-Options: nosniff\n'
  if ! grep -qiE '^x-frame-options:' <<<"$h" && ! grep -qiE '^content-security-policy:.*frame-ancestors' <<<"$h"; then
    printf 'low\t45\tXFO\tMissing clickjacking protection (no X-Frame-Options, no CSP frame-ancestors)\n'
  fi
  grep -qiE '^referrer-policy:' <<<"$h" || printf 'info\t25\tReferrer-Policy\tMissing Referrer-Policy header\n'
  local srv; srv="$(grep -iE '^server:' <<<"$h" | head -1)"
  [[ "$srv" =~ [0-9]+\.[0-9]+ ]] && printf 'info\t28\tServer\tServer version disclosure: %s\n' "${srv#*: }"
  local xpb; xpb="$(grep -iE '^x-powered-by:' <<<"$h" | head -1)"
  [[ -n "$xpb" ]] && printf 'info\t28\tX-Powered-By\tTechnology/version disclosure: %s\n' "${xpb#*: }"
  local acao; acao="$(grep -iE '^access-control-allow-origin:' <<<"$h" | head -1 | awk '{print $2}' | tr -d '\r')"
  [[ "$acao" == "*" ]] && printf 'low\t45\tCORS\tPermissive CORS: Access-Control-Allow-Origin: *\n'
}

# _cookie_issues <hdrfile> -> lines "sev<TAB>score<TAB>key<TAB>reason"
_cookie_issues() {
  local f="$1"; [[ -f "$f" ]] || return 0
  local cookies; cookies="$(grep -iE '^set-cookie:' "$f")"
  [[ -n "$cookies" ]] || return 0
  local line name
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    line="$(tr -d '\r' <<<"$line")"
    name="$(sed -E 's/^[Ss]et-[Cc]ookie:[[:space:]]*([^=;]+)=.*/\1/' <<<"$line")"
    grep -qi 'httponly' <<<"$line" || printf 'low\t38\tCookie\tCookie %s missing HttpOnly flag\n' "$name"
    grep -qi 'secure'   <<<"$line" || printf 'low\t38\tCookie\tCookie %s missing Secure flag\n' "$name"
    grep -qi 'samesite' <<<"$line" || printf 'info\t30\tCookie\tCookie %s missing SameSite attribute\n' "$name"
  done <<< "$cookies"
}

# _fingerprint_tech <hdrfile> -> one technology token per line
_fingerprint_tech() {
  local f="$1"; [[ -f "$f" ]] || return 0
  local h; h="$(tr -d '\r' < "$f")"
  grep -qiE '^server:.*nginx'      <<<"$h" && echo nginx
  grep -qiE '^server:.*apache'     <<<"$h" && echo apache
  grep -qiE '^server:.*cloudflare|^cf-ray:' <<<"$h" && echo cloudflare
  grep -qiE '^x-powered-by:.*php|PHPSESSID' <<<"$h" && echo php
  grep -qiE 'JSESSIONID'           <<<"$h" && echo java
  grep -qiE 'laravel_session'      <<<"$h" && echo laravel
  grep -qiE 'wp-|wordpress'        <<<"$h" && echo wordpress
  grep -qiE '^x-aspnet-version:|ASP\.NET' <<<"$h" && echo aspnet
  return 0
}

# _subs_from_crtsh <crtsh.json> -> unique in-domain hostnames
_subs_from_crtsh() {
  local f="$1"; [[ -f "$f" ]] || return 0
  jq -r '.[]?|.name_value // empty' "$f" 2>/dev/null \
    | tr '[:upper:]' '[:lower:]' | tr ',' '\n' \
    | sed -E 's/^\*\.//; s/[[:space:]]//g' \
    | grep -E '^[a-z0-9._-]+\.[a-z]{2,}$' | sort -u
}

# _ssrf_candidate_params <url> -> param names that look like server-side fetch sinks
_ssrf_candidate_params() {
  local url="$1" q p k
  q="${url#*\?}"; [[ "$q" == "$url" ]] && return 0
  local IFS='&'
  for p in $q; do
    k="${p%%=*}"; k="${k,,}"
    case "$k" in
      url|uri|link|src|source|dest|destination|redirect|redir|return|returnurl|returnto|next|continue|target|to|out|view|page|path|file|feed|host|domain|site|image|img|imageurl|callback|fetch|load|proxy|forward|open|window|data|reference|ref)
        printf '%s\n' "$k" ;;
    esac
  done
}

# _idor_candidate <url> -> object-reference tokens (numeric/uuid/path id)
_idor_candidate() {
  local url="$1"
  grep -oE '[?&](id|user|userid|uid|account|acct|order|orderid|invoice|doc|docid|file|fileid|num|no|pid|gid|key|record)=[0-9]+' <<<"$url" | sed 's/^[?&]//'
  grep -oiE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' <<<"$url" | sed 's/^/uuid=/'
  grep -oE '/[0-9]{2,}(/|$)' <<<"$url" | tr -d '/' | sed 's/^/pathid=/'
  return 0
}

# _race_analyze <codes-file> -> "ANOMALY <n>" if >1 HTTP 2xx, else "OK <n>"
_race_analyze() {
  local f="$1" ok
  ok="$(grep -cE '^2[0-9][0-9]$' "$f" 2>/dev/null || true)"; ok="${ok:-0}"
  if (( ok > 1 )); then printf 'ANOMALY %s\n' "$ok"; else printf 'OK %s\n' "$ok"; fi
}

# ---------------------------------------------------------------------------
# NATIVE PHASES (network) — tool-independent, evidence-first
# ---------------------------------------------------------------------------

_native_cap_urls()  { cfg_get_default max_urls 2000; }
_native_cap_hosts() { cfg_get_default max_hosts 5000; }

# Native subdomain brute-force (fallback when subfinder is absent).
phase_subs_native() {
  _recon_ok || return 0
  _have subfinder && { log_info "[SUBn] subfinder present; native brute skipped"; return 0; }
  _have dig || { log_warn "[SUBn] dig missing; cannot brute-force subdomains natively"; return 0; }
  local words="www mail api dev develop development staging stage test testing admin portal app apps gateway gw vpn remote m mobile blog shop store cdn static assets img images cms auth login sso secure db sql mysql postgres ftp sftp smtp imap ns1 ns2 dns git gitlab github jenkins ci cd argo argocd k8s kube jira confluence wiki docs help support status monitor monitoring grafana kibana prometheus elastic internal intranet corp beta demo sandbox uat qa prod preprod prd stg api1 api2 v1 v2 backend front frontend dashboard panel manage manager account accounts billing pay payment payments"
  local seed w host n=0 cap; cap="$(_native_cap_hosts)"
  for seed in "${APEX_SEEDS[@]}"; do
    for w in $words; do
      (( n >= cap )) && break 2
      host="$w.$seed"
      if dig +short +time=2 +tries=1 "$host" A 2>/dev/null | grep -qE '^[0-9]'; then
        in_scope "$host" && { store_upsert_host "$host" >/dev/null 2>&1; n=$((n+1)); log_info "[SUBn] resolved $host"; }
      fi
    done
  done
  log_info "[SUBn] native brute complete (+$n hosts)"
}

# Native HTTP probe (fallback when httpx is absent).
phase_http_native() {
  _recon_ok || return 0
  _have httpx && return 0
  _have curl  || { log_warn "[P3n] curl missing; cannot probe hosts natively"; return 0; }
  local hl="$APEX_RUN_DIR/raw/hosts.txt"
  store_query hosts '.host' -r > "$hl" 2>/dev/null || true
  [[ -s "$hl" ]] || { log_info "[P3n] no hosts to probe"; return 0; }
  local h scheme url code title hdr body tmo n=0 cap; tmo="$(cfg_get timeout)"; cap="$(_native_cap_hosts)"
  while IFS= read -r h; do
    [[ -z "$h" ]] && continue
    (( n >= cap )) && break; n=$((n+1))
    in_scope "$h" || continue
    for scheme in https http; do
      url="$scheme://$h"
      hdr="$APEX_RUN_DIR/raw/probe_$(printf '%s' "$url" | apex_sha256).h"
      body="$APEX_RUN_DIR/raw/probe_$(printf '%s' "$url" | apex_sha256).b"
      code="$(curl -sS -o "$body" -D "$hdr" -w '%{http_code}' -L --max-time "$tmo" -A 'APEX-Recon/2' "$url" 2>/dev/null || echo 000)"
      [[ "$code" == "000" ]] && continue
      title="$(grep -oiE '<title>[^<]*</title>' "$body" 2>/dev/null | head -1 | sed -E 's/<[^>]+>//g')"
      store_put web "$(jq -cn --arg u "$url" --arg c "$code" --arg t "$title" '{url:$u,status_code:($c|tonumber?//0),title:$t,source:"native-curl"}')" >/dev/null 2>&1 || true
      break
    done
  done < "$hl"
  log_info "[P3n] native probe complete; live web assets: $(store_count web)"
}

# Native security-header + cookie + tech analysis (ALWAYS runs with curl; no
# external tools required). This alone yields real findings on any live target.
phase_headers_native() {
  _recon_ok || { log_warn "[HDR] header analysis skipped (consent required)"; return 0; }
  _have curl || { log_warn "[HDR] curl missing; skipping native header analysis"; return 0; }
  local list="$APEX_RUN_DIR/raw/hdrn_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || { log_info "[HDR] no web targets"; return 0; }
  local u hdr tmo sev score key reason ev tech n=0 cap; tmo="$(cfg_get timeout)"; cap="$(_native_cap_urls)"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    (( n >= cap )) && break; n=$((n+1))
    url_in_scope "$u" || continue
    hdr="$APEX_RUN_DIR/raw/hdrn_$(printf '%s' "$u" | apex_sha256).txt"
    apex_exec "hdr:$u" "$tmo" "$hdr" -- curl -sS -D - -o /dev/null -L --max-time "$tmo" -A 'APEX-Recon/2' "$u" || true
    [[ -s "$hdr" ]] || continue
    local _hi _ci
    _hi="$(_header_issues "$hdr")"; _ci="$(_cookie_issues "$hdr")"
    while IFS=$'\t' read -r sev score key reason; do
      [[ -z "$sev" ]] && continue
      ev="$(record_evidence headers "$reason ($u)" "$(cat "$hdr")")"
      emit_finding "missing-security-header" "$u" "$sev" "$score" \
        "$reason" "Weakens the site's defense-in-depth posture." \
        "tool-observed" "curl -I $u   # inspect response headers" \
        "[\"$ev\"]" "[\"header-analysis\",\"$key\"]" >/dev/null
    done <<< "$_hi"
    while IFS=$'\t' read -r sev score key reason; do
      [[ -z "$sev" ]] && continue
      ev="$(record_evidence cookie "$reason ($u)" "$(grep -iE '^set-cookie:' "$hdr")")"
      emit_finding "insecure-cookie" "$u" "$sev" "$score" \
        "$reason" "Cookies without protective flags are exposed to theft or CSRF." \
        "tool-observed" "curl -I $u   # inspect Set-Cookie flags" \
        "[\"$ev\"]" "[\"cookie-analysis\",\"$key\"]" >/dev/null
    done <<< "$_ci"
    tech="$(_fingerprint_tech "$hdr" | paste -sd, -)"
    [[ -n "$tech" ]] && log_info "[HDR] $u tech: $tech"
  done < "$list"
  log_info "[HDR] native header/cookie/tech analysis complete"
}

# ---------------------------------------------------------------------------
# REAL implementations of the former placeholders: SSRF / Access-Control / Race
# ---------------------------------------------------------------------------

# P7 SSRF: passive, evidence-based candidate surface + gated active OOB harness.
phase_ssrf() {
  _recon_ok || { log_warn "[P7] SSRF surface scan skipped (consent required)"; return 0; }
  local list="$APEX_RUN_DIR/raw/ssrf_urls.txt" cap; cap="$(_native_cap_urls)"
  store_query urls '.url' -r 2>/dev/null | sort -u | head -n "$cap" > "$list" || true
  local u params ev n=0
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    params="$(_ssrf_candidate_params "$u" | paste -sd, -)"
    [[ -z "$params" ]] && continue
    ev="$(record_evidence ssrf-candidate "parameter(s) suggest server-side fetch: $params" "$u")"
    emit_finding "ssrf-candidate" "$u" "medium" 30 \
      "Parameter(s) [$params] commonly proxy a server-side request (SSRF sink candidate)." \
      "If the server fetches attacker-controlled URLs, internal services or cloud metadata may be reachable." \
      "needs-human" \
      "Test $params with an OOB collector (e.g. interactsh) against internal targets; confirm out-of-band interaction." \
      "[\"$ev\"]" "[\"parameter-heuristic\",\"unverified\"]" >/dev/null
    n=$((n+1))
  done < "$list"
  if _active_ok && cfg_bool enable_ssrf; then
    if _have interactsh-client; then
      log_info "[P7] active SSRF harness available (interactsh-client present); configure your OOB domain to fire probes."
    else
      log_warn "[P7] active SSRF requested but interactsh-client missing; only passive candidates emitted (no blind probes)."
    fi
  fi
  log_info "[P7] SSRF surface: $n candidate(s) flagged for manual verification"
}

# P8 Access-Control: IDOR/BAC candidate surface + optional real differential test.
_access_differential() {
  local list="$1" sa="$2" sb="$3" u ca cb ev tmo n=0; tmo="$(cfg_get timeout)"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    [[ -n "$(_idor_candidate "$u")" ]] || continue
    ca="$(curl -sS -o /dev/null -w '%{http_code}' --max-time "$tmo" -H "Cookie: $sa" "$u" 2>/dev/null || echo 000)"
    cb="$(curl -sS -o /dev/null -w '%{http_code}' --max-time "$tmo" -H "Cookie: $sb" "$u" 2>/dev/null || echo 000)"
    if [[ "$ca" == "200" && "$cb" == "200" ]]; then
      ev="$(record_evidence idor-differential "both sessions received HTTP 200 for $u" "A=$ca B=$cb $u")"
      emit_finding "broken-access-control" "$u" "high" 70 \
        "Two distinct user sessions BOTH received HTTP 200 for an object-referencing URL." \
        "Potential horizontal privilege escalation (IDOR): user B may access user A's object." \
        "tool-observed" \
        "Repeat with the second session cookie and diff the response body against the first user's." \
        "[\"$ev\"]" "[\"differential-200\",\"needs-body-diff\"]" >/dev/null
      n=$((n+1))
    fi
  done < "$list"
  log_info "[P8] differential access test: $n potential IDOR(s)"
}

phase_access() {
  _recon_ok || { log_warn "[P8] access-control scan skipped (consent required)"; return 0; }
  local list="$APEX_RUN_DIR/raw/idor_urls.txt" cap; cap="$(_native_cap_urls)"
  store_query urls '.url' -r 2>/dev/null | sort -u | head -n "$cap" > "$list" || true
  local u refs ev n=0
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    refs="$(_idor_candidate "$u" | paste -sd, -)"
    [[ -z "$refs" ]] && continue
    ev="$(record_evidence idor-candidate "direct object reference(s): $refs" "$u")"
    emit_finding "access-control-candidate" "$u" "medium" 30 \
      "URL exposes direct object reference(s) [$refs] — a common IDOR/BAC surface." \
      "If per-object authorization is missing, another user's data may be accessible." \
      "needs-human" \
      "Replay $u authenticated as a different low-privilege user (or with no session) and compare responses." \
      "[\"$ev\"]" "[\"object-reference-heuristic\",\"unverified\"]" >/dev/null
    n=$((n+1))
  done < "$list"
  local sa sb; sa="$(cfg_get session_a)"; sb="$(cfg_get session_b)"
  if _active_ok && [[ -n "$sa" && -n "$sb" ]] && _have curl; then
    _access_differential "$list" "$sa" "$sb"
  fi
  log_info "[P8] access-control surface: $n candidate(s) flagged for manual verification"
}

# P13 Race-condition: real concurrent-burst harness (opt-in, scoped, no blind fire).
phase_race() {
  if ! { _active_ok && cfg_bool enable_race; }; then
    log_warn "[P13] race-condition test skipped (needs enable_active + enable_race + authorization)"; return 0
  fi
  local rurl; rurl="$(cfg_get race_url)"
  [[ -n "$rurl" ]] || { log_warn "[P13] enabled but no race_url configured; nothing fired (no blind requests)."; return 0; }
  _have curl || { log_warn "[P13] curl missing; cannot run race harness"; return 0; }
  url_in_scope "$rurl" || { log_warn "[P13] race_url is out of scope; refusing to fire."; return 0; }
  local n; n="$(cfg_get_default race_count 20)"
  local codes="$APEX_RUN_DIR/raw/race_codes.txt" tmo i sess; tmo="$(cfg_get timeout)"; sess="$(cfg_get session_a)"
  : > "$codes"
  local -a extra=(); [[ -n "$sess" ]] && extra=(-H "Cookie: $sess")
  log_warn "[P13] firing $n concurrent requests at $rurl (single-use-operation race test)"
  local -a pids=()
  for ((i=0;i<n;i++)); do
    { curl -sS -o /dev/null -w '%{http_code}\n' --max-time "$tmo" "${extra[@]}" "$rurl" 2>/dev/null || echo 000; } >> "$codes" &
    pids+=("$!")
  done
  wait "${pids[@]}" 2>/dev/null || true
  local verdict succ; verdict="$(_race_analyze "$codes")"; succ="${verdict##* }"
  if [[ "$verdict" == ANOMALY* ]]; then
    local ev; ev="$(record_evidence race "$succ concurrent 2xx responses at $rurl" "$(sort "$codes" | uniq -c)")"
    emit_finding "race-condition" "$rurl" "high" 68 \
      "$succ of $n concurrent requests succeeded (HTTP 2xx) on an operation expected to be single-use." \
      "A race window may allow double-spend / limit bypass (coupon reuse, balance manipulation, etc.)." \
      "tool-observed" \
      "Re-run the concurrent burst and confirm the side effect actually occurred more than once." \
      "[\"$ev\"]" "[\"concurrent-2xx=$succ\"]" >/dev/null
  else
    log_info "[P13] race harness: only $succ success(es); no anomaly detected."
  fi
}

# ===== lib/pipeline.sh =====
# APEX :: lib/pipeline.sh
# The full 16-phase recon & assessment pipeline. Every phase is evidence-first
# and degrades gracefully when a tool is missing (logs a skip, never crashes,
# never fabricates). Target-touching phases require consent; payload/intrusive
# phases additionally require enable_active.

declare -ga APEX_SEEDS=()

# ---- consent gates -----------------------------------------------------------
_recon_ok()  { cfg_bool authorized || cfg_bool local_lab || (( ${APEX_SCOPE_ALLOW_ALL:-0} == 1 )); }
_active_ok() { _recon_ok && cfg_bool enable_active; }
_have()      { apex_have "$1"; }

# run_phase <phase_fn>: orchestration wrapper. Supports --dry-run and --resume,
# records per-phase duration, and logs an explicit DEGRADED line (never a silent
# '|| true') when a phase returns non-zero. The pipeline continues regardless,
# but every failure is surfaced.
APEX_PHASE_DURATIONS=""
run_phase() {
  local fn="$1" rc=0 t0 t1
  declare -F "$fn" >/dev/null 2>&1 || { log_error "run_phase: no such phase '$fn'"; return 0; }
  if cfg_bool resume && [[ -n "${APEX_STATE_DIR:-}" && -f "$APEX_STATE_DIR/$fn.done" ]]; then
    log_info "[skip] $fn (resume: already completed)"; return 0
  fi
  if cfg_bool dry_run; then
    log_info "[dry-run] would execute: $fn"; return 0
  fi
  t0="$(date +%s)"
  "$fn" || { rc=$?; log_warn "phase '$fn' DEGRADED (rc=$rc) — continuing (failure logged, not swallowed)"; }
  t1="$(date +%s)"
  APEX_PHASE_DURATIONS+="$fn=$((t1-t0))s "
  [[ -n "${APEX_RUN_DIR:-}" ]] && printf '%s\t%s\t%s\n' "$fn" "$((t1-t0))" "$rc" >> "$APEX_RUN_DIR/reports/phase_durations.tsv" 2>/dev/null || true
  [[ -n "${APEX_STATE_DIR:-}" ]] && : > "$APEX_STATE_DIR/$fn.done" 2>/dev/null || true
  return 0
}

# PCRE portability (FIX: 'grep -oP' is unavailable on BSD/macOS grep).
# Order of preference: PCRE grep -> ripgrep -> ERE grep (with (?i) stripped).
_APEX_PCRE=""
_pcre_ok() { printf 'x' | grep -qP 'x' 2>/dev/null; }
_secret_grep() { # <regex> <file> -> matching substrings, one per line
  local re="$1" f="$2"
  [[ -s "$f" ]] || return 0
  if [[ -z "$_APEX_PCRE" ]]; then if _pcre_ok; then _APEX_PCRE=1; else _APEX_PCRE=0; fi; fi
  if [[ "$_APEX_PCRE" == 1 ]]; then
    grep -aoP "$re" "$f" 2>/dev/null
  elif command -v rg >/dev/null 2>&1; then
    rg -aoP "$re" "$f" 2>/dev/null
  else
    grep -aoEi "${re//'(?i)'/}" "$f" 2>/dev/null
  fi
}

_fetch() { # url outfile  -> passive GET (redacted on storage by callers)
  _have curl || return 1
  local tmo; tmo="$(cfg_get timeout)"
  apex_exec "GET:$1" "$tmo" "$2" -- curl -sS -L --max-time "$tmo" -A "APEX-Recon/2" "$1"
}

# ---- P1: subdomain enumeration (passive OSINT + tools) -----------------------
phase_subdomains() {
  log_info "[P1] subdomain enumeration"
  local raw="$APEX_RUN_DIR/raw/subs_all.txt"; : > "$raw"
  local d out
  for d in "${APEX_SEEDS[@]}"; do
    if _have subfinder; then
      out="$APEX_RUN_DIR/raw/subfinder_$d.txt"
      apex_exec "subfinder:$d" 300 "$out" -- subfinder -silent -all -d "$d" || true
      [[ -s "$out" ]] && cat "$out" >> "$raw"
    fi
    if _have assetfinder; then
      out="$APEX_RUN_DIR/raw/assetfinder_$d.txt"
      apex_exec "assetfinder:$d" 300 "$out" -- assetfinder --subs-only "$d" || true
      [[ -s "$out" ]] && cat "$out" >> "$raw"
    fi
    if _have amass; then
      out="$APEX_RUN_DIR/raw/amass_$d.txt"
      apex_exec "amass:$d" 600 "$out" -- amass enum -passive -norecursive -d "$d" || true
      [[ -s "$out" ]] && cat "$out" >> "$raw"
    fi
    if _have curl; then
      out="$APEX_RUN_DIR/raw/crtsh_$d.json"
      apex_exec "crtsh:$d" 60 "$out" -- curl -sS --max-time 60 "https://crt.sh/?q=%25.$d&output=json" || true
      if [[ -s "$out" ]]; then
        jq -r '.[].name_value' "$out" 2>/dev/null | sed 's/\*\.//g' >> "$raw" || true
      fi
    fi
    printf '%s\n' "$d" >> "$raw"
  done
  # normalise + scope filter + persist (temp file; no process substitution)
  local sorted="$APEX_RUN_DIR/raw/subs_sorted.txt" host
  tr 'A-Z' 'a-z' < "$raw" | tr -d '\r' | sed 's/[[:space:]]//g' | grep -E '^[a-z0-9.-]+$' | sort -u > "$sorted" || true
  while IFS= read -r host; do
    [[ -z "$host" ]] && continue
    in_scope "$host" || continue
    store_upsert_host "$host" >/dev/null
  done < "$sorted"
  log_info "[P1] hosts in scope: $(store_count hosts)"
}

# ---- P2: DNS resolution ------------------------------------------------------
phase_dns() {
  _recon_ok || { log_warn "[P2] dns resolve skipped (consent required)"; return 0; }
  local hl="$APEX_RUN_DIR/raw/hosts.txt"
  store_query hosts '.host' -r > "$hl" 2>/dev/null || true
  [[ -s "$hl" ]] || { log_info "[P2] no hosts to resolve"; return 0; }
  if _have dnsx; then
    local out="$APEX_RUN_DIR/raw/dnsx.json"
    apex_exec dnsx 300 "$out" -- dnsx -silent -a -resp -json -l "$hl" || true
    log_info "[P2] dnsx completed ($(wc -l < "$out" 2>/dev/null || echo 0) records)"
  else
    log_warn "[P2] dnsx missing; skipping active resolution"
  fi
}

# ---- P3: live host probing + fingerprint ------------------------------------
phase_http() {
  _recon_ok || { log_warn "[P3] http probe skipped (consent required)"; return 0; }
  local hl="$APEX_RUN_DIR/raw/hosts.txt"
  store_query hosts '.host' -r > "$hl" 2>/dev/null || true
  [[ -s "$hl" ]] || { log_info "[P3] no hosts"; return 0; }
  _have httpx || { log_warn "[P3] httpx missing; skipping"; return 0; }
  local out="$APEX_RUN_DIR/raw/httpx.jsonl"
  apex_exec httpx 600 "$out" -- httpx -silent -json -td -sc -title -server -rl "$(cfg_get rate)" -t "$(cfg_get threads)" -l "$hl" || true
  [[ -s "$out" ]] || { log_info "[P3] no live hosts"; return 0; }
  local line url
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    url="$(printf '%s' "$line" | jq -r '.url // empty' 2>/dev/null)"
    [[ -z "$url" ]] && continue
    url_in_scope "$url" || continue
    store_put web "$line" >/dev/null 2>&1 || store_put web "$(jq -cn --arg u "$url" '{url:$u}')" >/dev/null
  done < "$out"
  log_info "[P3] live web assets: $(store_count web)"
}

# ---- P4: deep crawl + URL collection ----------------------------------------
phase_crawl() {
  _recon_ok || { log_warn "[P4] crawl skipped (consent required)"; return 0; }
  local seeds="$APEX_RUN_DIR/raw/web_urls.txt"
  store_query web '.url' -r > "$seeds" 2>/dev/null || true
  [[ -s "$seeds" ]] || { store_query hosts '.host' -r 2>/dev/null | sed 's#^#https://#' > "$seeds" || true; }
  [[ -s "$seeds" ]] || { log_info "[P4] no seeds"; return 0; }
  local out d
  if _have katana; then
    out="$APEX_RUN_DIR/raw/katana.txt"
    apex_exec katana 600 "$out" -- katana -silent -jc -d "$(cfg_get_default katana_depth 3)" -list "$seeds" || true
    _ingest_urls "$out"
  fi
  if _have gau; then
    for d in "${APEX_SEEDS[@]}"; do
      out="$APEX_RUN_DIR/raw/gau_$d.txt"
      apex_exec "gau:$d" 300 "$out" -- gau --subs "$d" || true
      _ingest_urls "$out"
    done
  fi
  if _have waybackurls; then
    for d in "${APEX_SEEDS[@]}"; do
      out="$APEX_RUN_DIR/raw/wb_$d.txt"
      apex_exec "wayback:$d" 300 "$out" -- waybackurls "$d" || true
      _ingest_urls "$out"
    done
  fi
  if _have gospider; then
    out="$APEX_RUN_DIR/raw/gospider.txt"
    apex_exec gospider 600 "$out" -- gospider -q -S "$seeds" || true
    _ingest_urls "$out"
  fi
  log_info "[P4] urls collected: $(store_count urls)"
}

_ingest_urls() {
  local f="$1" u host
  [[ -s "$f" ]] || return 0
  local clean="$f.clean"
  grep -oE 'https?://[^ \"'\''<>]+' "$f" 2>/dev/null | sort -u > "$clean" || true
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    host="$(url_host "$u")"
    in_scope "$host" || continue
    store_put urls "$(jq -cn --arg u "$u" '{url:$u}')" >/dev/null
  done < "$clean"
}

# ---- P5: JavaScript analysis + secret detection (pure-bash, always works) ----
# name|severity|score|regex  (strong unique formats get high confidence;
# generic patterns stay low to avoid false positives)
declare -ga APEX_SECRET_PATTERNS=(
  "AWS Access Key|high|88|AKIA[0-9A-Z]{16}"
  "AWS Secret Key|high|70|(?i)aws(.{0,20})?(secret|sk)[^A-Za-z0-9/+=]{0,3}[A-Za-z0-9/+=]{40}"
  "GCP API Key|high|85|AIza[0-9A-Za-z_-]{35}"
  "Stripe Live Key|critical|92|sk_live_[0-9a-zA-Z]{24,}"
  "Stripe Restricted Key|high|85|rk_live_[0-9a-zA-Z]{24,}"
  "GitHub Token|high|85|gh[pousr]_[A-Za-z0-9]{20,}"
  "Slack Token|high|82|xox[baprs]-[A-Za-z0-9-]{10,}"
  "Google OAuth|medium|60|ya29\\.[0-9A-Za-z_-]+"
  "JWT|medium|55|eyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{4,}\\.[A-Za-z0-9_-]{4,}"
  "Private Key Block|critical|90|-----BEGIN [A-Z ]*PRIVATE KEY-----"
  "Twilio SID|medium|60|AC[0-9a-fA-F]{32}"
  "SendGrid Key|high|85|SG\\.[A-Za-z0-9_-]{16,}\\.[A-Za-z0-9_-]{16,}"
  "Mailgun Key|high|80|key-[0-9a-zA-Z]{32}"
  "Generic Secret Assignment|low|30|(?i)(api[_-]?key|secret|passwd|password|token)[\"'\'' :=]{1,4}[^\"'\'' ,;]{8,}"
)

phase_js_secrets() {
  _recon_ok || { log_warn "[P5] js/secret scan skipped (consent required)"; return 0; }
  local urls="$APEX_RUN_DIR/raw/js_urls.txt"
  store_query urls '.url' -r 2>/dev/null | grep -iE '\.js([?#]|$)' | sort -u > "$urls" || true
  # also scan web bodies if no JS urls
  [[ -s "$urls" ]] || { log_info "[P5] no JS URLs discovered"; return 0; }
  local u f i=0
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    f="$APEX_RUN_DIR/raw/js_$i.body"; i=$((i+1))
    _fetch "$u" "$f" || continue
    _scan_secrets "$f" "$u"
    if _have jsluice; then
      apex_exec "jsluice:$u" 60 "$f.jsl" -- jsluice urls -R "$f" || true
      _ingest_urls "$f.jsl"
    fi
  done < "$urls"
  log_info "[P5] JavaScript analysed: $i file(s)"
}

_scan_secrets() {
  local f="$1" src="$2" p name rest sev score re ev matches line
  [[ -s "$f" ]] || return 0
  for p in "${APEX_SECRET_PATTERNS[@]}"; do
    name="${p%%|*}"; rest="${p#*|}"
    sev="${rest%%|*}"; rest="${rest#*|}"
    score="${rest%%|*}"; re="${rest#*|}"
    matches="$f.match"
    _secret_grep "$re" "$f" | sort -u > "$matches" || true
    [[ -s "$matches" ]] || continue
    while IFS= read -r line; do
      [[ -z "$line" ]] && continue
      ev="$(record_evidence js-secret "$name found in $src" "$line")"
      emit_finding "secret-exposure" "$src" "$sev" "$score" \
        "A string matching the '$name' format was served from an in-scope JavaScript asset." \
        "Exposed $name may grant unauthorized access to the associated service or data." \
        "needs-human" \
        "Fetch $src and locate the $name pattern (value stored redacted in evidence). Validate the key is live before reporting." \
        "[\"$ev\"]" "[\"served-in-scope\",\"format-match\"]" >/dev/null
    done < "$matches"
  done
}

# ---- P6: Nuclei automated vulnerability scan --------------------------------
phase_nuclei() {
  _recon_ok || { log_warn "[P6] nuclei skipped (consent required)"; return 0; }
  _have nuclei || { log_warn "[P6] nuclei missing; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/nuclei_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || store_query hosts '.host' -r 2>/dev/null | sed 's#^#https://#' > "$list"
  [[ -s "$list" ]] || { log_info "[P6] no targets"; return 0; }
  local out="$APEX_RUN_DIR/raw/nuclei.jsonl"
  local sev="info,low,medium,high,critical"
  # Non-active by default; intrusive templates only when enable_active.
  local extra=(-severity "$sev" -stats -silent -jsonl -rl "$(cfg_get rate)" -c "$(cfg_get threads)")
  _active_ok || extra+=(-exclude-tags intrusive,dos,fuzz)
  apex_exec nuclei 1200 "$out" -- nuclei -l "$list" "${extra[@]}" || true
  [[ -s "$out" ]] || { log_info "[P6] nuclei produced no findings"; return 0; }
  local line tid sv url name ev
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    tid="$(printf '%s' "$line" | jq -r '."template-id" // .templateID // empty' 2>/dev/null)"
    sv="$(printf '%s' "$line" | jq -r '.info.severity // "info"' 2>/dev/null)"
    url="$(printf '%s' "$line" | jq -r '."matched-at" // .host // empty' 2>/dev/null)"
    name="$(printf '%s' "$line" | jq -r '.info.name // ."template-id" // "nuclei"' 2>/dev/null)"
    [[ -z "$url" ]] && continue
    url_in_scope "$url" || continue
    ev="$(record_evidence nuclei-match "$name ($tid) at $url" "$line")"
    emit_finding "nuclei:$tid" "$url" "$sv" 80 \
      "Nuclei template '$tid' matched. Template severity: $sv." \
      "See template metadata; impact depends on the specific template." \
      "tool-matched" \
      "Re-run: nuclei -id $tid -u $url  (confirm the match is a true positive)." \
      "[\"$ev\"]" "[\"nuclei-template-match\"]" >/dev/null
  done < "$out"
  log_info "[P6] nuclei findings ingested"
}

# ---- P7: SSRF (intrusive) ----------------------------------------------------
# phase_ssrf is defined in lib/native.sh (real, evidence-based implementation).

# ---- P8: Access control / IDOR / JWT (careful) -------------------------------
# phase_access is defined in lib/native.sh (real, evidence-based implementation).

# ---- P9: XSS (intrusive) -----------------------------------------------------
# Pure-bash reflected-XSS probe (fallback when dalfox is absent). Injects a
# unique benign HTML-tag marker into each query parameter and only reports when
# the marker is reflected UNENCODED in an HTML response -> low false positives,
# and always marked needs-human (never auto-CONFIRMED).
_xss_reflection_probe() {
  _have curl || { log_warn "[P9] curl missing; skipping reflection probe"; return 0; }
  local list="$APEX_RUN_DIR/raw/xssrefl_targets.txt"
  store_query urls '.url' -r 2>/dev/null | grep -E '\?[^ ]+=' | sort -u | head -n "$(cfg_get_default max_urls 2000)" > "$list" || true
  [[ -s "$list" ]] || { log_info "[P9] no parameterised URLs for reflection probe"; return 0; }
  local u marker inj test body ctype ev tmo; tmo="$(cfg_get timeout)"
  marker="apxr${RANDOM}${RANDOM}z"; inj="${marker}<x>"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    test="$(printf '%s' "$u" | sed -E "s#=[^&]*#=${inj}#g")"
    body="$(curl -sS -L --max-time "$tmo" -A 'APEX-Recon/2' "$test" 2>/dev/null)" || continue
    ctype="$(curl -sS -o /dev/null -w '%{content_type}' -L --max-time "$tmo" "$test" 2>/dev/null || true)"
    if grep -qF "$inj" <<<"$body" && grep -qiE 'text/html' <<<"$ctype"; then
      ev="$(record_evidence xss-reflection "unencoded reflection of $inj at $u" "$(grep -oF "$inj" <<<"$body" | head -1)")"
      emit_finding "reflected-input" "$u" "medium" 60 \
        "An injected HTML-tag marker was reflected UNENCODED in an HTML response — a strong reflected-XSS indicator." \
        "Potential reflected XSS: attacker-controlled markup/script in a victim session." \
        "needs-human" \
        "Request the URL with the value replaced by ${inj} and confirm the tag reflects unencoded, then build a working XSS proof." \
        "[\"$ev\"]" "[\"marker-reflected\",\"html-context\",\"unencoded\"]" >/dev/null
    fi
  done < "$list"
  log_info "[P9] reflection probe (dalfox-free fallback) complete"
}

phase_xss() {
  _active_ok || { log_warn "[P9] XSS skipped (needs enable_active + authorization)"; return 0; }
  _have dalfox || { _xss_reflection_probe; return 0; }
  local list="$APEX_RUN_DIR/raw/xss_targets.txt"
  store_query urls '.url' -r 2>/dev/null | grep -E '\?' | sort -u > "$list" || true
  [[ -s "$list" ]] || { log_info "[P9] no parameterised URLs"; return 0; }
  local out="$APEX_RUN_DIR/raw/dalfox.jsonl"
  apex_exec dalfox 1200 "$out" -- dalfox file "$list" --format jsonl --silence || true
  [[ -s "$out" ]] || { log_info "[P9] no XSS confirmed"; return 0; }
  local line url ev
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    url="$(printf '%s' "$line" | jq -r '.data // .url // empty' 2>/dev/null)"
    [[ -z "$url" ]] && continue
    url_in_scope "$url" || continue
    ev="$(record_evidence dalfox "XSS at $url" "$line")"
    emit_finding "xss" "$url" "high" 85 \
      "dalfox verified a reflected/DOM XSS vector." \
      "Attacker-controlled script execution in a victim browser session." \
      "tool-verified" \
      "Reproduce with the dalfox proof URL stored in evidence." \
      "[\"$ev\"]" "[\"dalfox-verified\"]" >/dev/null
  done < "$out"
}

# ---- P10: CORS + security headers (lightweight active GET) -------------------
phase_cors_headers() {
  _recon_ok || { log_warn "[P10] header/CORS checks skipped (consent required)"; return 0; }
  _have curl || { log_warn "[P10] curl missing; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/hdr_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || { log_info "[P10] no web targets"; return 0; }
  local u hdr acao acac ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    hdr="$APEX_RUN_DIR/raw/hdr_$(printf '%s' "$u" | apex_sha256).txt"
    apex_exec "cors:$u" "$tmo" "$hdr" -- curl -sS -D - -o /dev/null --max-time "$tmo" -H "Origin: https://apex-evil.example" "$u" || true
    [[ -s "$hdr" ]] || continue
    acao="$(grep -i '^access-control-allow-origin:' "$hdr" | tr -d '\r' | awk '{print $2}')"
    acac="$(grep -i '^access-control-allow-credentials:' "$hdr" | tr -d '\r' | awk '{print $2}')"
    if [[ "$acao" == "https://apex-evil.example" && "${acac,,}" == "true" ]]; then
      ev="$(record_evidence cors "reflected Origin with credentials at $u" "$(cat "$hdr")")"
      emit_finding "cors-misconfiguration" "$u" "high" 82 \
        "Server reflected an arbitrary Origin AND set Allow-Credentials: true." \
        "Cross-origin theft of authenticated data." \
        "tool-verified" \
        "curl -H 'Origin: https://apex-evil.example' -I $u  and observe the reflected ACAO + ACAC:true." \
        "[\"$ev\"]" "[\"origin-reflected\",\"credentials-true\"]" >/dev/null
    fi
    # missing security headers (informational, low confidence)
    if ! grep -qi '^strict-transport-security:' "$hdr"; then
      ev="$(record_evidence headers "missing HSTS at $u" "$(cat "$hdr")")"
      emit_finding "missing-security-header" "$u" "low" 40 \
        "Response is missing Strict-Transport-Security." \
        "Weakens protection against protocol downgrade / MITM." \
        "tool-observed" \
        "curl -I $u ; note the absence of the HSTS header." \
        "[\"$ev\"]" "[\"header-absent\"]" >/dev/null
    fi
  done < "$list"
}

# ---- P11: Open redirect (intrusive param injection) --------------------------
phase_open_redirect() {
  _active_ok || { log_warn "[P11] open-redirect skipped (needs enable_active + authorization)"; return 0; }
  _have curl || return 0
  local list="$APEX_RUN_DIR/raw/or_targets.txt"
  store_query urls '.url' -r 2>/dev/null | grep -iE '(redirect|url|next|return|dest|continue)=' | sort -u > "$list" || true
  [[ -s "$list" ]] || { log_info "[P11] no redirect params"; return 0; }
  local u test loc ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    test="$(printf '%s' "$u" | sed -E 's#(=)(https?%3A%2F%2F[^&]*|[^&]*)#\\1https://apex-evil.example#I')"
    loc="$APEX_RUN_DIR/raw/or_$(printf '%s' "$u" | apex_sha256).txt"
    apex_exec "openredir:$u" "$tmo" "$loc" -- curl -sS -D - -o /dev/null --max-time "$tmo" "$test" || true
    if grep -iqE '^location:\\s*https?://apex-evil\\.example' "$loc" 2>/dev/null; then
      ev="$(record_evidence open-redirect "external redirect at $u" "$(cat "$loc")")"
      emit_finding "open-redirect" "$u" "medium" 80 \
        "A redirect parameter forwarded to an attacker-controlled external host." \
        "Phishing, OAuth token theft, filter bypass." \
        "tool-verified" \
        "Request $test and observe Location: https://apex-evil.example" \
        "[\"$ev\"]" "[\"location-external\"]" >/dev/null
    fi
  done < "$list"
}

# ---- P12: API security surface ----------------------------------------------
phase_api() {
  _recon_ok || { log_warn "[P12] API discovery skipped (consent required)"; return 0; }
  _have curl || return 0
  local hosts="$APEX_RUN_DIR/raw/api_hosts.txt"
  store_query web '.url' -r > "$hosts" 2>/dev/null || true
  [[ -s "$hosts" ]] || { log_info "[P12] no web assets"; return 0; }
  local paths=("/swagger.json" "/openapi.json" "/api-docs" "/v2/api-docs" "/graphql" "/.well-known/openid-configuration")
  local base p url code ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r base; do
    [[ -z "$base" ]] && continue
    url_in_scope "$base" || continue
    base="${base%/}"
    for p in "${paths[@]}"; do
      url="$base$p"
      code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time "$tmo" "$url" 2>/dev/null || echo 000)"
      if [[ "$code" == "200" ]]; then
        ev="$(record_evidence api-doc "exposed $p ($code) at $url" "HTTP $code $url")"
        emit_finding "api-exposure" "$url" "low" 55 \
          "An API definition/endpoint responded 200: $p" \
          "Exposed API schema aids attackers in mapping sensitive endpoints." \
          "tool-observed" \
          "curl $url  (verify it returns a real schema/endpoint, not a generic page)." \
          "[\"$ev\"]" "[\"http-200\"]" >/dev/null
      fi
    done
  done < "$hosts"
}

