# ---- P14: Subdomain takeover -------------------------------------------------
phase_takeover() {
  _recon_ok || { log_warn "[P14] takeover check skipped (consent required)"; return 0; }
  local hl="$APEX_RUN_DIR/raw/hosts.txt"
  store_query hosts '.host' -r > "$hl" 2>/dev/null || true
  [[ -s "$hl" ]] || { log_info "[P14] no hosts"; return 0; }
  if _have subzy; then
    local out="$APEX_RUN_DIR/raw/subzy.txt"
    apex_exec subzy 600 "$out" -- subzy run --targets "$hl" --hide_fails || true
    local line host ev
    while IFS= read -r line; do
      printf '%s' "$line" | grep -qiE 'VULNERABLE' || continue
      host="$(printf '%s' "$line" | grep -oE '[a-z0-9.-]+\\.[a-z]{2,}' | head -1)"
      [[ -z "$host" ]] && continue
      in_scope "$host" || continue
      ev="$(record_evidence takeover "subzy flagged $host" "$line")"
      emit_finding "subdomain-takeover" "$host" "high" 85 \
        "subzy identified a dangling DNS record pointing to an unclaimed service." \
        "An attacker can claim the service and serve content on your subdomain." \
        "tool-verified" \
        "Re-run: subzy run --target $host ; then confirm the fingerprint before claiming." \
        "[\"$ev\"]" "[\"subzy-vulnerable\"]" >/dev/null
    done < "$out"
  else
    log_warn "[P14] subzy missing; skipping (no unverified takeover claims made)"
  fi
}

# ---- P15: correlation, dedup, risk prioritisation ---------------------------
phase_triage() {
  log_info "[P15] correlation + risk prioritisation"
  local ff="$APEX_RUN_DIR/db/findings.ndjson"
  [[ -f "$ff" ]] || { log_info "[P15] no findings to triage"; return 0; }
  # risk = severity_weight * (confidence/100); emitted into a summary file.
  jq -s '
    def sw: {critical:10,high:8,medium:5,low:2,info:1}[.] // 1;
    map({target, category, severity, confidence_score, confidence_tier,
         risk: (((.severity|sw) * .confidence_score) / 10 | floor)})
    | sort_by(-.risk)
  ' "$ff" > "$APEX_RUN_DIR/reports/risk_ranked.json" 2>/dev/null || true
  log_info "[P15] risk ranking written"
}

# ---- P15b: correlation / attack-chain engine --------------------------------
# Real correlation (not a placeholder): groups findings by host and emits a
# higher-severity CHAIN finding when a sensitive exposure co-occurs with a
# reachable attack surface on the same host. Unit-tested in tests/unit.
phase_correlate() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson"
  [[ -f "$ff" ]] || { log_info "[P15b] no findings to correlate"; return 0; }
  local tmp="$APEX_RUN_DIR/raw/corr.tsv"
  jq -r '[.target,.category]|@tsv' "$ff" > "$tmp" 2>/dev/null || return 0
  declare -A HCATS
  local target cat host
  while IFS=$'\t' read -r target cat; do
    [[ -z "$target" ]] && continue
    host="$(url_host "$target")"; [[ -z "$host" ]] && host="$target"
    HCATS["$host"]="${HCATS["$host"]:-}|$cat"
  done < "$tmp"
  local h cats distinct ev n=0
  for h in "${!HCATS[@]}"; do
    cats="${HCATS[$h]}"
    grep -qE 'secret-exposure|exposed-file|high-entropy-string' <<<"$cats" || continue
    grep -qE 'api-exposure|graphql-introspection|directory-listing|cors-misconfiguration|open-redirect|nuclei:|subdomain-takeover|reflected-input' <<<"$cats" || continue
    distinct="$(tr '|' '\n' <<<"$cats" | sort -u | grep -v '^$' | paste -sd ',' -)"
    ev="$(record_evidence correlation "attack chain on $h" "categories: $distinct")"
    emit_finding "attack-chain" "$h" "high" 82 \
      "Multiple correlated issues on $h form a plausible attack chain: $distinct." \
      "Chained exploitation (sensitive exposure + reachable attack surface) materially raises real-world impact versus the isolated findings." \
      "correlation-derived" \
      "Review the linked findings on $h together and validate the chain end-to-end." \
      "[\"$ev\"]" "[\"multi-signal-correlation\"]" >/dev/null
    n=$((n+1))
  done
  log_info "[P15b] correlation complete: $n chain(s) identified"
}

# ---- P15c: run-to-run diff (baseline) ---------------------------------------
# Pure helper (unit-tested): given the current and a baseline findings.ndjson,
# print "<new_count> <resolved_count>" based on content dedupe_key sets.
_diff_counts() {
  local cur="$1" base="$2" a b
  a="$(mktemp)"; b="$(mktemp)"
  jq -r '.dedupe_key // empty' "$cur"  2>/dev/null | sort -u > "$a"
  jq -r '.dedupe_key // empty' "$base" 2>/dev/null | sort -u > "$b"
  printf '%s %s' "$(comm -23 "$a" "$b" | grep -c .)" "$(comm -13 "$a" "$b" | grep -c .)"
  rm -f "$a" "$b"
}

# Auto-detect the most recent sibling run's findings file (same parent dir).
_autodetect_baseline() {
  [[ -n "${APEX_RUN_DIR:-}" ]] || return 0
  local parent d f t newest="" newest_t=0
  parent="$(dirname "$APEX_RUN_DIR")"
  for d in "$parent"/*/; do
    d="${d%/}"; [[ "$d" == "$APEX_RUN_DIR" ]] && continue
    f="$d/db/findings.ndjson"; [[ -f "$f" ]] || continue
    t="$(stat -c %Y "$f" 2>/dev/null || echo 0)"
    (( t > newest_t )) && { newest_t="$t"; newest="$f"; }
  done
  printf '%s' "$newest"
}

phase_diff() {
  local cur="$APEX_RUN_DIR/db/findings.ndjson"
  [[ -f "$cur" ]] || { log_info "[P15c] no findings to diff"; return 0; }
  local base; base="$(cfg_get baseline)"
  # Allow --baseline to be either a findings file or a run directory.
  [[ -d "$base" ]] && base="$base/db/findings.ndjson"
  [[ -z "$base" || ! -f "$base" ]] && base="$(_autodetect_baseline)"
  local out="$APEX_RUN_DIR/reports/changes.md"
  if [[ -z "$base" || ! -f "$base" ]]; then
    { printf '# Changes since last run\n\n'
      printf '_No baseline found — this is treated as the first run; every finding is NEW._\n'; } > "$out"
    log_info "[P15c] no baseline; all findings are NEW (first run)"
    return 0
  fi
  local counts new_n res_n
  counts="$(_diff_counts "$cur" "$base")"; new_n="${counts%% *}"; res_n="${counts##* }"
  local ck bk; ck="$(mktemp)"; bk="$(mktemp)"
  jq -r '.dedupe_key // empty' "$cur"  2>/dev/null | sort -u > "$ck"
  jq -r '.dedupe_key // empty' "$base" 2>/dev/null | sort -u > "$bk"
  { printf '# Changes since last run\n\n'
    printf -- '- **Baseline:** `%s`\n' "$base"
    printf -- '- **NEW findings:** %s\n' "$new_n"
    printf -- '- **RESOLVED (gone) findings:** %s\n\n' "$res_n"
    if (( new_n > 0 )); then
      printf '## NEW findings (review these first)\n\n'
      local k
      while IFS= read -r k; do
        [[ -z "$k" ]] && continue
        jq -r --arg k "$k" 'select(.dedupe_key==$k)
          | "- [\(.severity|ascii_upcase)] \(.category) — \(.target)  (\(.confidence_tier))"' "$cur" 2>/dev/null | head -1
      done < <(comm -23 "$ck" "$bk")
    fi
  } > "$out"
  rm -f "$ck" "$bk"
  log_info "[P15c] diff vs baseline: NEW=$new_n RESOLVED=$res_n"
}

# ---- P15d: metrics / telemetry ----------------------------------------------
phase_metrics() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson"
  local out="$APEX_RUN_DIR/reports/metrics.json"
  local nf nh ne
  nf="$(store_count findings)"; nh="$(store_count hosts)"; ne="$(store_count events)"
  if [[ -f "$ff" ]]; then
    jq -s --argjson hosts "${nh:-0}" --argjson events "${ne:-0}" '{
      total_findings: length,
      hosts: $hosts,
      tool_runs: $events,
      by_severity: (group_by(.severity)|map({key:(.[0].severity//"unknown"),value:length})|from_entries),
      by_tier:     (group_by(.confidence_tier)|map({key:(.[0].confidence_tier//"unknown"),value:length})|from_entries),
      by_category: (group_by(.category)|map({key:(.[0].category//"unknown"),value:length})|from_entries)
    }' "$ff" > "$out" 2>/dev/null || printf '{"total_findings":%s,"hosts":%s,"tool_runs":%s}\n' "${nf:-0}" "${nh:-0}" "${ne:-0}" > "$out"
  else
    printf '{"total_findings":0,"hosts":%s,"tool_runs":%s}\n' "${nh:-0}" "${ne:-0}" > "$out"
  fi
  log_info "[P15d] metrics written (findings=$nf hosts=$nh tool_runs=$ne)"
}

