  local t1; t1="$(date +%s)"
  log_info "phase durations: ${APEX_PHASE_DURATIONS:-none}"
  log_info "pipeline done in $((t1 - t0))s | findings=$(store_count findings) hosts=$(store_count hosts)"
}

# ===== lib/deepscan.sh =====
# APEX :: lib/deepscan.sh
# High-signal, evidence-CONFIRMED detections that work in pure bash (no external
# tools required) plus wrappers for heavier tools when present. Every check here
# only fires when a CONTENT SIGNATURE proves the issue -> effectively zero false
# positives (a bare HTTP 200 is never enough).

# ============================================================================
# Pure decision functions (unit-testable, no network) -> return 0 (confirmed)
# ============================================================================
_git_head_confirms() { grep -qE '^(ref: refs/|[0-9a-f]{40})' <<<"$1"; }
_git_config_confirms() { grep -q '\[core\]' <<<"$1"; }
_env_confirms() {
  # at least 2 KEY=VALUE lines AND a sensitive key -> real .env, not an SPA page
  local kv sens
  kv="$(grep -cE '^[A-Z][A-Z0-9_]{2,}=' <<<"$1")"
  sens="$(grep -ciE '(secret|password|passwd|api[_-]?key|token|db_|database|aws|private)' <<<"$1")"
  [[ "${kv:-0}" -ge 2 && "${sens:-0}" -ge 1 ]]
}
_dirlisting_confirms() { grep -qiE '<title>\s*Index of /|Directory listing for|\[To Parent Directory\]' <<<"$1"; }
_graphql_confirms() { grep -qE '"__schema"|"queryType"|"__type"|"types"\s*:' <<<"$1"; }
_svn_confirms() { grep -qE 'dir|svn:|[0-9]+' <<<"$1" && grep -qiE 'svn' <<<"$1"; }
_htpasswd_confirms() { grep -qE '^[A-Za-z0-9_.-]+:\$(apr1|2y|1|6)\$' <<<"$1"; }
_ds_store_confirms() { grep -qa 'Bud1' <<<"$1"; }

# Subdomain-takeover fingerprint DB:  cname_regex|||body_fingerprint|||service
declare -ga APEX_TAKEOVER_FP=(
  "github\.io|||There isn't a GitHub Pages site here|||GitHub Pages"
  'herokuapp\.com|||No such app|||Heroku'
  's3.*\.amazonaws\.com|||NoSuchBucket|||AWS S3'
  'azurewebsites\.net|||404 Web Site not found|||Azure'
  'ghost\.io|||The thing you were looking for is no longer here|||Ghost'
  'myshopify\.com|||Sorry, this shop is currently unavailable|||Shopify'
  'fastly\.net|||Fastly error: unknown domain|||Fastly'
  'pantheonsite\.io|||The gods are wise|||Pantheon'
  'wordpress\.com|||Do you want to register|||WordPress'
  'bitbucket\.io|||Repository not found|||Bitbucket'
  'surge\.sh|||project not found|||Surge'
  'readme\.io|||Project doesnt exist|||Readme'
  'zendesk\.com|||Help Center Closed|||Zendesk'
  'unbouncepages\.com|||The requested URL was not found|||Unbounce'
  'cargocollective\.com|||404 Not Found|||Cargo'
)
# returns service name if both cname AND body fingerprint match; else empty
_takeover_match() { # cname body
  local cname="$1" body="$2" e re fp svc
  for e in "${APEX_TAKEOVER_FP[@]}"; do
    re="${e%%|||*}"; fp="${e#*|||}"; svc="${fp#*|||}"; fp="${fp%%|||*}"
    if grep -qiE "$re" <<<"$cname" && grep -qiF "$fp" <<<"$body"; then
      printf '%s' "$svc"; return 0
    fi
  done
  return 1
}

# Shannon entropy * 1000 (integer) for a token
_shannon_x1000() {
  printf '%s' "$1" | awk '{
    n=length($0); if(n==0){print 0; exit}
    for(i=1;i<=n;i++){c=substr($0,i,1); f[c]++}
    e=0; for(c in f){p=f[c]/n; e-=p*log(p)/log(2)}
    printf "%d", e*1000
  }'
}

# ============================================================================
# P17: sensitive content discovery (REAL, signature-confirmed)
# ============================================================================
# path|||severity|||score|||confirm_fn|||title
declare -ga APEX_SENSITIVE_PATHS=(
  '/.git/HEAD|||high|||88|||_git_head_confirms|||Exposed .git repository (HEAD)'
  '/.git/config|||high|||88|||_git_config_confirms|||Exposed .git repository (config)'
  '/.env|||critical|||92|||_env_confirms|||Exposed .env secrets file'
  '/.htpasswd|||high|||85|||_htpasswd_confirms|||Exposed .htpasswd credentials'
  '/.svn/entries|||medium|||70|||_svn_confirms|||Exposed .svn metadata'
  '/.DS_Store|||low|||45|||_ds_store_confirms|||Exposed .DS_Store (path leak)'
)

phase_content_discovery() {
  _recon_ok || { log_warn "[P17] content discovery skipped (consent required)"; return 0; }
  _have curl || { log_warn "[P17] curl missing; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/cd_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || store_query hosts '.host' -r 2>/dev/null | sed 's#^#https://#' > "$list"
  [[ -s "$list" ]] || { log_info "[P17] no targets"; return 0; }
  local base entry path sev score fn title url body code ev tmo
  tmo="$(cfg_get timeout)"
  while IFS= read -r base; do
    [[ -z "$base" ]] && continue
    url_in_scope "$base" || continue
    base="${base%/}"
    for entry in "${APEX_SENSITIVE_PATHS[@]}"; do
      path="${entry%%|||*}"; entry="${entry#*|||}"
      sev="${entry%%|||*}";  entry="${entry#*|||}"
      score="${entry%%|||*}"; entry="${entry#*|||}"
      fn="${entry%%|||*}";    title="${entry#*|||}"
      url="$base$path"
      body="$(curl -sS -L --max-time "$tmo" -A 'APEX-Recon/2' "$url" 2>/dev/null)" || continue
      code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time "$tmo" "$url" 2>/dev/null || echo 000)"
      [[ "$code" == "200" ]] || continue
      "$fn" "$body" || continue   # <-- signature gate: no signature, no finding
      ev="$(record_evidence content-discovery "$title at $url (HTTP $code)" "$(head -c 500 <<<"$body")")"
      emit_finding "exposed-file" "$url" "$sev" "$score" \
        "$title ��� confirmed by content signature (not just a 200 response)." \
        "Exposed source/secrets/metadata can leak code, credentials, or internal structure." \
        "tool-verified" \
        "curl $url  and confirm the file content signature (evidence stored, secrets redacted)." \
        "[\"$ev\"]" "[\"http-200\",\"content-signature-match\"]" >/dev/null
    done
  done < "$list"
  log_info "[P17] content discovery complete"
}

# ============================================================================
# P18: DNS hygiene + zone transfer (REAL, via dig)
# ============================================================================
phase_dns_hygiene() {
  _have dig || { log_warn "[P18] dig missing; skipping DNS hygiene"; return 0; }
  local d spf dmarc ns nsl axfr ev
  for d in "${APEX_SEEDS[@]}"; do
    [[ -z "$d" ]] && continue
    spf="$(dig +short TXT "$d" 2>/dev/null | grep -i 'v=spf1' || true)"
    if [[ -z "$spf" ]]; then
      ev="$(record_evidence dns "no SPF record for $d" "dig TXT $d -> no v=spf1")"
      emit_finding "dns-spf-missing" "$d" "low" 45 \
        "No SPF (v=spf1) TXT record found." "Enables email spoofing from this domain." \
        "tool-verified" "dig TXT $d" "[\"$ev\"]" "[\"no-spf\"]" >/dev/null
    fi
    dmarc="$(dig +short TXT "_dmarc.$d" 2>/dev/null | grep -i 'v=DMARC1' || true)"
    if [[ -z "$dmarc" ]]; then
      ev="$(record_evidence dns "no DMARC record for $d" "dig TXT _dmarc.$d -> no v=DMARC1")"
      emit_finding "dns-dmarc-missing" "$d" "low" 45 \
        "No DMARC policy found." "Weakens protection against spoofing/phishing." \
        "tool-verified" "dig TXT _dmarc.$d" "[\"$ev\"]" "[\"no-dmarc\"]" >/dev/null
    fi
    # Zone transfer (AXFR) — high impact if it works
    nsl="$(dig +short NS "$d" 2>/dev/null)"
    for ns in $nsl; do
      axfr="$(dig +noall +answer AXFR "$d" "@${ns%.}" 2>/dev/null | head -50)"
      if [[ "$(wc -l <<<"$axfr")" -ge 2 ]] && grep -qE 'IN\s+(A|CNAME|MX|NS)' <<<"$axfr"; then
        ev="$(record_evidence dns "AXFR succeeded on $d via $ns" "$axfr")"
        emit_finding "dns-zone-transfer" "$d" "high" 90 \
          "DNS zone transfer (AXFR) succeeded — the full zone was disclosed by $ns." \
          "Attackers enumerate every DNS record (internal hosts, services)." \
          "tool-verified" "dig AXFR $d @${ns%.}" "[\"$ev\"]" "[\"axfr-transfer\"]" >/dev/null
      fi
    done
  done
  log_info "[P18] DNS hygiene complete"
}

# ============================================================================
# P19: GraphQL introspection (REAL, confirmed by response)
# ============================================================================
phase_graphql() {
  _recon_ok || { log_warn "[P19] graphql skipped (consent required)"; return 0; }
  _have curl || return 0
  local list="$APEX_RUN_DIR/raw/gql_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || { log_info "[P19] no web targets"; return 0; }
  local q='{"query":"{__schema{queryType{name}types{name}}}"}'
  local base p url body ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r base; do
    [[ -z "$base" ]] && continue
    url_in_scope "$base" || continue
    base="${base%/}"
    for p in "/graphql" "/api/graphql" "/v1/graphql" "/query"; do
      url="$base$p"
      body="$(curl -sS -L --max-time "$tmo" -H 'Content-Type: application/json' -d "$q" "$url" 2>/dev/null)" || continue
      _graphql_confirms "$body" || continue
      ev="$(record_evidence graphql "introspection enabled at $url" "$(head -c 400 <<<"$body")")"
      emit_finding "graphql-introspection" "$url" "medium" 78 \
        "GraphQL introspection is enabled and returned the schema." \
        "Full API schema disclosure aids targeted attacks (hidden queries/mutations)." \
        "tool-verified" \
        "curl -d '$q' $url  and observe __schema in the response." \
        "[\"$ev\"]" "[\"introspection-enabled\"]" >/dev/null
    done
  done < "$list"
  log_info "[P19] graphql check complete"
}

# ============================================================================
# P20: directory listing (REAL, confirmed by body)
# ============================================================================
phase_dir_listing() {
  _recon_ok || { log_warn "[P20] dir-listing skipped (consent required)"; return 0; }
  _have curl || return 0
  local list="$APEX_RUN_DIR/raw/dl_targets.txt"
  store_query urls '.url' -r 2>/dev/null | grep -E '/$' | sort -u | head -n "$(cfg_get_default max_urls 2000)" > "$list" || true
  [[ -s "$list" ]] || { log_info "[P20] no directory URLs"; return 0; }
  local u body ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    url_in_scope "$u" || continue
    body="$(curl -sS -L --max-time "$tmo" "$u" 2>/dev/null)" || continue
    _dirlisting_confirms "$body" || continue
    ev="$(record_evidence dir-listing "open directory listing at $u" "$(head -c 400 <<<"$body")")"
    emit_finding "directory-listing" "$u" "medium" 72 \
      "Directory listing is enabled — the server returned an index of files." \
      "Exposes file names/structure and potentially sensitive files." \
      "tool-verified" "curl $u  and observe the 'Index of' listing." \
      "[\"$ev\"]" "[\"directory-index\"]" >/dev/null
  done < "$list"
  log_info "[P20] directory-listing check complete"
}

# ============================================================================
# P21: takeover fingerprint (REAL, CNAME + body; complements subzy)
# ============================================================================
phase_takeover_fp() {
  _recon_ok || { log_warn "[P21] takeover-fp skipped (consent required)"; return 0; }
  _have dig || { log_warn "[P21] dig missing; skipping"; return 0; }
  _have curl || return 0
  local hl="$APEX_RUN_DIR/raw/hosts.txt"
  store_query hosts '.host' -r > "$hl" 2>/dev/null || true
  [[ -s "$hl" ]] || { log_info "[P21] no hosts"; return 0; }
  local host cname body svc ev tmo; tmo="$(cfg_get timeout)"
  while IFS= read -r host; do
    [[ -z "$host" ]] && continue
    in_scope "$host" || continue
    cname="$(dig +short CNAME "$host" 2>/dev/null)"
    [[ -z "$cname" ]] && continue
    body="$(curl -sS -L --max-time "$tmo" "http://$host" 2>/dev/null)" || true
    if svc="$(_takeover_match "$cname" "$body")"; then
      ev="$(record_evidence takeover "$host -> $cname ($svc) shows unclaimed fingerprint" "CNAME=$cname\n$(head -c 300 <<<"$body")")"
      emit_finding "subdomain-takeover" "$host" "high" 88 \
        "$host points (CNAME) to $svc at $cname and the service returns its unclaimed-resource fingerprint." \
        "An attacker can register the dangling resource and control content on $host." \
        "tool-verified" \
        "dig CNAME $host  ; curl http://$host  and confirm the $svc takeover fingerprint." \
        "[\"$ev\"]" "[\"cname-dangling\",\"fingerprint-match\"]" >/dev/null
    fi
  done < "$hl"
  log_info "[P21] takeover fingerprint check complete"
}

# ============================================================================
# P22: high-entropy secret candidates in JS (marked NEEDS_REVIEW; no FP claims)
# ============================================================================
phase_entropy_secrets() {
  _recon_ok || { return 0; }
  local urls="$APEX_RUN_DIR/raw/js_urls.txt"
  [[ -s "$urls" ]] || return 0
  local u f i=0 tok ent ev
  while IFS= read -r u; do
    [[ -z "$u" ]] && continue
    f="$APEX_RUN_DIR/raw/ent_$i.body"; i=$((i+1))
    _fetch "$u" "$f" || continue
    # candidate tokens: 20-64 char base64-ish strings
    grep -oE '[A-Za-z0-9+/_=-]{24,64}' "$f" 2>/dev/null | sort -u | head -50 > "$f.tok" || true
    while IFS= read -r tok; do
      [[ -z "$tok" ]] && continue
      ent="$(_shannon_x1000 "$tok")"
      [[ "${ent:-0}" -ge 4200 ]] || continue   # >4.2 bits/char = high entropy
      ev="$(record_evidence entropy "high-entropy token in $u (H=${ent}m)" "$tok")"
      emit_finding "high-entropy-string" "$u" "low" 20 \
        "A high-entropy string (possible secret/token) was found in JavaScript." \
        "May be a credential; requires human review to confirm (could be a hash/minified id)." \
        "needs-human" \
        "Review the token in evidence; verify whether it is a live secret before reporting." \
        "[\"$ev\"]" "[\"entropy-only\",\"unconfirmed\"]" >/dev/null
    done < "$f.tok"
  done < "$urls"
  log_info "[P22] entropy scan complete"
}

# ============================================================================
# Optional heavy-tool wrappers (run only when the tool is present + gated)
# ============================================================================
phase_waf() {
  _recon_ok || return 0
  _have wafw00f || { log_warn "[WAF] wafw00f missing; skipping"; return 0; }
