  apex_exec wafw00f 300 "$APEX_RUN_DIR/raw/wafw00f.txt" -- wafw00f -i "$list" || true
  log_info "[WAF] wafw00f complete (informational; stored in raw/)"
}

phase_screenshots() {
  _recon_ok || return 0
  local list="$APEX_RUN_DIR/raw/shot_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || return 0
  if _have gowitness; then
    apex_exec gowitness 600 "$APEX_RUN_DIR/raw/gowitness.log" -- gowitness file -f "$list" -P "$APEX_RUN_DIR/screenshots" || true
    log_info "[SHOT] gowitness screenshots in screenshots/"
  elif _have aquatone; then
    APEX_EXEC_STDIN="$list" apex_exec aquatone 600 "$APEX_RUN_DIR/raw/aquatone.log" -- aquatone -out "$APEX_RUN_DIR/screenshots" || true
    log_info "[SHOT] aquatone screenshots in screenshots/"
  else
    log_warn "[SHOT] no screenshot tool (gowitness/aquatone); skipping"
  fi
