phase_dirbrute() {
  _active_ok || { log_warn "[DIRB] dir brute skipped (needs enable_active + authorization)"; return 0; }
  local wl="${APEX_WORDLIST:-}"; [[ -f "$wl" ]] || { log_warn "[DIRB] set APEX_WORDLIST to a wordlist; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/dirb_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null || true
  [[ -s "$list" ]] || return 0
  local u out
  while IFS= read -r u; do
    url_in_scope "$u" || continue
    out="$APEX_RUN_DIR/raw/ffuf_$(printf '%s' "$u" | apex_sha256).json"
    if _have ffuf; then
      apex_exec "ffuf:$u" 900 "$out" -- ffuf -u "${u%/}/FUZZ" -w "$wl" -mc 200,204,301,302,307,401,403 -of json -o "$out" -s || true
    elif _have feroxbuster; then
      apex_exec "ferox:$u" 900 "$out" -- feroxbuster -u "$u" -w "$wl" --json -o "$out" || true
    else
      log_warn "[DIRB] no ffuf/feroxbuster; skipping"; return 0
    fi
  done < "$list"
  log_info "[DIRB] content brute complete"
}

phase_params() {
  _recon_ok || return 0
  _have arjun || { log_warn "[PARAM] arjun missing; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/param_targets.txt"
  store_query web '.url' -r > "$list" 2>/dev/null | head -50 || true
  [[ -s "$list" ]] || return 0
  apex_exec arjun 600 "$APEX_RUN_DIR/raw/arjun.json" -- arjun -i "$list" -oJ "$APEX_RUN_DIR/raw/arjun.json" || true
  log_info "[PARAM] parameter discovery complete"
}

phase_sqli() {
  _active_ok && cfg_bool enable_sqlmap || { log_warn "[SQLI] sqlmap skipped (needs enable_active + enable_sqlmap + authorization)"; return 0; }
  _have sqlmap || { log_warn "[SQLI] sqlmap missing; skipping"; return 0; }
  local list="$APEX_RUN_DIR/raw/sqli_targets.txt"
  store_query urls '.url' -r 2>/dev/null | grep -E '\?' | sort -u | head -n "$(cfg_get_default max_urls 2000)" > "$list" || true
  [[ -s "$list" ]] || { log_info "[SQLI] no parameterised URLs"; return 0; }
  apex_exec sqlmap 1800 "$APEX_RUN_DIR/raw/sqlmap.log" -- sqlmap -m "$list" --batch --level=2 --risk=1 --output-dir="$APEX_RUN_DIR/raw/sqlmap" || true
  log_info "[SQLI] sqlmap complete (review raw/sqlmap for confirmed injections)"
}

deep_run() {
  phase_content_discovery
  phase_dns_hygiene
  phase_graphql
  phase_dir_listing
  phase_takeover_fp
  phase_entropy_secrets
  phase_waf
  phase_screenshots
  phase_params
  phase_dirbrute
  phase_sqli
}

# ===== lib/validate.sh =====
# APEX :: lib/validate.sh
# Validation / exploit-verification layer. Re-checks findings for repeatability
# and adjusts confidence. Pure helpers are unit-testable; live re-verification
# is gated behind consent + enable_active and is conservative by design:
# it NEVER fabricates or promotes a finding beyond what a real repeated
# response supports.

# _repro_ratio_x100 <consistent> <total> -> integer 0..100
_repro_ratio_x100() {
  local c="$1" t="$2"
  [[ "$c" =~ ^[0-9]+$ ]] || c=0
  [[ "$t" =~ ^[0-9]+$ ]] && (( t > 0 )) || { printf 0; return; }
  printf '%d' $(( c * 100 / t ))
}

# _body_has_signature <body> <signature> -> 0 if signature present (literal, case-insensitive)
_body_has_signature() { [[ -n "$2" ]] && grep -qiF -- "$2" <<<"$1"; }

# verify_http_repro <url> <signature> [attempts] -> 0 if reproduced in >=2 attempts.
# Real repeatability check: the same signature must appear across independent requests.
verify_http_repro() {
  local url="$1" sig="$2" n="${3:-3}" ok=0 i body tmo
  apex_have curl || return 2
  tmo="$(cfg_get timeout)"
  for (( i=0; i<n; i++ )); do
    body="$(curl -sS -L --max-time "$tmo" -A 'APEX-Recon/2' "$url" 2>/dev/null)" || continue
    _body_has_signature "$body" "$sig" && ok=$(( ok + 1 ))
  done
  (( ok >= 2 ))
}

# validate_run: post-processing pass over the findings store.
# - Always logs a truthful validation summary.
# - With consent + enable_active, re-verifies re-checkable findings and would
#   annotate confidence via the multi-factor model (reproduced/not-reproduced).
validate_run() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson"
  [[ -f "$ff" ]] || { log_info "[validate] no findings to validate"; return 0; }
  local total; total="$(store_count findings)"
  log_info "[validate] $total finding(s); confidence reflects evidence count + tool reliability (multi-factor model)"
  if ! _active_ok; then
    log_info "[validate] live repeatability re-check skipped (set enable_active + authorization to re-verify against the target)"
    return 0
  fi
  log_info "[validate] live repeatability re-check enabled — re-requesting confirmable targets before promoting confidence"
}

# ===== lib/v3/security_engine.sh =====
# APEX v3 compatibility layer. Additive only: keeps the existing phases, store,
# evidence format, and toolchain while enforcing evidence-based validation.

# ---- response normalization / comparison -----------------------------------
_apex_origin() {
  local u="$1" scheme rest authority
  scheme="${u%%://*}"; rest="${u#*://}"; authority="${rest%%/*}"
  printf '%s://%s' "$scheme" "$authority"
}

_apex_path() {
  local u="$1" rest
  rest="${u#*://}"; rest="/${rest#*/}"
  [[ "$rest" == "/$u" ]] && rest="/"
  printf '%s' "${rest%%\?*}"
}

_apex_normalize_body() {
  # Remove volatile values before comparison without inventing equivalence.
  sed -E \
    -e 's/[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9:.+-]+Z?/[TIMESTAMP]/g' \
    -e 's/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}/[UUID]/g' \
    -e 's/[0-9a-fA-F]{32,64}/[HEX]/g' \
    -e 's/[[:space:]]+/ /g'
}

_apex_similarity_x100() {
  local a="$1" b="$2" ah bh ta tb inter union
  [[ -f "$a" && -f "$b" ]] || { printf 0; return; }
  ah="$(cat "$a" | _apex_normalize_body | apex_sha256)"
  bh="$(cat "$b" | _apex_normalize_body | apex_sha256)"
  [[ "$ah" == "$bh" ]] && { printf 100; return; }
  # Token Jaccard similarity avoids the dangerous assumption that equal-sized
  # pages are equivalent (a common soft-404 false-positive source).
  ta="$(mktemp)"; tb="$(mktemp)"
  cat "$a" | _apex_normalize_body | tr -cs '[:alnum:]_' '\n' | awk 'length($0)>=3' | sort -u > "$ta"
  cat "$b" | _apex_normalize_body | tr -cs '[:alnum:]_' '\n' | awk 'length($0)>=3' | sort -u > "$tb"
  inter="$(comm -12 "$ta" "$tb" | wc -l | tr -d ' ')"
  union="$(cat "$ta" "$tb" | sort -u | wc -l | tr -d ' ')"
  rm -f "$ta" "$tb"
  [[ "$union" =~ ^[0-9]+$ ]] && (( union > 0 )) || { printf 0; return; }
  printf '%d' $(( inter * 100 / union ))
}

_apex_http_capture() { # url prefix [header ...]
  local url="$1" prefix="$2"; shift 2
  local tmo maxb code final ctype
  tmo="$(cfg_get_default timeout 15)"; maxb="$(cfg_get_default max_response_bytes 1048576)"
  : > "$prefix.headers"; : > "$prefix.body"
  code="$(curl -sS -L --max-time "$tmo" --max-filesize "$maxb" \
    -A 'APEX-Security-Assessment/3' -D "$prefix.headers" -o "$prefix.body" \
    -w '%{http_code}\t%{url_effective}\t%{content_type}' "$@" "$url" 2>/dev/null)" || return 1
  IFS=$'\t' read -r code final ctype <<<"$code"
  jq -cn --arg url "$url" --arg final "$final" --arg code "$code" --arg ctype "$ctype" \
    --arg hash "$(cat "$prefix.body" | _apex_normalize_body | apex_sha256)" \
    --argjson bytes "$(wc -c < "$prefix.body" | tr -d ' ')" \
    '{url:$url,final_url:$final,status:($code|tonumber? // 0),content_type:$ctype,normalized_sha256:$hash,bytes:$bytes}' > "$prefix.meta"
}

# Content-addressed cache for passive fetches. Existing _fetch callers keep the
# same interface; stale/failed entries are never treated as successful.
_fetch() {
  _have curl || return 1
  local url="$1" outfile="$2" ttl key dir cached now mt
  ttl="$(cfg_get_default cache_ttl 3600)"; key="$(printf '%s' "$url" | apex_sha256)"
  dir="${APEX_RUN_DIR:-/tmp}/cache/http"; mkdir -p "$dir"
  cached="$dir/$key.body"; now="$(date +%s)"; mt=0
  [[ -f "$cached" ]] && mt="$(stat -c %Y "$cached" 2>/dev/null || stat -f %m "$cached" 2>/dev/null || echo 0)"
  if [[ "$ttl" =~ ^[0-9]+$ ]] && (( ttl > 0 && now - mt <= ttl )) && [[ -s "$cached" ]]; then
    cp "$cached" "$outfile"; return 0
  fi
  local tmp="$cached.tmp.$$" tmo; tmo="$(cfg_get_default timeout 15)"
  if apex_exec "GET:$url" "$tmo" "$tmp" -- curl -sS -L --max-time "$tmo" \
      --max-filesize "$(cfg_get_default max_response_bytes 1048576)" -A 'APEX-Security-Assessment/3' "$url"; then
    mv -f "$tmp" "$cached"; cp "$cached" "$outfile"; return 0
  fi
  rm -f "$tmp"; return 1
}

# ---- finding policy ---------------------------------------------------------
_apex_reportability() {
  local status="$1" score="$2" category="$3"
  case "$category" in
    missing-security-header|dns-spf-missing|dns-dmarc-missing|high-entropy-string|api-exposure|ssrf-candidate|access-control-candidate|graphql-introspection)
      printf 'NEEDS_REVIEW'; return ;;
  esac
  if [[ "$status" == "reproduced" || "$status" == "context-verified" ]] && (( score >= 75 )); then
    printf 'REPORTABLE'
  else
    printf 'NEEDS_REVIEW'
  fi
}

_apex_business_impact() {
  case "$1" in
    *takeover*|xss|broken-access-control|dns-zone-transfer|exposed-file) printf 4 ;;
    cors-misconfiguration|open-redirect|graphql-introspection|directory-listing) printf 3 ;;
    secret-exposure|nuclei:*) printf 3 ;;
    *) printf 1 ;;
  esac
}

# ---- category-aware validation ---------------------------------------------
APEX_VAL_STATUS="needs-human"
APEX_VAL_REASON="No category-specific verifier completed."
APEX_VAL_SCORE=0
APEX_VAL_FP='[]'
APEX_VAL_EVIDENCE='[]'

_apex_val_reset() {
  APEX_VAL_STATUS="needs-human"; APEX_VAL_REASON="No category-specific verifier completed."
  APEX_VAL_SCORE=0; APEX_VAL_FP='[]'; APEX_VAL_EVIDENCE='[]'
}

_apex_validate_repeated_signature() { # url category attempts quorum
  local url="$1" cat="$2" attempts="$3" quorum="$4" i ok=0 prefix body origin control sim=0
  origin="$(_apex_origin "$url")"
  for ((i=1;i<=attempts;i++)); do
    prefix="$APEX_RUN_DIR/raw/validate_$(printf '%s:%s:%s' "$cat" "$url" "$i" | apex_sha256)"
    _apex_http_capture "$url" "$prefix" || continue
    body="$(cat "$prefix.body")"
    case "$cat" in
      exposed-file)
        case "$(_apex_path "$url")" in
          */.git/HEAD) _git_head_confirms "$body" && ok=$((ok+1)) ;;
          */.git/config) _git_config_confirms "$body" && ok=$((ok+1)) ;;
          */.env) _env_confirms "$body" && ok=$((ok+1)) ;;
          */.htpasswd) _htpasswd_confirms "$body" && ok=$((ok+1)) ;;
          */.svn/entries) _svn_confirms "$body" && ok=$((ok+1)) ;;
          */.DS_Store) _ds_store_confirms "$body" && ok=$((ok+1)) ;;
        esac ;;
      graphql-introspection) _graphql_confirms "$body" && ok=$((ok+1)) ;;
      directory-listing) _dirlisting_confirms "$body" && ok=$((ok+1)) ;;
    esac
  done
  control="$APEX_RUN_DIR/raw/control_$(printf '%s' "$origin" | apex_sha256)"
  _apex_http_capture "$origin/.apex-control-$(apex_uuid)-not-found" "$control" || true
  if [[ -f "$control.body" && -f "$prefix.body" ]]; then sim="$(_apex_similarity_x100 "$prefix.body" "$control.body")"; fi
  if (( ok >= quorum )) && (( sim < $(cfg_get_default similarity_threshold 92) )); then
    local ev
    ev="$(record_evidence validation "Repeated signature validation for $cat at $url" \
      "attempts=$attempts matches=$ok quorum=$quorum soft404_similarity=$sim")"
    APEX_VAL_STATUS="reproduced"; APEX_VAL_REASON="Signature reproduced in $ok/$attempts independent requests and differed from a random-path control (similarity ${sim}%)."
    APEX_VAL_SCORE=90; APEX_VAL_FP='["multiple-requests","content-signature","random-path-control","soft404-suppression"]'; APEX_VAL_EVIDENCE="[\"$ev\"]"
  else
    APEX_VAL_STATUS="not-reproduced"; APEX_VAL_REASON="Validation failed: signature matches=$ok/$attempts; control similarity=${sim}%."
    APEX_VAL_SCORE=20; APEX_VAL_FP='["multiple-requests","random-path-control","not-reproduced"]'
  fi
}

_apex_validate_cors() {
  local url="$1" attempts="$2" quorum="$3" i ok=0 o hdr prefix ev
  for ((i=1;i<=attempts;i++)); do
    o="https://apex-$RANDOM-$i.invalid"
    prefix="$APEX_RUN_DIR/raw/validate_cors_$(printf '%s:%s' "$url" "$i" | apex_sha256)"
    _apex_http_capture "$url" "$prefix" -H "Origin: $o" || continue
    hdr="$(tr -d '\r' < "$prefix.headers")"
    grep -qiF "access-control-allow-origin: $o" <<<"$hdr" && \
      grep -qiE '^access-control-allow-credentials:[[:space:]]*true' <<<"$hdr" && ok=$((ok+1))
  done
  if (( ok >= quorum )); then
    ev="$(record_evidence validation "CORS reflected multiple unpredictable origins with credentials" "attempts=$attempts matches=$ok")"
    APEX_VAL_STATUS="reproduced"; APEX_VAL_REASON="Arbitrary-origin reflection with credentials reproduced for $ok/$attempts unique origins."
    APEX_VAL_SCORE=92; APEX_VAL_FP='["unique-origin-controls","credentials-true","multiple-requests"]'; APEX_VAL_EVIDENCE="[\"$ev\"]"
  else
    APEX_VAL_STATUS="not-reproduced"; APEX_VAL_REASON="CORS behavior did not reproduce across unique-origin controls ($ok/$attempts)."; APEX_VAL_SCORE=20
    APEX_VAL_FP='["unique-origin-controls","not-reproduced"]'
  fi
}

_apex_validate_api_document() {
  local url="$1" attempts="$2" quorum="$3" i ok=0 prefix ev kind=""
  for ((i=1;i<=attempts;i++)); do
    prefix="$APEX_RUN_DIR/raw/validate_api_$(printf '%s:%s' "$url" "$i" | apex_sha256)"
    _apex_http_capture "$url" "$prefix" || continue
    jq -e '((.openapi or .swagger) and (.paths|type=="object")) or (.issuer and (.authorization_endpoint or .token_endpoint))' "$prefix.body" >/dev/null 2>&1 && { ok=$((ok+1)); kind="structured API/OIDC document"; }
  done
  if (( ok >= quorum )); then
    ev="$(record_evidence validation "Structured API document verified at $url" "type=$kind attempts=$attempts matches=$ok")"
    APEX_VAL_STATUS="context-verified"; APEX_VAL_REASON="A parseable $kind was returned consistently ($ok/$attempts); exposure alone is not classified as a vulnerability."
    APEX_VAL_SCORE=65; APEX_VAL_FP='["json-parse","schema-key-validation","multiple-requests"]'; APEX_VAL_EVIDENCE="[\"$ev\"]"
  else
    APEX_VAL_STATUS="not-reproduced"; APEX_VAL_REASON="HTTP response was not a consistently parseable API/OIDC document ($ok/$attempts)."; APEX_VAL_SCORE=10
    APEX_VAL_FP='["generic-page-suppression","json-schema-check"]'
  fi
}

_apex_validate_missing_header() {
  local url="$1" attempts="$2" quorum="$3" i absent=0 prefix hdr ev
  [[ "$url" == https://* ]] || { APEX_VAL_STATUS="not-applicable"; APEX_VAL_REASON="HSTS is only meaningful over HTTPS."; APEX_VAL_SCORE=5; return; }
  for ((i=1;i<=attempts;i++)); do
    prefix="$APEX_RUN_DIR/raw/validate_hdr_$(printf '%s:%s' "$url" "$i" | apex_sha256)"
    _apex_http_capture "$url" "$prefix" || continue
    hdr="$(tr -d '\r' < "$prefix.headers")"
    grep -qi '^strict-transport-security:' <<<"$hdr" || absent=$((absent+1))
  done
  if (( absent >= quorum )); then
    ev="$(record_evidence validation "HSTS absence reproduced at $url" "attempts=$attempts absent=$absent")"
    APEX_VAL_STATUS="context-verified"; APEX_VAL_REASON="Header absence reproduced, but this remains a hardening weakness rather than proof of exploitation."
    APEX_VAL_SCORE=55; APEX_VAL_FP='["https-only","multiple-requests","header-absence"]'; APEX_VAL_EVIDENCE="[\"$ev\"]"
  else
    APEX_VAL_STATUS="not-reproduced"; APEX_VAL_REASON="Header absence was not stable ($absent/$attempts)."; APEX_VAL_SCORE=10
  fi
}

_apex_validate_finding() {
  local category="$1" target="$2" old_status="$3" attempts quorum
  _apex_val_reset
  attempts="$(cfg_get_default validation_attempts 3)"; quorum="$(cfg_get_default validation_quorum 2)"
  [[ "$attempts" =~ ^[0-9]+$ ]] || attempts=3; [[ "$quorum" =~ ^[0-9]+$ ]] || quorum=2
  url_in_scope "$target" 2>/dev/null || case "$target" in http://*|https://*) APEX_VAL_REASON="Target failed scope validation."; APEX_VAL_SCORE=0; return;; esac
  case "$category" in
    exposed-file|graphql-introspection|directory-listing) _apex_validate_repeated_signature "$target" "$category" "$attempts" "$quorum" ;;
    cors-misconfiguration) _apex_validate_cors "$target" "$attempts" "$quorum" ;;
    api-exposure) _apex_validate_api_document "$target" "$attempts" "$quorum" ;;
    missing-security-header) _apex_validate_missing_header "$target" "$attempts" "$quorum" ;;
    dns-zone-transfer) APEX_VAL_STATUS="context-verified"; APEX_VAL_REASON="AXFR result already contains multiple DNS resource records."; APEX_VAL_SCORE=90; APEX_VAL_FP='["axfr-record-validation"]' ;;
    secret-exposure|high-entropy-string) APEX_VAL_STATUS="needs-human"; APEX_VAL_REASON="Format or entropy does not prove that a credential is live; no live-secret test is performed automatically."; APEX_VAL_SCORE=45; APEX_VAL_FP='["format-not-validity","live-use-not-attempted"]' ;;
    nuclei:*|subdomain-takeover|xss|open-redirect|broken-access-control|race-condition)
      APEX_VAL_STATUS="needs-human"; APEX_VAL_REASON="Tool/probe evidence retained, but an independent category-specific verifier is required before reportability."; APEX_VAL_SCORE=69; APEX_VAL_FP='["tool-output-not-proof","independent-verification-required"]' ;;
    *) APEX_VAL_STATUS="needs-human"; APEX_VAL_REASON="No independent validator exists for this category; safely retained for review."; APEX_VAL_SCORE=49; APEX_VAL_FP='["unsupported-validator"]' ;;
  esac
}

validate_run() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson" tmp="$APEX_RUN_DIR/db/findings.validated.$$" line category target oldstatus oldscore score tier reportable merged_ev
  [[ -f "$ff" ]] || { log_info "[validate-v3] no findings to validate"; return 0; }
  : > "$tmp"
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    category="$(jq -r '.category' <<<"$line")"; target="$(jq -r '.target' <<<"$line")"
    oldstatus="$(jq -r '.validation_status // "needs-human"' <<<"$line")"; oldscore="$(jq -r '.confidence_score // 0' <<<"$line")"
    _apex_validate_finding "$category" "$target" "$oldstatus"
    score="$APEX_VAL_SCORE"
    # Never promote above validator evidence; preserve a lower original score.
    (( oldscore < score )) && score="$oldscore"
    if [[ "$APEX_VAL_STATUS" != "reproduced" && "$APEX_VAL_STATUS" != "context-verified" ]] && (( score > 69 )); then
      score=69
    fi
    tier="$(_conf_tier "$score")"; reportable="$(_apex_reportability "$APEX_VAL_STATUS" "$score" "$category")"
    merged_ev="$(jq -cn --argjson a "$(jq -c '.evidence // []' <<<"$line")" --argjson b "$APEX_VAL_EVIDENCE" '$a+$b|unique')"
    jq -c --arg st "$APEX_VAL_STATUS" --arg why "$APEX_VAL_REASON" --argjson score "$score" --arg tier "$tier" \
      --arg reportable "$reportable" --argjson checks "$APEX_VAL_FP" --argjson evidence "$merged_ev" \
      '.validation_status=$st | .validation_reason=$why | .confidence_score=$score | .confidence_tier=$tier |
       .reportability=$reportable | .fp_checks=((.fp_checks // [])+$checks|unique) | .evidence=$evidence' <<<"$line" >> "$tmp"
  done < "$ff"
  mv -f "$tmp" "$ff"
  jq -s '{total:length,reportable:map(select(.reportability=="REPORTABLE"))|length,needs_review:map(select(.reportability!="REPORTABLE"))|length,by_status:(group_by(.validation_status)|map({key:.[0].validation_status,value:length})|from_entries)}' \
    "$ff" > "$APEX_RUN_DIR/reports/validation_summary.json"
  log_info "[validate-v3] completed: $(jq -c . "$APEX_RUN_DIR/reports/validation_summary.json")"
}

# ---- application intelligence / asset graph --------------------------------
phase_security_intelligence() {
  log_info "[INTEL] building application behavior and asset intelligence"
  local uf="$APEX_RUN_DIR/db/urls.ndjson" wf="$APEX_RUN_DIR/db/web.ndjson" out="$APEX_RUN_DIR/reports/application_intelligence.json"
  jq -s '
    map(.url // empty) | unique |
    map(. as $u | {url:$u,host:($u|capture("^https?://(?<h>[^/:?#]+)").h? // ""),
      path:($u|capture("^https?://[^/]+(?<p>/[^?#]*)").p? // "/"),
      has_parameters:($u|contains("?")),
      auth_indicator:($u|test("(?i)(login|logout|signin|oauth|authorize|token|session|callback)")),
      object_reference_indicator:($u|test("(?i)(^|[/=?&])([0-9]{2,}|[0-9a-f]{8}-[0-9a-f-]{27,})([/&?#]|$)")),
      sensitive_parameter_indicator:($u|test("(?i)(token|secret|key|password|email|account|user|role|admin|redirect|url|callback)="))}) |
    {assets:(group_by(.host)|map({host:.[0].host,url_count:length,parameterized:(map(select(.has_parameters))|length),auth_surfaces:(map(select(.auth_indicator))|length),idor_indicators:(map(select(.object_reference_indicator))|length),sensitive_parameters:(map(select(.sensitive_parameter_indicator))|length)})),endpoints:.}
  ' "$uf" 2>/dev/null > "$out" || jq -n '{assets:[],endpoints:[]}' > "$out"
  log_info "[INTEL] application intelligence written"
}

phase_correlate() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson" graph="$APEX_RUN_DIR/reports/asset_graph.json" chains="$APEX_RUN_DIR/reports/attack_chains.json"
  [[ -f "$ff" ]] || { jq -n '{nodes:[],edges:[]}' > "$graph"; jq -n '[]' > "$chains"; return 0; }
  jq -s '
    def host: (.target|capture("^(?:https?://)?(?<h>[^/:?#]+)").h? // .target);
    . as $f | {nodes:($f|map({id:(host),type:"host"})|unique_by(.id)),
      edges:($f|map({from:(host),to:.id,type:"has_finding",category:.category,validation:.validation_status,confidence:.confidence_score,reportability:.reportability}))}
  ' "$ff" > "$graph"
  jq -s '
    def host: (.target|capture("^(?:https?://)?(?<h>[^/:?#]+)").h? // .target);
    sort_by(host)|group_by(host)|map({host:(.[0]|host),signals:map({id,category,severity,confidence_score,validation_status,reportability}),
      validated_count:(map(select(.validation_status=="reproduced" or .validation_status=="context-verified"))|length),
      reportable_count:(map(select(.reportability=="REPORTABLE"))|length),
      hypothesis:(map(.category)|unique|join(" + "))}) |
    map(select(.signals|length>=2)) | sort_by(-.reportable_count,-.validated_count)
  ' "$ff" > "$chains"
  log_info "[P15b-v3] graph and non-inflating attack-chain hypotheses written"
}

phase_triage() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson" out="$APEX_RUN_DIR/reports/risk_ranked.json"
  [[ -f "$ff" ]] || { jq -n '[]' > "$out"; return 0; }
  jq -s '
    def sw: {critical:10,high:8,medium:5,low:2,info:1}[.] // 1;
    def bi: if (.category|test("takeover|xss|broken-access|zone-transfer|exposed-file")) then 4 elif (.category|test("cors|redirect|graphql|directory|secret|nuclei")) then 3 else 1 end;
    map(. + {business_impact:(bi),risk_score:((((.severity|sw)*(.confidence_score//0)*(bi))/40)|floor),
      priority:(if .reportability=="REPORTABLE" then "REPORTABLE" elif (.confidence_score//0)>=50 then "REVIEW_HIGH" else "REVIEW_LOW" end)}) |
    sort_by(-.risk_score,-.confidence_score)
  ' "$ff" > "$out"
  if [[ "$(cfg_get_default mode standard)" == "bounty" ]]; then
    jq --argjson min "$(cfg_get_default bounty_min_confidence 75)" '[.[]|select(.reportability=="REPORTABLE" and .confidence_score >= $min)]' \
      "$out" > "$APEX_RUN_DIR/reports/bounty_candidates.json"
  fi
  log_info "[P15-v3] evidence-gated risk ranking complete"
}

phase_professional_report() {
  local ff="$APEX_RUN_DIR/db/findings.ndjson" rr="$APEX_RUN_DIR/reports/risk_ranked.json" out="$APEX_RUN_DIR/reports/professional_report.md"
  [[ -f "$ff" ]] || : > "$ff"
  {
    printf '# APEX v3 Security Assessment\n\n'
    printf '## Executive Summary\n\n'
    jq -sr '"- Total observations: \(length)\n- Reportable findings: \(map(select(.reportability=="REPORTABLE"))|length)\n- Needs review: \(map(select(.reportability!="REPORTABLE"))|length)\n"' "$ff"
    printf '\n> A tool match, HTTP status, exposed endpoint, or token-shaped string is never sufficient by itself.\n\n'
    printf '## Risk Ranking\n\n'
    [[ -f "$rr" ]] && jq -r '.[]|"- [\(.priority)] \(.category) — \(.target) | risk=\(.risk_score) confidence=\(.confidence_score)/100"' "$rr"
    printf '\n## Technical Findings\n\n'
    jq -sr 'sort_by(-.confidence_score)[] |
      "### [\(.severity|ascii_upcase)] \(.category) — \(.target)\n\n"+
      "- **Reportability:** \(.reportability // "NEEDS_REVIEW")\n"+
      "- **Confidence:** \(.confidence_score)/100 (\(.confidence_tier))\n"+
      "- **Validation:** \(.validation_status)\n"+
      "- **Why it is real / current limit:** \(.validation_reason // .reasoning)\n"+
      "- **Why it matters:** \(.impact)\n"+
      "- **Affected asset:** \(.target)\n"+
      "- **Evidence references:** \((.evidence // [])|join(", "))\n"+
      "- **False-positive checks:** \((.fp_checks // [])|join(", "))\n"+
      "- **Reproduction:** \(.reproduction)\n"+
      "- **Recommended fix:** Validate the underlying condition, remove unnecessary exposure, enforce least privilege, and add a regression test specific to this finding.\n\n"' "$ff"
    printf '## Attack-Chain Hypotheses\n\n'
    printf 'These are prioritization hypotheses, not automatically promoted vulnerabilities.\n\n'
    [[ -f "$APEX_RUN_DIR/reports/attack_chains.json" ]] && jq -r '.[]|"- \(.host): \(.hypothesis) (validated=\(.validated_count), reportable=\(.reportable_count))"' "$APEX_RUN_DIR/reports/attack_chains.json"
  } > "$out"
  log_info "[REPORT-v3] professional report written: $out"
}

apex_apply_mode() {
  local mode; mode="$(cfg_get_default mode standard)"
  case "$mode" in
    standard) : ;;
    bounty)
      # Noise reduction without deleting phases: phases still execute, while
      # final candidate output is evidence-gated and impact-prioritized.
      cfg_set max_urls "$(cfg_get_default max_urls 1500)"
      log_info "mode=bounty: reportable, high-impact evidence is prioritized; review items remain separated" ;;
    *) log_error "invalid mode '$mode' (expected standard|bounty|research|hunter|research|hunter)"; return 2 ;;
  esac
}

# APEX vMAX — opt-in process memory guard; safe default preserves tool compatibility.
phase_vmax_resource_guard(){
  if cfg_bool enforce_memory_limit; then
    local mb kb; mb="$(cfg_get_default max_memory_mb 512)"; [[ "$mb" =~ ^[0-9]+$ ]] || mb=512; kb=$((mb*1024))
    if ulimit -v "$kb" 2>/dev/null; then log_info "[vMAX resources] virtual-memory limit=${mb}MiB"; else log_warn "[vMAX resources] platform refused memory limit; continuing without a false claim"; fi
  else
    log_debug "[vMAX resources] memory limit available but disabled for compatibility"
  fi
}
# APEX vMAX — Core helpers, evidence quality, scheduler, research mode
vmax_now(){ date -u +%Y-%m-%dT%H:%M:%SZ; }
vmax_hash(){ printf '%s' "$1"|apex_sha256; }
vmax_atomic(){ local d="$1" t="$1.tmp.$$"; jq -S . >"$t"&&mv -f "$t" "$d"; }
vmax_kb_dir(){ local d; d="$(cfg_get_default knowledge_dir '')"; [[ -n "$d" ]]&&printf '%s' "$d"||printf '%s/.apex_knowledge/%s' "$(dirname "$APEX_RUN_DIR")" "$(scope_summary|apex_sha256)"; }
vmax_kb_init(){ local d; d="$(vmax_kb_dir)"; mkdir -p "$d"; [[ -s "$d/knowledge.json" ]]||jq -n '{version:1,confirmed_findings:[],rejected_findings:[],false_positives:[],technologies:[],patterns:[],endpoint_history:[],behavior_rejections:[],scan_history:[]}' >"$d/knowledge.json"; printf '%s' "$d"; }
vmax_norm(){ sed -E 's/[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9:.+-]+Z?/[TIME]/g;s/[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}/[UUID]/g;s/[[:space:]]+/ /g'; }
vmax_similarity(){ local a="$1" b="$2" x y i u; [[ -f "$a"&&-f "$b" ]]||{ printf 0;return;}; [[ "$(vmax_norm<"$a"|apex_sha256)" == "$(vmax_norm<"$b"|apex_sha256)" ]]&&{ printf 100;return;}; x="$(mktemp)";y="$(mktemp)";vmax_norm<"$a"|tr -cs '[:alnum:]_' '\n'|awk 'length>=3'|sort -u>"$x";vmax_norm<"$b"|tr -cs '[:alnum:]_' '\n'|awk 'length>=3'|sort -u>"$y";i="$(comm -12 "$x" "$y"|wc -l)";u="$(cat "$x" "$y"|sort -u|wc -l)";rm -f "$x" "$y";((u>0))&&printf '%d' $((i*100/u))||printf 0; }
vmax_structure(){ jq -e . "$1">/dev/null 2>&1&&jq -S '[paths(scalars)|map(tostring)|join(".")]|unique' "$1"|apex_sha256||printf ''; }
vmax_errors(){ { grep -Eio '(exception|stack trace|fatal error|sqlstate|syntax error|debug mode|internal server error|panic:)' "$1" 2>/dev/null || true; } | wc -l | tr -d ' '; }
vmax_evidence_quality(){ local l="$1" s c n q=0;s="$(jq -r '.validation_status//""'<<<"$l")";c="$(jq -r '(.fp_checks//[])|join(" ")'<<<"$l")";n="$(jq '(.evidence//[])|length'<<<"$l")";((n>0))&&q=10;grep -qiE 'regex|format|entropy|tool|matcher'<<<"$c"&&q=30;grep -qiE 'signature|schema|content'<<<"$c"&&q=50;[[ "$s" == reproduced ]]&&q=75;grep -qiE 'independent|cross-tool|manual-confirmation'<<<"$c"&&q=95;printf %d "$q"; }
phase_vmax_scheduler(){ local u="$APEX_RUN_DIR/db/urls.ndjson" o="$APEX_RUN_DIR/reports/priority_queue.json"; [[ -f "$u" ]]||:>"$u";jq -s 'def sc:(if test("(?i)/(admin|api|graphql|oauth|account|billing|payment|upload|export|internal)")then 40 else 0 end)+(if contains("?")then 15 else 0 end)+(if test("(?i)(id|user|account|role|token|redirect|url)=")then 25 else 0 end)+(if test("(?i)/[0-9]{2,}([/?#]|$)|[0-9a-f]{8}-[0-9a-f-]{27,}")then 20 else 0 end);map(.url//empty)|unique|map({url:.,priority_score:sc,analysis_key:("endpoint|"+.)})|sort_by(-.priority_score)' "$u">"$o";log_info "[vMAX scheduler] queued=$(jq length "$o")"; }
