phase_vmax_api(){ local o="$APEX_RUN_DIR/reports/api_intelligence.json" n="$APEX_RUN_DIR/reports/api_endpoints.ndjson" h="$APEX_RUN_DIR/raw/api_hosts.txt" d="$APEX_RUN_DIR/raw/vmax_api" b p url f t c=0;mkdir -p "$d";:>"$n";[[ -s "$h" ]]||store_query web '.url' -r >"$h" 2>/dev/null||true;t="$(cfg_get_default timeout 15)";if _recon_ok&&apex_have curl;then while IFS= read -r b;do url_in_scope "$b"||continue;b="${b%/}";for p in /openapi.json /swagger.json /v2/api-docs /v3/api-docs /.well-known/openid-configuration;do c=$((c+1));((c>100))&&break 2;url="$b$p";f="$d/$(vmax_hash "$url").json";curl -sS -L --max-time "$t" --max-filesize "$(cfg_get_default max_response_bytes 1048576)" "$url" -o "$f" 2>/dev/null||continue;jq -e . "$f">/dev/null 2>&1||continue;jq -e '((.openapi or .swagger)and(.paths|type=="object"))' "$f">/dev/null 2>&1&&_vmax_openapi "$b" "$f">>"$n";jq -e '.issuer and (.authorization_endpoint or .token_endpoint)' "$f">/dev/null 2>&1&&jq -c --arg base "$b" '{base:$base,type:"oidc",issuer,authorization_endpoint,token_endpoint,jwks_uri,scopes_supported,response_types_supported,grant_types_supported,code_challenge_methods_supported}' "$f">"$d/oidc_$(vmax_hash "$b").json"||true;done;done<"$h";fi;jq -n --slurpfile ep "$n" --slurpfile oidc <(cat "$d"/oidc_*.json 2>/dev/null||true) '{openapi_endpoints:$ep,oidc:$oidc,jwt_metadata:[],graphql:{mapped:([$ep[]|select(.path|test("graphql";"i"))]|length)},summary:{endpoints:($ep|length),sensitive:([$ep[]|select(.sensitive)]|length),missing_security:([$ep[]|select(.missing_security_scheme)]|length),object_identifiers:([$ep[]|select(.object_id)]|length)}}'>"$o";log_info "[vMAX API] endpoints=$(jq '.summary.endpoints' "$o")"; }
phase_vmax_http(){ local o="$APEX_RUN_DIR/reports/http_intelligence.json" n="$APEX_RUN_DIR/reports/http_assets.ndjson" l="$APEX_RUN_DIR/raw/vmax_http.txt" u p hdr cache cookie fw err;:>"$n";store_query web '.url' -r 2>/dev/null|sort -u|head -n "$(cfg_get_default http_intel_max_hosts 100)">"$l"||true;if _recon_ok&&apex_have curl;then while IFS= read -r u;do url_in_scope "$u"||continue;p="$APEX_RUN_DIR/raw/httpintel_$(vmax_hash "$u")";_apex_http_capture "$u" "$p"||continue;hdr="$(tr -d '\r'<"$p.headers")";cache="$(grep -iE '^(cache-control|age|etag|expires|vary|x-cache|cf-cache-status):'<<<"$hdr"|redact_stream|jq -Rsc .)";cookie="$(grep -i '^set-cookie:'<<<"$hdr"|awk 'BEGIN{IGNORECASE=1}{print "Secure="($0~/secure/?"yes":"no")",HttpOnly="($0~/httponly/?"yes":"no")",SameSite="($0~/samesite/?"yes":"no")}'|jq -Rsc 'split("\n")|map(select(length>0))')";fw="$( { grep -iE '^(server|x-powered-by|x-aspnet-version):'<<<"$hdr";grep -aoEi '(wp-content|__NEXT_DATA__|ng-version|laravel|django|rails|spring boot|express)' "$p.body" 2>/dev/null|head -20;}|redact_stream|jq -Rsc 'split("\n")|map(select(length>0))|unique')";err="$(vmax_errors "$p.body")";jq -cn --arg url "$u" --argjson meta "$(cat "$p.meta")" --argjson cache "$cache" --argjson cookies "$cookie" --argjson frameworks "$fw" --argjson errors "$err" '{url:$url,status:$meta.status,final_url:$meta.final_url,redirected:($meta.url!=$meta.final_url),cache_headers:$cache,cookies:$cookies,frameworks:$frameworks,error_indicators:$errors,evidence_quality:50,classification:"INTELLIGENCE"}'>>"$n";done<"$l";fi;jq -s '{assets:.,count:length,redirecting:([.[]|select(.redirected)]|length),with_errors:([.[]|select(.error_indicators>0)]|length),frameworks:(map(.frameworks[])|unique)}' "$n">"$o";log_info "[vMAX HTTP] assets=$(jq .count "$o")"; }
