phase_vmax_behavior(){ local plan="$(cfg_get_default behavior_plan '')" n="$APEX_RUN_DIR/reports/behavior_signals.ndjson" o="$APEX_RUN_DIR/reports/behavior_analysis.json" q key b m bs ms bl ml sim bh mh js1 js2 e1 e2 ref=0 c=0;:>"$n";[[ -s "$plan" ]]||{ jq -n '{signals:[],count:0,note:"No behavior plan supplied; no requests invented."}'>"$o";return;};while IFS= read -r q;do jq -e .<<<"$q">/dev/null 2>&1||continue;c=$((c+1));((c>$(cfg_get_default behavior_max_requests 100)))&&break;key="behavior|$(jq -cS .<<<"$q"|apex_sha256)";if jq -e --arg k "$key" '(.behavior_rejections//[])|index($k)!=null' "$(vmax_kb_init)/knowledge.json" >/dev/null 2>&1;then continue;fi;b="$APEX_RUN_DIR/raw/beh_$(vmax_hash "$key")_b";m="$APEX_RUN_DIR/raw/beh_$(vmax_hash "$key")_m";_vmax_req "$q" baseline "$b"||continue;_vmax_req "$q" modified "$m"||continue;bs="$(jq .status "$b.meta")";ms="$(jq .status "$m.meta")";bl="$(jq .bytes "$b.meta")";ml="$(jq .bytes "$m.meta")";sim="$(vmax_similarity "$b.body" "$m.body")";bh="$(tr -d '\r'<"$b.headers"|awk -F: '/^[A-Za-z0-9-]+:/{print tolower($1)}'|sort -u|apex_sha256)";mh="$(tr -d '\r'<"$m.headers"|awk -F: '/^[A-Za-z0-9-]+:/{print tolower($1)}'|sort -u|apex_sha256)";js1="$(vmax_structure "$b.body")";js2="$(vmax_structure "$m.body")";e1="$(vmax_errors "$b.body")";e2="$(vmax_errors "$m.body")";local marker;marker="$(jq -r '.marker//.modified.marker//""'<<<"$q")";[[ -n "$marker" ]]&&grep -qF "$marker" "$m.body"&&ref=1||ref=0;jq -cn --arg key "$key" --arg url "$(jq -r .url<<<"$q")" --arg method "$(jq -r '.method//"GET"|ascii_upcase'<<<"$q")" --argjson bs "$bs" --argjson ms "$ms" --argjson bl "$bl" --argjson ml "$ml" --argjson sim "$sim" --arg bh "$bh" --arg mh "$mh" --arg j1 "$js1" --arg j2 "$js2" --argjson e1 "$e1" --argjson e2 "$e2" --argjson ref "$ref" '{type:"behavior_signal",analysis_key:$key,url:$url,method:$method,evidence_quality_score:75,differences:{status:($bs!=$ms),headers:($bh!=$mh),body_similarity:$sim,length_delta:($ml-$bl),structure:($j1!=$j