# APEX vMAX — five-gate report control and persistent learning memory
phase_vmax_gate(){ local f="$APEX_RUN_DIR/db/findings.ndjson" e="$APEX_RUN_DIR/db/evidence.ndjson" n="$APEX_RUN_DIR/reports/quality_gate.ndjson" o="$APEX_RUN_DIR/reports/quality_gate.json" l id t s v r ev miss scope evidence valid conf dup d q pass eid;[[ -f "$f" ]]||:>"$f";[[ -f "$e" ]]||:>"$e";:>"$n";while IFS= read -r l;do [[ -n "$l" ]]||continue;id="$(jq -r .id<<<"$l")";t="$(jq -r .target<<<"$l")";s="$(jq -r '.confidence_score//0'<<<"$l")";v="$(jq -r '.validation_status//""'<<<"$l")";r="$(jq -r '.reportability//"NEEDS_REVIEW"'<<<"$l")";scope=0;if [[ "$t" == http* ]];then url_in_scope "$t"&&scope=1||:;else in_scope "$t"&&scope=1||:;fi;ev="$(jq -c '.evidence//[]'<<<"$l")";miss=0;while IFS= read -r eid;do jq -e --arg x "$eid" 'select(.id==$x)' "$e">/dev/null 2>&1||miss=$((miss+1));done<<<"$(jq -r '.[]'<<<"$ev")";evidence=0;[[ "$(jq length<<<"$ev")" -gt 0&&"$miss" -eq 0 ]]&&evidence=1;valid=0;[[ "$v" == reproduced||"$v" == context-verified ]]&&valid=1;conf=0;((s>=75))&&conf=1;d="$(jq -r '.dedupe_key//""'<<<"$l")";dup="$(jq -s --arg d "$d" '[.[]|select((.dedupe_key//"")==$d)]|length' "$f")";[[ "$dup" -eq 1 ]]&&dup=1||dup=0;q="$(vmax_evidence_quality "$l")";pass=false;((scope&&evidence&&valid&&conf&&dup))&&[[ "$r" == REPORTABLE ]]&&pass=true;jq -cn --arg id "$id" --arg target "$t" --arg validation "$v" --arg reportability "$r" --argjson confidence "$s" --argjson quality "$q" --argjson scope "$scope" --argjson evidence "$evidence" --argjson valid "$valid" --argjson conf "$conf" --argjson dup "$dup" --argjson pass "$pass" '{finding_id:$id,target:$target,reportability:$reportability,validation_status:$validation,confidence:$confidence,evidence_quality:$quality,checks:{scope:($scope==1),evidence:($evidence==1),validation:($valid==1),confidence:($conf==1),duplicate:($dup==1)},passes_vulnerability_gate:$pass}'>>"$n";done<"$f";jq -s '{total:length,passed:([.[]|select(.passes_vulnerability_gate)]|length),blocked:([.[]|select(.passes_vulnerability_gate|not)]|length),minimum_evidence_quality:{http_status_only:10,regex_match:30,content_signature:50,repeated_validation:75,independent_confirmation:95},records:.}' "$n">"$o";log_info "[vMAX gate] passed=$(jq .passed "$o") blocked=$(jq .blocked "$o")"; }
phase_vmax_knowledge(){ local k f lock m g db b tmp now fd;k="$(vmax_kb_init)";f="$k/knowledge.json";lock="$k/.lock";m="$APEX_RUN_DIR/reports/application_model.json";g="$APEX_RUN_DIR/reports/quality_gate.json";db="$APEX_RUN_DIR/db/findings.ndjson";b="$APEX_RUN_DIR/reports/behavior_signals.ndjson";[[ -s "$m" ]]||jq -n '{technologies:[],endpoints:[]}'>"$m";[[ -s "$g" ]]||jq -n '{records:[]}'>"$g";[[ -f "$db" ]]||:>"$db";[[ -f "$b" ]]||:>"$b";now="$(vmax_now)";exec {fd}>>"$lock";flock -x "$fd";tmp="$f.tmp.$$";jq -n --slurpfile old "$f" --slurpfile model "$m" --slurpfile gate "$g" --slurpfile findings "$db" --slurpfile behavior "$b" --arg now "$now" --arg run "$APEX_RUN_DIR" '($old[0])as$o|($gate[0].records//[])as$gr|($gr|map(select(.passes_vulnerability_gate).finding_id))as$passed|($findings|map(. as $x|select($passed|index($x.id)!=null)|.+{learned_at:$now,run:$run,signal_key:(.category+"|"+.target)}))as$c|($findings|map(. as $x|select(($passed|index($x.id))==null)|.+{learned_at:$now,run:$run,signal_key:(.category+"|"+.target)}))as$r|($findings|map(select(.validation_status=="not-reproduced")|.+{learned_at:$now}))as$fp|{version:1,confirmed_findings:(($o.confirmed_findings//[])+$c|unique_by(.dedupe_key)),rejected_findings:(($o.rejected_findings//[])+$r|unique_by(.dedupe_key)),false_positives:(($o.false_positives//[])+$fp|unique_by(.dedupe_key)),technologies:(($o.technologies//[])+($model[0].technologies//[])|unique),patterns:(($o.patterns//[])+($findings|map(.category))|unique),endpoint_history:(($o.endpoint_history//[])+[{scan:$now,run:$run,endpoints:($model[0].endpoints//[])}]),behavior_rejections:(($o.behavior_rejections//[])+($behavior|map(select((.differences.status|not)and(.differences.headers|not)and(.differences.structure|not)and(.differences.reflection|not)and.differences.body_similarity>=92)|.analysis_key))|unique),scan_history:(($o.scan_history//[])+[{scan:$now,run:$run,confirmed:($c|length),rejected:($r|length)}])}'>"$tmp"&&mv "$tmp" "$f";flock -u "$fd";exec {fd}>&-;cp "$f" "$APEX_RUN_DIR/reports/knowledge_snapshot.json";log_info "[vMAX knowledge] scans=$(jq '.scan_history|length' "$f")"; }
# APEX vMAX — backwards-compatible MAX report
phase_vmax_report(){ local o="$APEX_RUN_DIR/reports/professional_security_report.md" m="$APEX_RUN_DIR/reports/application_model.json" g="$APEX_RUN_DIR/reports/quality_gate.json" r="$APEX_RUN_DIR/reports/research_paths.json" nx="$APEX_RUN_DIR/reports/next_steps.json" k="$APEX_RUN_DIR/reports/knowledge_snapshot.json" f="$APEX_RUN_DIR/db/findings.ndjson" ids;[[ -s "$m" ]]||jq -n '{hosts:[],endpoints:[],technologies:[],sensitive_areas:[],historical_changes:{}}'>"$m";[[ -s "$g" ]]||jq -n '{passed:0,blocked:0,records:[],minimum_evidence_quality:{}}'>"$g";[[ -s "$r" ]]||jq -n '{paths:[]}'>"$r";[[ -s "$nx" ]]||jq -n '{suggestions:[]}'>"$nx";[[ -s "$k" ]]||jq -n '{rejected_findings:[],false_positives:[]}'>"$k";[[ -f "$f" ]]||:>"$f";ids="$(jq -c '[.records[]|select(.passes_vulnerability_gate)|.finding_id]' "$g")";{ printf '# APEX vMAX Professional Security Report\n\n## Executive Summary\n\n';jq -nr --slurpfile m "$m" --slurpfile g "$g" --slurpfile r "$r" '"- Hosts: \($m[0].hosts|length)\n- Endpoints: \($m[0].endpoints|length)\n- Technologies: \($m[0].technologies|length)\n- Confirmed by quality gate: \($g[0].passed)\n- Blocked from vulnerability reporting: \($g[0].blocked)\n- Research paths: \($r[0].paths|length)\n"';printf '\n> A vulnerability must pass scope, evidence, validation, confidence and duplicate gates.\n\n## Attack Surface\n\n';jq -r '"### Hosts\n"+((.hosts//[])|map("- "+.)|join("\n"))+"\n\n### Technologies\n"+((.technologies//[])|map("- "+.)|join("\n"))+"\n\n### Sensitive Areas\n"+((.sensitive_areas//[])|map("- "+.)|join("\n"))' "$m";printf '\n\n## Confirmed Findings\n\n';if [[ "$(jq length<<<"$ids")" -eq 0 ]];then printf '_No finding passed all quality gates._\n';else jq -sr --argjson ids "$ids" '.[] as $x|select($ids|index($x.id)!=null)|$x|"### [\(.severity|ascii_upcase)] \(.category) — \(.target)\n- Confidence: \(.confidence_score)/100\n- Validation: \(.validation_status)\n- Evidence: \((.evidence//[])|join(", "))\n- Why it matters: \(.impact)\n- Reproduction: \(.reproduction)\n"' "$f";fi;printf '\n## Research Paths\n\n';jq -r '.paths[]?|"### [\(.priority)] \(.target)\n- Score: \(.priority_score)\n- Reasons: \(.reasons|join("; "))\n- Safe next steps: \(.safe_next_steps|join("; "))\n"' "$r";printf '\n## Evidence Quality and Validation History\n\n';jq -r '.minimum_evidence_quality|to_entries[]?|"- \(.key): \(.value)"' "$g";jq -r '.records[]?|"- \(.target): quality=\(.evidence_quality), confidence=\(.confidence), gate=\(.passes_vulnerability_gate)"' "$g";printf '\n## Rejected Findings\n\n';jq -r '(.rejected_findings//[])|.[-50:][]?|"- \(.category) — \(.target): \(.validation_status//"review")"' "$k";printf '\n## False Positive Analysis\n\n';jq -r '(.false_positives//[])|.[-50:][]?|"- \(.category) — \(.target): not reproduced"' "$k";printf '\n## Historical Changes\n\n';jq -r '"- New endpoints: \((.historical_changes.new_endpoints//[])|length)\n- Removed endpoints: \((.historical_changes.removed_endpoints//[])|length)\n- New technologies: \((.historical_changes.new_technologies//[])|length)"' "$m";printf '\n\n## Manual Testing Recommendations\n\n';jq -r '.suggestions[]?|"- [\(.priority)] \(.action) — \(.safety)"' "$nx";printf '\n## Limitations\n\n- Behavioral differences and research paths are not vulnerabilities.\n- Authorization requires controlled identities and business context.\n- Bash cannot execute browser JavaScript, perform semantic AST analysis, or provide distributed graph analytics; those capabilities are not claimed.\n';}>"$o";log_info "[vMAX report] $o"; }

# APEX vMAX+ — controlled identity differential engine.
# Identity secrets are referenced by environment-variable name and are never written to reports.
vplus_identity_header(){
  local file="$1" id="$2" env_name
  env_name="$(jq -r --arg id "$id" '.identities[]|select(.id==$id)|.header_env//empty' "$file" 2>/dev/null | head -1)"
  [[ "$env_name" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || return 1
  [[ -n "${!env_name-}" ]] || return 1
  printf '%s' "${!env_name}"
}
_vplus_identity_request(){
  local q="$1" id="$2" identities="$3" prefix="$4" method url body secret h
  method="$(jq -r '.method//"GET"|ascii_upcase' <<<"$q")"
  url="$(jq -r '.url' <<<"$q")"
  body="$(jq -r '.body//""' <<<"$q")"
  case "$method" in GET|POST|PUT|PATCH|DELETE) ;; *) return 2;; esac
  url_in_scope "$url" || return 3
  [[ "$method" == GET ]] || _active_ok || return 4
  secret="$(vplus_identity_header "$identities" "$id")" || return 5
  local args=(-X "$method" -H "$secret")
  while IFS= read -r h; do [[ -n "$h" ]] && args+=(-H "$h"); done <<<"$(jq -r '.headers//{}|to_entries[]?|"\(.key): \(.value)"' <<<"$q")"
  [[ -n "$body" ]] && args+=(--data-binary "$body")
  _apex_http_capture "$url" "$prefix" "${args[@]}"
}
phase_vplus_identity(){
  local identities plan out obs max q key id role rank prefix status bytes object sensitive
  identities="$(cfg_get_default identities_file '')"; plan="$(cfg_get_default identity_plan '')"
  out="$APEX_RUN_DIR/reports/identity_differential.json"; obs="$APEX_RUN_DIR/reports/identity_observations.ndjson"
  :>"$obs"
  if [[ ! -s "$identities" || ! -s "$plan" ]]; then jq -n '{classification:"CONTROLLED_IDENTITY_SIGNALS",comparisons:[],count:0,note:"Explicit identities_file and identity_plan are required; no requests invented."}' >"$out"; return; fi
  jq -e '.identities|type=="array" and length>=2 and all(.[];.id and .role and .header_env and (.rank|type=="number"))' "$identities" >/dev/null || { log_warn '[vMAX+ identity] invalid identities schema'; jq -n '{classification:"CONTROLLED_IDENTITY_SIGNALS",comparisons:[],count:0,error:"invalid identities schema"}' >"$out"; return; }
  max="$(cfg_get_default identity_max_requests 100)"; local n=0
  while IFS= read -r q; do
    jq -e '.url and (.identities|type=="array")' <<<"$q" >/dev/null 2>&1 || continue
    key="identity|$(jq -cS . <<<"$q"|apex_sha256)"; object="$(jq -r '.object//""' <<<"$q")"
    while IFS= read -r id; do
      n=$((n+1)); if ((n>max)); then break 2; fi
      role="$(jq -r --arg id "$id" '.identities[]|select(.id==$id)|.role' "$identities")"; rank="$(jq -r --arg id "$id" '.identities[]|select(.id==$id)|.rank' "$identities")"
      prefix="$APEX_RUN_DIR/raw/id_$(vmax_hash "$key|$id")"
      _vplus_identity_request "$q" "$id" "$identities" "$prefix" || continue
      status="$(jq '.status' "$prefix.meta")"; bytes="$(jq '.bytes' "$prefix.meta")"
      sensitive="$(grep -Eio '"(email|phone|address|token|secret|ssn|credit|balance|invoice|owner|user_id)"[[:space:]]*:' "$prefix.body" 2>/dev/null | sort -u | wc -l | tr -d ' ' || true)"; sensitive="${sensitive:-0}"
      local object_seen=false; [[ -n "$object" ]] && grep -qF "$object" "$prefix.body" 2>/dev/null && object_seen=true
      jq -cn --arg key "$key" --arg id "$id" --arg role "$role" --argjson rank "$rank" --arg url "$(jq -r .url<<<"$q")" --arg method "$(jq -r '.method//"GET"|ascii_upcase'<<<"$q")" --arg object "$object" --argjson status "$status" --argjson bytes "$bytes" --arg body_hash "$(apex_sha256 <"$prefix.body")" --arg structure "$(vmax_structure "$prefix.body")" --argjson sensitive "$sensitive" --argjson object_seen "$object_seen" '{analysis_key:$key,identity:$id,role:$role,rank:$rank,url:$url,method:$method,object:$object,status:$status,length:$bytes,body_hash:$body_hash,structure_hash:$structure,sensitive_field_indicators:$sensitive,object_reference_seen:$object_seen}' >>"$obs"
    done <<<"$(jq -r '.identities[]' <<<"$q")"
  done <"$plan"
  jq -s 'group_by(.analysis_key)|map(. as $g|{analysis_key:$g[0].analysis_key,target:$g[0].url,method:$g[0].method,object:$g[0].object,observations:$g,comparisons:([$g[] as $a|$g[] as $b|select($a.rank<$b.rank)|{identity_a:$a.identity,role_a:$a.role,identity_b:$b.identity,role_b:$b.role,status_difference:($a.status!=$b.status),length_difference:($a.length-$b.length),structure_difference:($a.structure_hash!=$b.structure_hash),content_difference:($a.body_hash!=$b.body_hash),same_response_fingerprint:($a.body_hash==$b.body_hash),lower_identity_success:($a.status>=200 and $a.status<300),object_visible_to_lower:$a.object_reference_seen,sensitive_to_lower:($a.sensitive_field_indicators>0),boundary_signal:(($a.status>=200 and $a.status<300) and ($a.object_reference_seen or $a.sensitive_field_indicators>0) and ($a.body_hash==$b.body_hash)),classification:"IDENTITY_DIFFERENTIAL_SIGNAL",automatic_exploitation:false}])})|{classification:"CONTROLLED_IDENTITY_SIGNALS_NOT_VULNERABILITIES",count:length,tests:.,boundary_signals:([.[].comparisons[]|select(.boundary_signal)]|length)}' "$obs" >"$out"
  log_info "[vMAX+ identity] tests=$(jq .count "$out") boundary_signals=$(jq .boundary_signals "$out")"
}
# APEX vMAX+ — offline HAR/session learning and workflow intelligence.
phase_vplus_har(){
  local har out
  har="$(cfg_get_default har_file '')"; out="$APEX_RUN_DIR/reports/session_intelligence.json"
  if [[ ! -s "$har" ]]; then jq -n '{source:"none",transactions:[],sessions:[],api_calls:[],objects:[],actions:[],note:"No HAR supplied."}' >"$out"; return; fi
  jq -e '.log.entries|type=="array"' "$har" >/dev/null || { jq -n '{error:"invalid HAR",transactions:[]}' >"$out"; return; }
  jq '{source:"HAR_OFFLINE_NO_REPLAY",transactions:[.log.entries[]|(try (.request.url|capture("^(?<scheme>https?)://(?<host>[^/:?#]+)(?<path>/[^?#]*)?")) catch {}) as $u|{time:.startedDateTime,method:(.request.method|ascii_upcase),url:.request.url,host:($u.host//""),path:($u.path//"/"),status:(.response.status//0),mime:(.response.content.mimeType//""),duration_ms:(.time//0),authenticated:([.request.headers[]?.name|ascii_downcase]|any(.=="authorization" or .=="cookie")),parameter_names:([.request.queryString[]?.name,.request.postData.params[]?.name]|map(select(.!=null))|unique),object_identifiers:([.request.url|scan("(?:/|=)([0-9]{2,}|[0-9a-fA-F-]{16,})")]|unique),action:(if (.request.url|test("(?i)(login|signin|oauth|session)")) then "login" elif (.request.url|test("(?i)(dashboard|home)")) then "dashboard" elif (.request.url|test("(?i)(create|new)")) then "create" elif (.request.url|test("(?i)(approve|accept)")) then "approve" elif (.request.url|test("(?i)(pay|charge|checkout)")) then "pay" elif (.request.url|test("(?i)(refund|reverse)")) then "refund" elif (.request.url|test("(?i)(delete|remove)")) or .request.method=="DELETE" then "delete" elif (.request.url|test("(?i)(update|edit)")) or (.request.method|test("PUT|PATCH")) then "update" elif .request.method=="POST" then "create" else "read" end)}],secrets_stored:false} | .sessions=([.transactions|group_by(.host)[]|{host:.[0].host,authenticated:(any(.authenticated)),sequence:map(.action),transaction_count:length}]) | .api_calls=[.transactions[]|select(.path|test("(?i)(/api/|/graphql|/v[0-9]+/)"))] | .objects=([.transactions[].object_identifiers[]]|unique) | .actions=([.transactions[].action]|unique)' "$har" >"$out"
  log_info "[vMAX+ HAR] transactions=$(jq '.transactions|length' "$out") api=$(jq '.api_calls|length' "$out")"
}
phase_vplus_workflow(){
  local session spec out
  session="$APEX_RUN_DIR/reports/session_intelligence.json"; spec="$(cfg_get_default workflow_file '')"; out="$APEX_RUN_DIR/reports/workflow_intelligence.json"
  [[ -s "$session" ]] || jq -n '{transactions:[]}' >"$session"
  if [[ ! -s "$spec" ]]; then jq -n --slurpfile s "$session" '{classification:"INFERRED_WORKFLOW_MAP",workflows:($s[0].sessions//[]|map({name:.host,observed_steps:.sequence,anomalies:[],automatic_replay:false})),note:"No workflow specification supplied; ordering anomalies are not asserted."}' >"$out"; return; fi
  jq -e '.workflows|type=="array"' "$spec" >/dev/null || { jq -n '{error:"invalid workflow schema",workflows:[]}' >"$out"; return; }
  jq -n --slurpfile s "$session" --slurpfile w "$spec" 'def idx($a;$x):([range(0;($a|length)) as $i|select($a[$i]==$x)|$i][0]//-1); {classification:"WORKFLOW_RESEARCH_HYPOTHESES",workflows:[($w[0].workflows[] as $wf|([$s[0].transactions[]|select(.path|test($wf.match;"i"))|.action]) as $obs|{name:$wf.name,match:$wf.match,expected_steps:$wf.steps,observed_steps:$obs,missing_steps:[$wf.steps[] as $step|select(($obs|index($step))==null)|$step],wrong_order:[range(0;($wf.steps|length)-1) as $i|select(idx($obs;$wf.steps[$i])>=0 and idx($obs;$wf.steps[$i+1])>=0 and idx($obs;$wf.steps[$i])>idx($obs;$wf.steps[$i+1]))|{before:$wf.steps[$i],after:$wf.steps[$i+1]}],state_transition_signals:[range(0;($obs|length)-1) as $i|select(($wf.steps|index($obs[$i]))!=null and ($wf.steps|index($obs[$i+1]))!=null and ($wf.steps|index($obs[$i+1]))<($wf.steps|index($obs[$i])))|{from:$obs[$i],to:$obs[$i+1]}],classification:"WORKFLOW_SIGNAL",automatic_replay:false})]}' >"$out"
  log_info "[vMAX+ workflow] workflows=$(jq '.workflows|length' "$out")"
}
# APEX vMAX+ — bounded lexical JavaScript call/guard analysis (not a semantic AST).
phase_vplus_deep_js(){
  local urls="$APEX_RUN_DIR/raw/js_urls.txt" raw="$APEX_RUN_DIR/reports/deep_js_calls.ndjson" out="$APEX_RUN_DIR/reports/deep_javascript_map.json" src file i=0 line_no line guard guard_line direct var resolved assign name value
  :>"$raw"
  [[ -f "$urls" ]] || { jq -n '{analysis:"BOUNDED_LEXICAL_NOT_AST",calls:[],sensitive_functions:[],client_authorization_guards:[]}' >"$out"; return; }
  while IFS= read -r src; do
    file="$APEX_RUN_DIR/raw/js_$i.body"; i=$((i+1)); [[ -s "$file" ]] || continue
    declare -A vars=(); guard=""; guard_line=0; line_no=0
    while IFS= read -r line; do
      line_no=$((line_no+1))
      assign="$(printf '%s\n' "$line"|sed -nE 's/.*(const|let|var)[[:space:]]+([A-Za-z_$][A-Za-z0-9_$]*)[[:space:]]*=[[:space:]]*"([^"]+)".*/\2\t\3/p'|head -1)"
      if [[ -n "$assign" ]]; then name="${assign%%$'\t'*}"; value="${assign#*$'\t'}"; vars["$name"]="$value"; fi
      if grep -Eqi '(role|permission|isAdmin|is_admin|canAccess).*(admin|owner|manager|export|billing)' <<<"$line"; then guard="$(grep -Eio '(admin|owner|manager|billing|export|[A-Za-z_]+permission)'<<<"$line"|head -1)"; guard_line=$line_no; fi
      if ((line_no-guard_line>8)); then guard=""; fi
      direct="$(printf '%s\n' "$line"|grep -Eo '(fetch|axios\.(get|post|put|patch|delete))[[:space:]]*\([[:space:]]*"[^"]+"'|sed -E 's/.*"([^"]+)"$/\1/'|head -1 || true)"
      if [[ -n "$direct" ]]; then jq -cn --arg source "$src" --argjson line "$line_no" --arg endpoint "$direct" --arg guard "$guard" '{source:$source,line:$line,endpoint:$endpoint,resolution:"direct_literal",client_role_guard:(if $guard=="" then null else $guard end),sensitive:($endpoint|test("(?i)(admin|export|billing|refund|payment|users|account|secret)")),confidence:75}' >>"$raw"; fi
      var="$(printf '%s\n' "$line"|sed -nE 's/.*(fetch|axios\.(get|post|put|patch|delete))[[:space:]]*\([[:space:]]*([A-Za-z_$][A-Za-z0-9_$]*).*/\3/p'|head -1)"
      if [[ -n "$var" && -n "${vars[$var]-}" ]]; then resolved="${vars[$var]}"; jq -cn --arg source "$src" --argjson line "$line_no" --arg endpoint "$resolved" --arg variable "$var" --arg guard "$guard" '{source:$source,line:$line,endpoint:$endpoint,variable:$variable,resolution:"local_string_binding",client_role_guard:(if $guard=="" then null else $guard end),sensitive:($endpoint|test("(?i)(admin|export|billing|refund|payment|users|account|secret)")),confidence:60}' >>"$raw"; fi
    done <"$file"
    unset vars
  done <"$urls"
  jq -s '{analysis:"BOUNDED_LEXICAL_DATAFLOW_NOT_SEMANTIC_AST",calls:(unique_by(.source,.line,.endpoint)),sensitive_functions:[.[]|select(.sensitive)],client_authorization_guards:[.[]|select(.client_role_guard!=null)],limitations:["No browser execution","No semantic AST","Bindings are local string assignments only","Client-side guards are research indicators, not server authorization"]}' "$raw" >"$out"
  log_info "[vMAX+ deep-js] calls=$(jq '.calls|length' "$out") guarded=$(jq '.client_authorization_guards|length' "$out")"
}
# APEX vMAX+ — Nuclei template memory and bug-bounty target prioritization.
phase_vplus_template_intelligence(){
  local signals="$APEX_RUN_DIR/reports/nuclei_intelligence.json" model="$APEX_RUN_DIR/reports/application_model.json" out="$APEX_RUN_DIR/reports/template_intelligence.json" kb hist decisions
  kb="$(vmax_kb_init)"; hist="$kb/template_history.json"; decisions="$(cfg_get_default decisions_file '')"
  [[ -s "$signals" ]] || jq -n '{signals:[]}' >"$signals"; [[ -s "$model" ]] || jq -n '{technologies:[]}' >"$model"; [[ -s "$hist" ]] || jq -n '{templates:{}}' >"$hist"
  if [[ -s "$decisions" ]]; then
    jq -s --slurpfile old "$hist" 'reduce (.[]|select(.template and (.decision=="rejected" or .decision=="confirmed"))) as $d ($old[0]; .templates[$d.template] = ((.templates[$d.template]//{observations:0,false_positives:0,confirmed:0}) | .observations+=1 | if $d.decision=="rejected" then .false_positives+=1 else .confirmed+=1 end))' "$decisions" >"$hist.tmp" && mv "$hist.tmp" "$hist"
  fi
  jq -n --slurpfile s "$signals" --slurpfile m "$model" --slurpfile h "$hist" '{classification:"TEMPLATE_SIGNAL_MEMORY",templates:[($s[0].signals[]? as $x|($h[0].templates[$x.template]//{observations:0,false_positives:0,confirmed:0}) as $p|{template:$x.template,target:$x.target,technologies:($m[0].technologies//[]),previous:$p,noise_score:([80,($p.false_positives*20)]|min),priority_adjustment:(-([60,($p.false_positives*15)]|min)),classification:"TEMPLATE_SIGNAL_ONLY"})],history:$h[0].templates}' >"$out"
  log_info "[vMAX+ templates] templates=$(jq '.templates|length' "$out")"
}
vplus_asset_bonus(){ local file="$1" target="$2"; [[ -s "$file" ]] || { echo 0; return; }; jq -r --arg t "$target" '[.rules[]?|select($t|test(.match;"i"))|.value]|max//0' "$file" 2>/dev/null || echo 0; }
phase_vplus_hunter(){
  local auth="$APEX_RUN_DIR/reports/authorization_map.json" deep="$APEX_RUN_DIR/reports/deep_javascript_map.json" ident="$APEX_RUN_DIR/reports/identity_differential.json" work="$APEX_RUN_DIR/reports/workflow_intelligence.json" out="$APEX_RUN_DIR/reports/hunter_targets.json" av tmp target bonus top
  [[ -s "$auth" ]] || jq -n '{endpoints:[]}' >"$auth"; [[ -s "$deep" ]] || jq -n '{calls:[]}' >"$deep"; [[ -s "$ident" ]] || jq -n '{tests:[]}' >"$ident"; [[ -s "$work" ]] || jq -n '{workflows:[]}' >"$work"
  av="$(cfg_get_default asset_values_file '')"; top="$(cfg_get_default hunter_top 20)"; tmp="$APEX_RUN_DIR/reports/hunter_candidates.ndjson"; :>"$tmp"
  while IFS= read -r target; do
    bonus="$(vplus_asset_bonus "$av" "$target")"
    jq -cn --arg t "$target" --argjson b "$bonus" --slurpfile a "$auth" --slurpfile d "$deep" --slurpfile i "$ident" --slurpfile w "$work" '($a[0].endpoints|map(select((.base+.path)==$t))[0]//{}) as $e|([$d[0].calls[]?|select(.endpoint==$t and .client_role_guard!=null)]|length>0) as $guard|([$i[0].tests[]?.comparisons[]?|select(.boundary_signal and (.target==$t))]|length>0) as $identity|([$w[0].workflows[]?|select((.wrong_order|length)>0 or (.state_transition_signals|length)>0)]|length>0) as $workflow|{target:$t,components:{impact_likelihood:((if ($t|test("(?i)(export|refund|payment|billing|admin|delete|invite|token|secret)")) then 25 else 5 end)),asset_value:$b,authentication_surface:(if ($e.authentication_required//false) then 15 else 0 end),data_sensitivity:(if ($e.sensitive_data_indicators//false) then 20 else 0 end),object_identifier:(if ($e.object_identifiers//false) then 15 else 0 end),missing_security:(if ($e.indicators.missing_authorization//false) then 10 else 0 end),client_role_guard:(if $guard then 10 else 0 end),identity_boundary:(if $identity then 25 else 0 end),workflow_anomaly:(if $workflow then 20 else 0 end)}}|.priority_score=([100,(.components|to_entries|map(.value)|add)]|min)|.priority=(if .priority_score>=80 then"Critical Research"elif .priority_score>=60 then"High"elif .priority_score>=40 then"Medium"else"Low"end)|.reasons=[.components|to_entries[]|select(.value>0)|.key]|.classification="HUNTER_TARGET_NOT_VULNERABILITY"' >>"$tmp"
  done <<<"$(jq -r '.endpoints[]?|(.base+.path)' "$auth" | sort -u)"
  jq -s --argjson top "$top" --arg mode "$(cfg_get_default mode standard)" '{mode:$mode,classification:"TOP_TARGETS_NOT_VULNERABILITIES",targets:(sort_by(-.priority_score)|.[0:$top]),informational_suppressed:($mode=="hunter"),scoring:"impact likelihood + asset value + authentication + data sensitivity + object IDs + logical signals"}' "$tmp" >"$out"
  log_info "[vMAX+ hunter] targets=$(jq '.targets|length' "$out")"
}
# APEX vMAX+ — human review queue and supplemental report.
phase_vplus_human_loop(){
  local hunter="$APEX_RUN_DIR/reports/hunter_targets.json" queue="$APEX_RUN_DIR/reports/review_queue.json" out="$APEX_RUN_DIR/reports/human_review.json" decisions evidence hash d
  [[ -s "$hunter" ]] || jq -n '{targets:[]}' >"$hunter"
  jq --argjson n "$(cfg_get_default review_top 10)" '{classification:"HUMAN_REVIEW_QUEUE",items:[.targets[0:$n][]|{research_id:("review|"+(.target|@base64)),target,priority_score,reasons,prompt:"Perform an authorized manual test and return a decision with evidence_file.",allowed_decisions:["confirmed","rejected","needs_more"],automatic_action:false}]}' "$hunter" >"$queue"
  decisions="$(cfg_get_default decisions_file '')"; :>"$APEX_RUN_DIR/reports/human_decisions.ndjson"
  if [[ -s "$decisions" ]]; then
    while IFS= read -r d; do
      jq -e '.research_id and (.decision=="confirmed" or .decision=="rejected" or .decision=="needs_more")' <<<"$d" >/dev/null 2>&1 || continue
      evidence="$(jq -r '.evidence_file//""'<<<"$d")"; hash=""; [[ -f "$evidence" ]] && hash="$(apex_sha256 <"$evidence")"
      jq -c --arg hash "$hash" --arg valid "$([[ -n "$hash" ]]&&echo true||echo false)" '.+{evidence_sha256:(if $hash=="" then null else $hash end),evidence_file_valid:($valid=="true"),promotion_allowed:false,note:"Human decisions guide research; vulnerability reporting still requires the five-part quality gate."}' <<<"$d" >>"$APEX_RUN_DIR/reports/human_decisions.ndjson"
    done <"$decisions"
  fi
  jq -s --slurpfile q "$queue" '{classification:"HUMAN_IN_THE_LOOP_ANALYSIS",queue:$q[0].items,decisions:.,summary:{queued:($q[0].items|length),confirmed_hypotheses:([.[]|select(.decision=="confirmed")]|length),rejected:([.[]|select(.decision=="rejected")]|length),needs_more:([.[]|select(.decision=="needs_more")]|length)},automatic_promotion:false}' "$APEX_RUN_DIR/reports/human_decisions.ndjson" >"$out"
  log_info "[vMAX+ human] queued=$(jq '.summary.queued' "$out") decisions=$(jq '.decisions|length' "$out")"
}
phase_vplus_report(){
  local base="$APEX_RUN_DIR/reports/professional_security_report.md" out="$APEX_RUN_DIR/reports/professional_security_report_vmax_plus.md" hunter="$APEX_RUN_DIR/reports/hunter_targets.json" ident="$APEX_RUN_DIR/reports/identity_differential.json" workflow="$APEX_RUN_DIR/reports/workflow_intelligence.json" human="$APEX_RUN_DIR/reports/human_review.json"
  [[ -f "$base" ]] && cat "$base" >"$out" || printf '# APEX vMAX+ Professional Security Report\n' >"$out"
  {
    printf '\n\n## vMAX+ Identity Differential Signals\n\n'; jq -r '.tests[]?.comparisons[]?|select(.boundary_signal)|"- \(.role_a) vs \(.role_b) — \(.identity_a) accessed \(.object // "object") at \(.target // "controlled target"): same response fingerprint; manual ownership validation required."' "$ident" 2>/dev/null || true
    printf '\n## Workflow and Business Logic Signals\n\n'; jq -r '.workflows[]?|select((.missing_steps|length)>0 or (.wrong_order|length)>0 or (.state_transition_signals|length)>0)|"- \(.name): missing=\(.missing_steps|join(",")); wrong-order=\(.wrong_order|length); reverse-transitions=\(.state_transition_signals|length)"' "$workflow" 2>/dev/null || true
    printf '\n## Hunter Top Targets\n\n'; jq -r '.targets[]?|"- [\(.priority_score)] \(.target) — \(.reasons|join(", "))"' "$hunter" 2>/dev/null || true
    printf '\n## Human Review State\n\n'; jq -r '"- Queued: \(.summary.queued)\n- Confirmed hypotheses: \(.summary.confirmed_hypotheses)\n- Rejected: \(.summary.rejected)\n- Needs more evidence: \(.summary.needs_more)\n\nHuman confirmation does not bypass the five-part vulnerability quality gate."' "$human" 2>/dev/null || true
    printf '\n## vMAX+ Analysis Limits\n\n- JavaScript analysis is bounded lexical/local-binding analysis, not semantic AST execution.\n- HAR learning is offline and never replays captured traffic.\n- Identity comparisons require explicit authorized identities and plans; signals do not prove ownership impact.\n- Workflow anomalies require product-specific state definitions for reliable conclusions.\n'
  } >>"$out"
  log_info "[vMAX+ report] $out"
}

# APEX v5 Research Core — evidence and object intelligence.
v5_endpoint_family(){ local p="$1"; p="${p%%\?*}"; printf '%s' "$p" | sed -E 's#/(users?|orders?|invoices?|files?|accounts?|transactions?)/([0-9]{2,}|[0-9a-fA-F-]{16,})(/|$)#/\1/{\1_id}\3#g;s#\{users?_id\}#{user_id}#g;s#\{orders?_id\}#{order_id}#g;s#\{invoices?_id\}#{invoice_id}#g;s#\{files?_id\}#{file_id}#g;s#\{accounts?_id\}#{account_id}#g;s#\{transactions?_id\}#{transaction_id}#g;s#/([0-9]{2,}|[0-9a-fA-F-]{16,})(/|$)#/{object_id}\2#g'; }
v5_object_type(){ local s="${1,,}"; case "$s" in *invoice*)echo invoice;;*order*)echo order;;*file*)echo file;;*account*)echo account;;*transaction*|*payment*)echo transaction;;*user*|*profile*)echo user;;*)echo unknown;;esac; }
v5_action(){ local method="${1^^}" p="${2,,}"; case "$p" in *approve*)echo approve;;*refund*|*reverse*)echo refund;;*pay*|*charge*)echo pay;;*export*)echo export;;*delete*|*remove*)echo delete;;*create*|*new*)echo create;;*)case "$method" in POST)echo create;;PUT|PATCH)echo update;;DELETE)echo delete;;*)echo read;;esac;;esac; }
phase_v5_evidence_graph(){
 local out="$APEX_RUN_DIR/reports/evidence_graph.json" raw="$APEX_RUN_DIR/reports/evidence_claims.ndjson" s="$APEX_RUN_DIR/reports/session_intelligence.json" a="$APEX_RUN_DIR/reports/api_intelligence.json" j="$APEX_RUN_DIR/reports/deep_javascript_map.json" io="$APEX_RUN_DIR/reports/identity_observations.ndjson" f="$APEX_RUN_DIR/db/findings.ndjson" u m p src id l
 :>"$raw"; [[ -f "$io" ]]||:>"$io"; [[ -f "$f" ]]||:>"$f"
 if [[ -s "$s" ]]; then while IFS=$'\t' read -r u m; do [[ -n "$u" ]]||continue; p="$(v5_endpoint_family "$u")"; id="ev-$(vmax_hash "HAR|$m|$u")"; jq -cn --arg id "$id" --arg subject "$p" --arg ref "$u" '{id:$id,source_type:"HAR",source_ref:$ref,claim:{type:"OBSERVED_ENDPOINT",subject:$subject},confidence:75,confidence_reason:"Request observed in supplied HAR",fact_status:"OBSERVED",ownership_asserted:false}'>>"$raw"; done<<<"$(jq -r '.transactions[]?|[.url,.method]|@tsv' "$s")"; fi
 if [[ -s "$a" ]]; then while IFS=$'\t' read -r u m; do [[ -n "$u" ]]||continue;p="$(v5_endpoint_family "$u")";id="ev-$(vmax_hash "OPENAPI|$m|$u")";jq -cn --arg id "$id" --arg subject "$p" --arg ref "$u" '{id:$id,source_type:"OPENAPI",source_ref:$ref,claim:{type:"DECLARED_ENDPOINT",subject:$subject},confidence:75,confidence_reason:"Declared in supplied API document",fact_status:"DECLARED_NOT_RUNTIME_VERIFIED",ownership_asserted:false}'>>"$raw";done<<<"$(jq -r '.openapi_endpoints[]?|[.base+.path,.method]|@tsv' "$a")"; fi
 if [[ -s "$j" ]]; then while IFS= read -r u;do [[ -n "$u" ]]||continue;p="$(v5_endpoint_family "$u")";id="ev-$(vmax_hash "JS|$u")";jq -cn --arg id "$id" --arg subject "$p" --arg ref "$u" '{id:$id,source_type:"JS",source_ref:$ref,claim:{type:"CLIENT_REFERENCED_ENDPOINT",subject:$subject},confidence:50,confidence_reason:"Static client reference; runtime reachability unproven",fact_status:"OBSERVED_REFERENCE",ownership_asserted:false}'>>"$raw";done<<<"$(jq -r '.calls[]?.endpoint' "$j")"; fi
 while IFS= read -r l;do [[ -n "$l" ]]||continue;u="$(jq -r .url<<<"$l")";p="$(v5_endpoint_family "$u")";id="ev-$(vmax_hash "RESPONSE|$(jq -r .analysis_key<<<"$l")|$(jq -r .identity<<<"$l")")";jq -cn --arg id "$id" --arg subject "$p" --arg ref "$(jq -r .analysis_key<<<"$l")" --arg identity "$(jq -r .identity<<<"$l")" --argjson conf 75 '{id:$id,source_type:"RESPONSE",source_ref:$ref,claim:{type:"IDENTITY_RESPONSE_OBSERVED",subject:$subject,identity:$identity},confidence:$conf,confidence_reason:"Controlled response observation; does not prove ownership",fact_status:"OBSERVED",ownership_asserted:false}'>>"$raw";done<"$io"
 while IFS= read -r l;do [[ -n "$l" ]]||continue;id="ev-$(vmax_hash "TOOL|$(jq -r .id<<<"$l")")";jq -cn --arg id "$id" --arg subject "$(jq -r .target<<<"$l")" --arg ref "$(jq -r .id<<<"$l")" '{id:$id,source_type:"TOOL",source_ref:$ref,claim:{type:"TOOL_OBSERVATION",subject:$subject},confidence:30,confidence_reason:"Tool output is a signal until independently validated",fact_status:"OBSERVATION",ownership_asserted:false}'>>"$raw";done<"$f"
 jq -s '{schema_version:1,policy:{observation_is_not_vulnerability:true,inference_is_not_fact:true,ownership_requires_independent_evidence:true},evidence:.,claims:(map(.claim+{evidence_id:.id,confidence:.confidence,fact_status:.fact_status})),summary:{total:length,observed:([.[]|select(.fact_status=="OBSERVED")]|length),inferences_promoted_to_fact:0}}' "$raw">"$out"; log_info "[v5 evidence] nodes=$(jq .summary.total "$out")"
}
phase_v5_object_intelligence(){
 local ev="$APEX_RUN_DIR/reports/evidence_graph.json" sess="$APEX_RUN_DIR/reports/session_intelligence.json" raw="$APEX_RUN_DIR/reports/object_observations.ndjson" out="$APEX_RUN_DIR/reports/object_intelligence.json" graph="$APEX_RUN_DIR/reports/object_graph.json" u fam typ method action ids src conf
 :>"$raw"; [[ -s "$ev" ]]||jq -n '{evidence:[]}' >"$ev"
 while IFS=$'\t' read -r u method src;do [[ -n "$u" ]]||continue;fam="$(v5_endpoint_family "$u")";typ="$(v5_object_type "$fam")";action="$(v5_action "$method" "$fam")";ids="$( { grep -Eo '([0-9]{2,}|[0-9a-fA-F-]{16,})'<<<"${u%%\?*}" || true; }|jq -Rsc 'split("\n")|map(select(length>0))|unique')";conf=50;[[ "$src" == HAR ]]&&conf=75;[[ "$src" == OPENAPI ]]&&conf=70;jq -cn --arg endpoint "$u" --arg family "$fam" --arg type "$typ" --arg method "$method" --arg action "$action" --arg source "$src" --argjson ids "$ids" --argjson conf "$conf" '{endpoint:$endpoint,endpoint_family:$family,object_type:$type,method:$method,observed_action:$action,identifiers:$ids,discovery_source:$source,confidence:$conf,state_status:"OBSERVED_ACTION_NOT_CONFIRMED_STATE"}'>>"$raw";done<<<"$(jq -r '.evidence[]?|select(.claim.type=="OBSERVED_ENDPOINT" or .claim.type=="DECLARED_ENDPOINT" or .claim.type=="CLIENT_REFERENCED_ENDPOINT")|[.source_ref,(if .claim.type=="OBSERVED_ENDPOINT" then "GET" else "UNKNOWN" end),.source_type]|@tsv' "$ev")"
 # HAR carries authoritative observed method/action metadata.
 if [[ -s "$sess" ]];then while IFS=$'\t' read -r u method;do fam="$(v5_endpoint_family "$u")";typ="$(v5_object_type "$fam")";action="$(v5_action "$method" "$fam")";ids="$( { grep -Eo '([0-9]{2,}|[0-9a-fA-F-]{16,})'<<<"${u%%\?*}" || true; }|jq -Rsc 'split("\n")|map(select(length>0))|unique')";jq -cn --arg endpoint "$u" --arg family "$fam" --arg type "$typ" --arg method "$method" --arg action "$action" --argjson ids "$ids" '{endpoint:$endpoint,endpoint_family:$family,object_type:$type,method:$method,observed_action:$action,identifiers:$ids,discovery_source:"HAR",confidence:75,state_status:"OBSERVED_ACTION_NOT_CONFIRMED_STATE"}'>>"$raw";done<<<"$(jq -r '.transactions[]?|[.url,.method]|@tsv' "$sess")";fi
 jq -s 'group_by(.object_type,.endpoint_family)|map({object_type:.[0].object_type,endpoint_family:.[0].endpoint_family,identifiers:(map(.identifiers[])|unique),discovery_sources:(map(.discovery_source)|unique),creator_endpoints:[.[]|select(.observed_action=="create")|.endpoint],reader_endpoints:[.[]|select(.observed_action=="read")|.endpoint],updater_endpoints:[.[]|select(.observed_action=="update" or .observed_action=="approve" or .observed_action=="pay" or .observed_action=="refund")|.endpoint],deleter_endpoints:[.[]|select(.observed_action=="delete")|.endpoint],related_objects:[],sensitivity:(.[0].object_type|test("user|account|invoice|transaction|file")),confidence:(map(.confidence)|max),lifecycle_observations:[.[]|select(.observed_action|IN("create","approve","pay","refund","delete"))|{action:.observed_action,endpoint:.endpoint,status:"OBSERVED_ACTION_NOT_CONFIRMED_STATE",source:.discovery_source}]})|{classification:"OBJECT_INTELLIGENCE_NOT_OWNERSHIP_PROOF",objects:.,count:length}' "$raw">"$out"
 jq -n --slurpfile o "$out" '{nodes:([$o[0].objects[]|{id:("object-type:"+.object_type+":"+.endpoint_family),type:"observed_object_family",value:.object_type,confidence:.confidence}]),edges:([$o[0].objects[] as $x|$x.creator_endpoints[]?|{from:.,to:("object-type:"+$x.object_type+":"+$x.endpoint_family),type:"CREATES_OBJECT",fact_status:"OBSERVED_METHOD_MAPPING"},$o[0].objects[] as $x|$x.reader_endpoints[]?|{from:.,to:("object-type:"+$x.object_type+":"+$x.endpoint_family),type:"READS_OBJECT",fact_status:"OBSERVED_METHOD_MAPPING"}]),ownership_edges:[],note:"Identifier observation does not establish ownership."}' >"$graph";log_info "[v5 objects] families=$(jq .count "$out")"
}
# APEX v5 — permission matrix and API relationships.
phase_v5_permission_matrix(){
 local ids="$APEX_RUN_DIR/reports/identity_differential.json" profiles="$(cfg_get_default identity_profiles_dir '')" out="$APEX_RUN_DIR/reports/permission_matrix.json" raw="$APEX_RUN_DIR/reports/permission_rows.ndjson" test obs identity role rank target action expected status cls visible sensitive structure state=false profile
 :>"$raw";[[ -s "$ids" ]]||jq -n '{tests:[]}' >"$ids"
 while IFS= read -r test;do [[ -n "$test" ]]||continue;target="$(jq -r .target<<<"$test")";action="$(v5_action "$(jq -r .method<<<"$test")" "$target")";while IFS= read -r obs;do identity="$(jq -r .identity<<<"$obs")";role="$(jq -r .role<<<"$obs")";rank="$(jq -r .rank<<<"$obs")";status="$(jq -r .status<<<"$obs")";visible="$(jq -r .object_reference_seen<<<"$obs")";sensitive="$(jq -r .sensitive_field_indicators<<<"$obs")";structure="$(jq -r .structure_hash<<<"$obs")";expected=unknown;profile="$profiles/$identity.json";if [[ -s "$profile" ]];then jq -e --arg a "$action" '.allowed_actions//[]|index($a)!=null' "$profile">/dev/null&&expected=allow||expected=deny;fi;if [[ "$expected" == allow && "$status" =~ ^(401|403)$ ]];then cls=UNEXPECTED_DENIAL_SIGNAL;elif [[ "$expected" == deny && "$status" -ge 200 && "$status" -lt 300 && ( "$visible" == true || "$sensitive" -gt 0 ) ]];then cls=UNEXPECTED_ACCESS_SIGNAL;elif [[ "$expected" == allow && "$status" -ge 200 && "$status" -lt 400 ]];then cls=EXPECTED;elif [[ "$expected" == deny && "$status" =~ ^(401|403|404)$ ]];then cls=EXPECTED;else cls=INCONCLUSIVE;fi;jq -cn --arg identity "$identity" --arg role "$role" --argjson rank "$rank" --arg endpoint "$target" --arg action "$action" --arg expectation "$expected" --arg classification "$cls" --argjson status "$status" --arg structure "$structure" --argjson visible "$visible" --argjson sensitive "$sensitive" --argjson state "$state" '{identity:$identity,role:$role,rank:$rank,endpoint:$endpoint,action:$action,expectation:$expectation,observed:{status:$status,response_structure:$structure,object_visible:$visible,sensitive_fields:$sensitive,state_change:$state},classification:$classification,automatic_vulnerability:false}'>>"$raw";done<<<"$(jq -c '.observations[]'<<<"$test")";done<<<"$(jq -c '.tests[]?' "$ids")"
 jq -s '{policy:{allowed_classifications:["EXPECTED","UNEXPECTED_ACCESS_SIGNAL","UNEXPECTED_DENIAL_SIGNAL","INCONCLUSIVE"],vulnerable_label_forbidden:true},rows:.,summary:{total:length,unexpected_access:([.[]|select(.classification=="UNEXPECTED_ACCESS_SIGNAL")]|length),unexpected_denial:([.[]|select(.classification=="UNEXPECTED_DENIAL_SIGNAL")]|length),inconclusive:([.[]|select(.classification=="INCONCLUSIVE")]|length)}}' "$raw">"$out";log_info "[v5 permissions] rows=$(jq .summary.total "$out")"
}
phase_v5_api_relationships(){
 local obj="$APEX_RUN_DIR/reports/object_intelligence.json" ev="$APEX_RUN_DIR/reports/evidence_graph.json" pm="$APEX_RUN_DIR/reports/permission_matrix.json" out="$APEX_RUN_DIR/reports/api_relationships.json" graph="$APEX_RUN_DIR/reports/research_graph.json" raw="$APEX_RUN_DIR/reports/api_edges.ndjson" o endpoint action rel conf evid key r
 :>"$raw";[[ -s "$obj" ]]||jq -n '{objects:[]}' >"$obj";[[ -s "$ev" ]]||jq -n '{evidence:[]}' >"$ev";[[ -s "$pm" ]]||jq -n '{rows:[]}' >"$pm"
 while IFS= read -r o;do for action in create read update delete export approve pay refund;do case "$action" in create) rel=CREATES_OBJECT;key=creator_endpoints;;read)rel=READS_OBJECT;key=reader_endpoints;;update|approve|pay|refund)rel=CHANGES_STATE;key=updater_endpoints;;delete)rel=DELETES_OBJECT;key=deleter_endpoints;;export)rel=EXPORTS_OBJECT;key=reader_endpoints;;esac;while IFS= read -r endpoint;do [[ -n "$endpoint" ]]||continue;[[ "$action" == export && "${endpoint,,}" != *export* ]]&&continue;[[ "$action" =~ ^(approve|pay|refund)$ && "${endpoint,,}" != *"$action"* ]]&&continue;conf="$(jq -r .confidence<<<"$o")";evid="$(jq -c --arg e "$(v5_endpoint_family "$endpoint")" '[.evidence[]?|select(.claim.subject==$e)|.id]' "$ev")";[[ "$(jq length<<<"$evid")" -gt 0 ]]||continue;jq -cn --arg from "$endpoint" --arg to "$(jq -r '.object_type+":"+.endpoint_family'<<<"$o")" --arg relation "$rel" --arg method "observed_endpoint_mapping" --argjson confidence "$conf" --argjson evidence "$evid" '{from:$from,to:$to,relationship:$relation,source_evidence:$evidence,confidence:$confidence,discovery_method:$method,fact_status:"OBSERVED_RELATIONSHIP_SIGNAL"}'>>"$raw";done<<<"$(jq -r --arg k "$key" '.[$k][]?'<<<"$o")";done;done<<<"$(jq -c '.objects[]' "$obj")"
 local observations="$APEX_RUN_DIR/reports/object_observations.ndjson"; [[ -f "$observations" ]]||:>"$observations"
 while IFS= read -r o;do [[ -n "$o" ]]||continue;endpoint="$(jq -r .endpoint<<<"$o")";action="$(jq -r .observed_action<<<"$o")";case "$action" in create)rel=CREATES_OBJECT;;read)rel=READS_OBJECT;;update)rel=UPDATES_OBJECT;;delete)rel=DELETES_OBJECT;;export)rel=EXPORTS_OBJECT;;approve|pay|refund)rel=CHANGES_STATE;;*)rel=READS_OBJECT;;esac;evid="$(jq -c --arg ref "$endpoint" '[.evidence[]?|select(.source_ref==$ref)|.id]' "$ev")";[[ "$(jq length<<<"$evid")" -gt 0 ]]||continue;jq -cn --arg from "$endpoint" --arg to "$(jq -r '.object_type+":"+.endpoint_family'<<<"$o")" --arg relationship "$rel" --argjson evidence "$evid" --argjson confidence "$(jq .confidence<<<"$o")" --arg method "$(jq -r .discovery_source<<<"$o")" '{from:$from,to:$to,relationship:$relationship,source_evidence:$evidence,confidence:$confidence,discovery_method:$method,fact_status:"OBSERVED_RELATIONSHIP_SIGNAL"}'>>"$raw";if [[ "$(jq '.identifiers|length'<<<"$o")" -gt 0 ]];then jq -cn --arg from "$endpoint" --arg to "$(jq -r '.object_type+":"+.endpoint_family'<<<"$o")" --argjson evidence "$evid" '{from:$from,to:$to,relationship:"ACCEPTS_IDENTIFIER",source_evidence:$evidence,confidence:75,discovery_method:"identifier_in_observed_request_path",fact_status:"OBSERVED"}'>>"$raw";fi;done<"$observations"
 while IFS= read -r r;do endpoint="$(jq -r .endpoint<<<"$r")";evid="$(jq -c --arg id "$(jq -r .identity<<<"$r")" --arg e "$(v5_endpoint_family "$endpoint")" '[.evidence[]?|select(.claim.identity==$id and .claim.subject==$e)|.id]' "$ev")";[[ "$(jq length<<<"$evid")" -gt 0 ]]||continue;jq -cn --arg from "identity:$(jq -r .identity<<<"$r")" --arg to "$endpoint" --arg relation REQUIRES_ROLE --argjson evidence "$evid" --arg role "$(jq -r .role<<<"$r")" '{from:$from,to:$to,relationship:$relation,source_evidence:$evidence,confidence:60,discovery_method:"identity_profile_and_controlled_response",required_role:$role,fact_status:"EXPECTATION_COMPARISON"}'>>"$raw";if [[ "$(jq -r .observed.object_visible<<<"$r")" == true ]];then jq -cn --arg from "$endpoint" --arg to "identity:$(jq -r .identity<<<"$r")" --argjson evidence "$evid" '{from:$from,to:$to,relationship:"RETURNS_IDENTIFIER",source_evidence:$evidence,confidence:50,discovery_method:"controlled_response_object_visibility",fact_status:"OBSERVED_RESPONSE_SIGNAL"}'>>"$raw";fi;done<<<"$(jq -c '.rows[]?' "$pm")"
 jq -s 'unique_by(.from,.to,.relationship)|{classification:"RESEARCH_RELATIONSHIPS_NOT_FACTS",relationships:.,count:length}' "$raw">"$out";jq -n --slurpfile r "$out" '{nodes:([$r[0].relationships[]|.from,.to]|unique|map({id:.,type:(split(":")[0])})),edges:$r[0].relationships,policy:{inference_is_not_fact:true}}'>"$graph";log_info "[v5 relationships] edges=$(jq .count "$out")"
}
# APEX v5 — workflow learning and differential memory.
phase_v5_workflow_learning(){
 local sess="$APEX_RUN_DIR/reports/session_intelligence.json" kb hist out changes curr="$APEX_RUN_DIR/reports/current_transitions.ndjson" a b host i seq key prior reverse s
 kb="$(vmax_kb_init)";hist="$kb/workflow_history.ndjson";out="$APEX_RUN_DIR/reports/workflow_learned.json";changes="$APEX_RUN_DIR/reports/workflow_comparison.json";touch "$hist";:>"$curr";[[ -s "$sess" ]]||jq -n '{sessions:[]}' >"$sess"
 while IFS= read -r s;do host="$(jq -r .host<<<"$s")";mapfile -t seq <<<"$(jq -r '.sequence[]'<<<"$s")";for((i=0;i+1<${#seq[@]};i++));do a="${seq[i]}";b="${seq[i+1]}";key="$host|$a|$b";prior="$(grep -Fc '"key":"'"$key"'"' "$hist"||true)";reverse="$(grep -Fc '"key":"'"$host|$b|$a"'"' "$hist"||true)";jq -cn --arg key "$key" --arg host "$host" --arg from "$a" --arg to "$b" --argjson prior "$prior" --argjson reverse "$reverse" '{key:$key,host:$host,from:$from,to:$to,prior_count:$prior,reverse_prior_count:$reverse,signal:(if ($reverse>$prior and $reverse>0) then"REVERSED_TRANSITION"elif $prior==0 then"NEW_STATE_PATH"elif $prior<=1 then"RARE_TRANSITION"else null end),classification:"WORKFLOW_RESEARCH_SIGNAL"}'>>"$curr";done;local first="${seq[0]-}" pred;if [[ -n "$first" && -s "$hist" ]];then while IFS= read -r pred;do [[ -n "$pred" ]]||continue;if ! printf '%s\n' "${seq[@]}"|grep -Fxq "$pred";then jq -cn --arg key "$host|$pred|$first" --arg host "$host" --arg from "$pred" --arg to "$first" '{key:$key,host:$host,from:$from,to:$to,prior_count:1,reverse_prior_count:0,signal:"MISSING_OBSERVED_PREDECESSOR",classification:"WORKFLOW_RESEARCH_SIGNAL"}'>>"$curr";fi;done<<<"$(jq -r --arg h "$host" --arg t "$first" 'select(.host==$h and .to==$t)|.from' "$hist"|sort -u)";fi;done<<<"$(jq -c '.sessions[]?' "$sess")"
 cat "$curr">>"$hist";jq -s 'group_by(.key)|map({key:.[0].key,host:.[0].host,from:.[0].from,to:.[0].to,observed_count:length})|{classification:"LEARNED_OBSERVED_TRANSITIONS_NOT_BUSINESS_RULES",transitions:.,count:length}' "$hist">"$out";jq -s '{signals:[.[]|select(.signal!=null)],allowed_signals:["RARE_TRANSITION","MISSING_OBSERVED_PREDECESSOR","REVERSED_TRANSITION","NEW_STATE_PATH"],automatic_vulnerability:false}' "$curr">"$changes";cp "$hist" "$APEX_RUN_DIR/reports/workflow_history.ndjson";log_info "[v5 workflow-learning] transitions=$(jq .count "$out") signals=$(jq '.signals|length' "$changes")"
}
phase_v5_differential_memory(){
 local obs="$APEX_RUN_DIR/reports/identity_observations.ndjson" kb base hist changes raw="$APEX_RUN_DIR/reports/current_behavior.ndjson" l fam role rel auth key prior
 kb="$(vmax_kb_init)";base="$kb/differential_baseline.json";hist="$kb/behavior_history.ndjson";changes="$APEX_RUN_DIR/reports/differential_changes.json";touch "$hist";[[ -s "$base" ]]||jq -n '{profiles:[]}' >"$base";:>"$raw";[[ -f "$obs" ]]||:>"$obs"
 while IFS= read -r l;do [[ -n "$l" ]]||continue;fam="$(v5_endpoint_family "$(jq -r .url<<<"$l")")";role="$(jq -r .role<<<"$l")";rel="$(jq -r 'if .object_reference_seen then"observed_object"else"unknown"end'<<<"$l")";auth=true;key="$fam|$(jq -r .method<<<"$l")|$role|$rel|$auth";jq -cn --arg key "$key" --arg family "$fam" --arg method "$(jq -r .method<<<"$l")" --arg role "$role" --arg relation "$rel" --argjson auth "$auth" --argjson status "$(jq .status<<<"$l")" --arg structure "$(jq -r .structure_hash<<<"$l")" --argjson sensitive "$(jq .sensitive_field_indicators<<<"$l")" '{key:$key,endpoint_family:$family,method:$method,identity_role:$role,object_relationship:$relation,authenticated:$auth,status:$status,structure_hash:$structure,sensitive_fields:$sensitive}'>>"$raw";done<"$obs"
 jq -n --slurpfile current "$raw" --slurpfile baseline "$base" '{classification:"DIFFERENTIAL_RESEARCH_SIGNALS",signals:[($current[] as $c|($baseline[0].profiles|map(select(.key==$c.key))[0]//null) as $b|select($b!=null and (($b.normal_status!=$c.status) or ($b.structure_hash!=$c.structure_hash) or ($c.sensitive_fields>$b.max_sensitive_fields)))|{type:"DIFFERENTIAL_AUTHORIZATION_ANOMALY",key:$c.key,current:$c,baseline:$b,reason:"Observed behavior differs from stored normalized baseline",automatic_vulnerability:false})],count:0}|.count=(.signals|length)' >"$changes"
 cat "$raw">>"$hist";jq -s 'group_by(.key)|map({key:.[0].key,endpoint_family:.[0].endpoint_family,method:.[0].method,identity_role:.[0].identity_role,object_relationship:.[0].object_relationship,authenticated:.[0].authenticated,normal_status:(group_by(.status)|max_by(length)[0].status),structure_hash:(group_by(.structure_hash)|max_by(length)[0].structure_hash),max_sensitive_fields:(map(.sensitive_fields)|max),observations:length})|{profiles:.}' "$hist">"$base.tmp"&&mv "$base.tmp" "$base";cp "$base" "$APEX_RUN_DIR/reports/differential_baseline.json";cp "$hist" "$APEX_RUN_DIR/reports/behavior_history.ndjson";log_info "[v5 differential] profiles=$(jq '.profiles|length' "$base") changes=$(jq .count "$changes")"
}
# APEX v5 — suggestion-only endpoint mutation and append-only research memory.
phase_v5_endpoint_mutations(){
 local obj="$APEX_RUN_DIR/reports/object_intelligence.json" out="$APEX_RUN_DIR/reports/endpoint_mutations.json" raw="$APEX_RUN_DIR/reports/mutation_suggestions.ndjson" endpoints versions e v nv sug typ actions a
 [[ -s "$obj" ]]||jq -n '{objects:[]}' >"$obj";:>"$raw";endpoints="$(jq -r '.objects[]?|.creator_endpoints[],.reader_endpoints[],.updater_endpoints[],.deleter_endpoints[]' "$obj"|sort -u)";versions="$(grep -Eo '/v[0-9]+/'<<<"$endpoints"|sort -u||true)"
 while IFS= read -r e;do [[ -n "$e" ]]||continue;v="$(grep -Eo '/v[0-9]+/'<<<"$e"|head -1||true)";if [[ -n "$v" ]];then while IFS= read -r nv;do [[ -n "$nv"&&"$nv"!="$v" ]]||continue;sug="${e/$v/$nv}";grep -Fqx "$sug"<<<"$endpoints"&&continue;jq -cn --arg source "$e" --arg suggestion "$sug" --arg version "$nv" '{source:$source,suggestion:$suggestion,reason:("Version "+$version+" observed elsewhere in application"),confidence:60,automatic_request:false,classification:"RESEARCH_SUGGESTION"}'>>"$raw";done<<<"$versions";fi;typ="$(v5_object_type "$e")";actions="$(jq -r --arg t "$typ" '.objects[]|select(.object_type==$t)|.lifecycle_observations[].action' "$obj"|sort -u)";while IFS= read -r a;do [[ -n "$a" ]]||continue;[[ "${e,,}" == *"$a"* ]]&&continue;sug="${e%/}/$a";grep -Fqx "$sug"<<<"$endpoints"&&continue;jq -cn --arg source "$e" --arg suggestion "$sug" --arg action "$a" --arg type "$typ" '{source:$source,suggestion:$suggestion,reason:("Action "+$action+" observed for object type "+$type),confidence:50,automatic_request:false,classification:"RESEARCH_SUGGESTION"}'>>"$raw";done<<<"$actions";done<<<"$endpoints"
 jq -s 'unique_by(.source,.suggestion)|{classification:"SUGGESTIONS_ONLY_NO_REQUESTS",suggestions:.,count:length,requests_sent:0}' "$raw">"$out";log_info "[v5 mutations] suggestions=$(jq .count "$out")"
}
phase_v5_research_memory(){
 local kb mem out now f k d w p
 kb="$(vmax_kb_init)";mem="$kb/research_memory.json";out="$APEX_RUN_DIR/reports/research_memory_snapshot.json";now="$(vmax_now)";[[ -s "$mem" ]]||jq -n '{confirmed_findings:[],rejected_signals:[],false_positives:[],technologies:[],endpoint_behavior:[],signal_history:[]}'>"$mem";f="$APEX_RUN_DIR/db/findings.ndjson";k="$APEX_RUN_DIR/reports/knowledge_snapshot.json";d="$APEX_RUN_DIR/reports/differential_changes.json";w="$APEX_RUN_DIR/reports/workflow_comparison.json";p="$APEX_RUN_DIR/reports/application_model.json";[[ -f "$f" ]]||:>"$f";[[ -s "$k" ]]||jq -n '{rejected_findings:[],false_positives:[]}' >"$k";[[ -s "$d" ]]||jq -n '{signals:[]}' >"$d";[[ -s "$w" ]]||jq -n '{signals:[]}' >"$w";[[ -s "$p" ]]||jq -n '{technologies:[]}' >"$p"
 jq -n --arg now "$now" --slurpfile old "$mem" --slurpfile f "$f" --slurpfile k "$k" --slurpfile d "$d" --slurpfile w "$w" --slurpfile p "$p" '$old[0]|.confirmed_findings=((.confirmed_findings+[$f[]|select(.reportability=="REPORTABLE")])|unique_by(.id))|.rejected_signals=((.rejected_signals+($k[0].rejected_findings//[]))|unique_by(.id//(.category+"|"+.target)))|.false_positives=((.false_positives+($k[0].false_positives//[]))|unique_by(.id//(.category+"|"+.target)))|.technologies=((.technologies+($p[0].technologies//[]))|unique)|.endpoint_behavior=((.endpoint_behavior+($d[0].signals//[]))|unique_by(.key))|.signal_history += [{timestamp:$now,differential:($d[0].signals//[]),workflow:($w[0].signals//[])}]|.policy={new_signals_are_never_deleted:true,signals_do_not_auto_promote:true}' >"$mem.tmp"&&mv "$mem.tmp" "$mem";cp "$mem" "$out";log_info "[v5 memory] signal-history=$(jq '.signal_history|length' "$out")"
}
# APEX v5 — research copilot report (not a vulnerability report).
phase_v5_research_copilot(){
 local hunter="$APEX_RUN_DIR/reports/hunter_targets.json" obj="$APEX_RUN_DIR/reports/object_intelligence.json" pm="$APEX_RUN_DIR/reports/permission_matrix.json" diff="$APEX_RUN_DIR/reports/differential_changes.json" wf="$APEX_RUN_DIR/reports/workflow_comparison.json" mut="$APEX_RUN_DIR/reports/endpoint_mutations.json" out="$APEX_RUN_DIR/reports/research_copilot_report.md" t x
 for x in "$hunter" "$obj" "$pm" "$diff" "$wf" "$mut";do [[ -s "$x" ]]||echo '{}' >"$x";done
 { printf '# APEX v5 Research Copilot Plan\n\n> Research plan only. Observation and inference are not vulnerabilities.\n\n';while IFS= read -r t;do jq -nr --argjson t "$t" --slurpfile o "$obj" --slurpfile p "$pm" --slurpfile d "$diff" --slurpfile w "$wf" --slurpfile m "$mut" '($t.target)as$target|($o[0].objects//[]|map(. as $x|select(($target|contains($x.endpoint_family)) or ($x.endpoint_family|contains($target))))[0]//{})as$object|($p[0].rows//[]|map(select(.endpoint==$target)))as$perm|($d[0].signals//[]|map(select(.current.endpoint_family==$target)))as$changes|($w[0].signals//[])as$workflow|($m[0].suggestions//[]|map(select(.source==$target)))as$mutations|"## Target: \($target)\n\n- **Priority:** \($t.priority_score//0)\n- **Why it matters:** \(($t.reasons//[])|join(", "))\n- **Identity context:** \(if ($perm|length)>0 then ($perm|map(.identity+":"+.classification)|join(", ")) else "No controlled identity result" end)\n- **Object context:** \($object.object_type//"unknown") / \($object.endpoint_family//"unresolved")\n- **Permission expectation:** \(if ($perm|length)>0 then ($perm|map(.expectation)|unique|join(", ")) else "Missing" end)\n- **Observed behavior:** \(if ($changes|length)>0 then "Differential change observed" else "No historical differential evidence" end)\n- **Missing evidence:** independent ownership proof; before/after state evidence; server-side authorization confirmation\n- **Manual research question:** Can a lower-ranked authorized identity perform this action against an independently proven foreign object?\n- **Safe next test:** Use two controlled identities, record ownership first, then compare response and state without destructive impact.\n- **Stop condition:** Stop if scope, consent, ownership evidence, or safe rollback is absent.\n- **Workflow signals:** \($workflow|length)\n- **Mutation suggestions:** \($mutations|map(.suggestion)|join(", "))\n\n"' ;done<<<"$(jq -c '.targets[]?' "$hunter")";printf '## Decision Policy\n\n- No signal in this document is a vulnerability.\n- Confidence cannot increase without a referenced evidence node.\n- Ownership is never inferred from identifier visibility alone.\n- Existing five-part quality gate remains mandatory for vulnerability reporting.\n';}>"$out";log_info "[v5 copilot] targets=$(grep -c '^## Target:' "$out"||true)"
}

# APEX v6 — evidence-bounded reasoning and attack-surface intelligence v2.
phase_v6_security_reasoning(){
 local ev="$APEX_RUN_DIR/reports/evidence_graph.json" obj="$APEX_RUN_DIR/reports/object_intelligence.json" pm="$APEX_RUN_DIR/reports/permission_matrix.json" rel="$APEX_RUN_DIR/reports/api_relationships.json" wf="$APEX_RUN_DIR/reports/workflow_comparison.json" out="$APEX_RUN_DIR/reports/security_reasoning_graph.json" raw="$APEX_RUN_DIR/reports/reasoning_paths.ndjson" ob typ fam ids perms identities unexpected state sensitive strength score classification rid
 :>"$raw";[[ -s "$ev" ]]||jq -n '{evidence:[]}' >"$ev";[[ -s "$obj" ]]||jq -n '{objects:[]}' >"$obj";[[ -s "$pm" ]]||jq -n '{rows:[]}' >"$pm";[[ -s "$rel" ]]||jq -n '{relationships:[]}' >"$rel";[[ -s "$wf" ]]||jq -n '{signals:[]}' >"$wf"
 while IFS= read -r ob;do [[ -n "$ob" ]]||continue;typ="$(jq -r .object_type<<<"$ob")";fam="$(jq -r .endpoint_family<<<"$ob")";ids="$(jq -c --arg t "$typ:$fam" '[.relationships[]?|select(.to|contains($t))|.source_evidence[]?]|unique' "$rel")";perms="$(jq -c --argjson o "$ob" '[.rows[]?|select(.endpoint as $x|($o.creator_endpoints+$o.reader_endpoints+$o.updater_endpoints+$o.deleter_endpoints)|index($x)!=null)]' "$pm")";identities="$(jq '[.[].identity]|unique|length'<<<"$perms")";unexpected="$(jq '[.[]|select(.classification|startswith("UNEXPECTED"))]|length'<<<"$perms")";state="$(jq '.lifecycle_observations|length>0'<<<"$ob")";sensitive="$(jq .sensitivity<<<"$ob")";strength="$(jq -r --argjson ids "$ids" '[.evidence[]?|select(.id as $x|$ids|index($x)!=null)|.confidence]|if length==0 then 0 else (add/length|floor) end' "$ev")";score=0;[[ "$sensitive" == true ]]&&score=$((score+25))||score=$((score+5));[[ "$state" == true ]]&&score=$((score+20));((identities>1))&&score=$((score+20));((unexpected>0))&&score=$((score+25));score=$((score + (${#ids}>20?20:${#ids})));((score>100))&&score=100;classification=RESEARCH_PATH;((score>=75))&&classification=HIGH_PRIORITY_RESEARCH_PATH;rid="reasoning|$(vmax_hash "$typ|$fam")";jq -cn --arg id "$rid" --arg target "$fam" --arg object_type "$typ" --arg classification "$classification" --argjson ids "$ids" --argjson strength "$strength" --argjson identities "$identities" --argjson sensitive "$sensitive" --argjson state "$state" --argjson unexpected "$([[ $unexpected -gt 0 ]]&&echo true||echo false)" --argjson workflow "$(jq '.signals|length' "$wf")" --argjson score "$score" '{id:$id,target:$target,object_type:$object_type,evidence_sources:$ids,evidence_strength:$strength,confidence:([95,$strength]|min),reasoning_chain:(["Endpoint family observed","Object type mapped"]+(if $identities>0 then["Controlled identity context available"]else[]end)+(if $state then["State-changing action observed"]else[]end)+(if $unexpected then["Unexpected permission behavior signal exists"]else[]end)),missing_proof:([if $identities<2 then"second controlled identity"else empty end,"independent object ownership proof",if($unexpected|not)then"unexpected controlled behavior"else empty end,if $state then"before/after state confirmation"else empty end]),next_safe_investigation_step:"Using controlled identities only, establish ownership independently, capture baseline, compare response and state, and stop before destructive impact.",components:{identities:$identities,sensitive:$sensitive,state_changing:$state,unexpected_behavior:$unexpected,workflow_signals:$workflow,evidence_nodes:($ids|length)},priority_score:$score,classification:$classification,automatic_vulnerability:false}'>>"$raw";done<<<"$(jq -c '.objects[]?' "$obj")"
 jq -s '{policy:{inference_is_not_fact:true,automatic_vulnerability:false},paths:.,nodes:[.[]|{id,type:"reasoning_path",target}],edges:[.[] as $p|$p.evidence_sources[]?|{from:.,to:$p.id,type:"SUPPORTS_REASONING",fact_status:"EVIDENCE_REFERENCE"}]}' "$raw">"$out";log_info "[v6 reasoning] paths=$(jq '.paths|length' "$out")"
}
phase_v6_attack_surface_v2(){
 local app="$APEX_RUN_DIR/reports/application_model.json" obj="$APEX_RUN_DIR/reports/object_intelligence.json" pm="$APEX_RUN_DIR/reports/permission_matrix.json" wf="$APEX_RUN_DIR/reports/workflow_comparison.json" ev="$APEX_RUN_DIR/reports/evidence_graph.json" reason="$APEX_RUN_DIR/reports/security_reasoning_graph.json" out="$APEX_RUN_DIR/reports/attack_surface_intelligence_v2.json" f;for f in "$app" "$obj" "$pm" "$wf" "$ev" "$reason";do [[ -s "$f" ]]||echo '{}' >"$f";done
 jq -n --slurpfile a "$app" --slurpfile o "$obj" --slurpfile p "$pm" --slurpfile w "$wf" --slurpfile e "$ev" --slurpfile r "$reason" '{classification:"ATTACK_SURFACE_RESEARCH_MAP",nodes:((($a[0].hosts//[])|map({id:("asset:"+.),type:"asset",value:.}))+(($a[0].technologies//[])|map({id:("technology:"+.),type:"technology",value:.}))+(($a[0].endpoints//[])|map({id:("endpoint:"+.),type:"endpoint",value:.}))+(($o[0].objects//[])|map({id:("object:"+.object_type+":"+.endpoint_family),type:"object",value:.object_type}))+(($p[0].rows//[])|map({id:("identity:"+.identity),type:"identity",value:.role}))+(($w[0].signals//[])|map({id:("workflow:"+.key),type:"workflow",value:.signal}))+(($e[0].evidence//[])|map({id:.id,type:"evidence",value:.source_type}))|unique_by(.id)),critical_paths:[($r[0].paths[]?|select(.components.sensitive and .components.state_changing and .components.identities>1)|{target,reasoning_id:.id,conditions:{internet_exposed:(.target|test("^https?://|^/api")),authenticated:(.components.identities>0),sensitive_object:.components.sensitive,multiple_identities:(.components.identities>1),state_changing:.components.state_changing},evidence_sources,priority_score,classification:"HIGH_VALUE_RESEARCH_AREA",automatic_vulnerability:false})],policy:{critical_path_is_not_vulnerability:true}}' >"$out";log_info "[v6 surface-v2] critical=$(jq '.critical_paths|length' "$out")"
}
# APEX v6 — research hypotheses and false-positive intelligence v2.
phase_v6_hypotheses(){
 local r="$APEX_RUN_DIR/reports/security_reasoning_graph.json" out="$APEX_RUN_DIR/reports/hypothesis_engine.json";[[ -s "$r" ]]||jq -n '{paths:[]}' >"$r"
 jq '{policy:{research_only:true,automatic_exploit:false},hypotheses:[.paths[]?|{id:("hypothesis|"+(.id|@base64)),hypothesis:((.object_type|ascii_upcase)+" ownership and permission enforcement requires controlled verification"),target,evidence:.evidence_sources,reasoning_chain,missing:.missing_proof,priority:.priority_score,confidence,classification:"RESEARCH_HYPOTHESIS",next_safe_step:.next_safe_investigation_step,automatic_vulnerability:false}]}' "$r">"$out";log_info "[v6 hypotheses] count=$(jq '.hypotheses|length' "$out")"
}
phase_v6_false_positive_v2(){
 local kb="$(vmax_kb_init)" mem="$APEX_RUN_DIR/reports/research_memory_snapshot.json" gate="$APEX_RUN_DIR/reports/quality_gate.json" out="$APEX_RUN_DIR/reports/false_positive_intelligence_v2.json" persist raw="$APEX_RUN_DIR/reports/fp_patterns.ndjson" x target pattern reasons evidence
 persist="$kb/false_positive_intelligence_v2.json";:>"$raw";[[ -s "$mem" ]]||jq -n '{false_positives:[],rejected_signals:[]}' >"$mem";[[ -s "$gate" ]]||jq -n '{records:[]}' >"$gate"
 while IFS= read -r x;do [[ -n "$x" ]]||continue;target="$(jq -r '.target//"unknown"'<<<"$x")";pattern="$(jq -r 'if(.status//0)==200 then"HTTP 200 + response pattern"elif(.validation_status//"")!="reproduced" then"Not reproduced"else"Insufficient evidence"end'<<<"$x")";reasons="$(jq -c '[if((.sensitive_fields//0)==0)then"No sensitive data"else empty end,if((.state_change//false)==false)then"No state change"else empty end,if((.validation_status//"")!="reproduced")then"Validation did not reproduce"else empty end]'<<<"$x")";evidence="$(jq -c '.evidence//[]'<<<"$x")";jq -cn --arg target "$target" --arg pattern "$pattern" --argjson reasons "$reasons" --argjson evidence "$evidence" '{fingerprint:($pattern+"|"+$target),target:$target,pattern:$pattern,rejected_because:$reasons,evidence_causes:$evidence,learning_effect:"Reduce priority only when the same normalized pattern recurs without new independent evidence",classification:"FALSE_POSITIVE_PATTERN"}'>>"$raw";done<<<"$(jq -c '(.false_positives//[])+(.rejected_signals//[])|.[]' "$mem")"
 while IFS= read -r x;do [[ -n "$x" ]]||continue;jq -cn --arg target "$(jq -r .target<<<"$x")" --argjson evidence "$(jq -c '.evidence_refs//[]'<<<"$x")" --argjson gates "$(jq -c '.gates'<<<"$x")" '{fingerprint:("quality-gate|"+$target),target:$target,pattern:"Failed quality gate",rejected_because:[$gates|to_entries[]|select(.value==false)|.key],evidence_causes:$evidence,learning_effect:"Do not suppress new evidence; require failed gates to be satisfied",classification:"REJECTED_SIGNAL_PATTERN"}'>>"$raw";done<<<"$(jq -c '.records[]?|select(.passes_vulnerability_gate==false)' "$gate")"
 jq -s 'group_by(.fingerprint)|map(.[0]+{occurrences:length})|{patterns:.,count:length,policy:{new_evidence_bypasses_prior_rejection:true,automatic_suppression:false}}' "$raw">"$out";cp "$out" "$persist.tmp";mv "$persist.tmp" "$persist";log_info "[v6 fp-v2] patterns=$(jq .count "$out")"
}
# APEX v6 — evidence chains, optimized research queue, and manual plans.
phase_v6_evidence_chains(){
 local r="$APEX_RUN_DIR/reports/security_reasoning_graph.json" pm="$APEX_RUN_DIR/reports/permission_matrix.json" out="$APEX_RUN_DIR/reports/evidence_chains.json";[[ -s "$r" ]]||jq -n '{paths:[]}' >"$r";[[ -s "$pm" ]]||jq -n '{rows:[]}' >"$pm"
 jq -n --slurpfile r "$r" --slurpfile p "$pm" '{classification:"EVIDENCE_COMPLETENESS_NOT_CONFIDENCE",chains:[($r[0].paths[]? as$x|([$p[0].rows[]?|select(.endpoint==$x.target)])as$rows|{reasoning_id:$x.id,target:$x.target,stages:[{id:"E1",name:"Endpoint discovered",complete:(($x.evidence_sources|length)>0),evidence:$x.evidence_sources},{id:"E2",name:"Object identified",complete:($x.object_type!="unknown"),evidence:$x.evidence_sources},{id:"E3",name:"Identity relationship",complete:($x.components.identities>1),evidence:[$rows[].identity]},{id:"E4",name:"Permission expectation",complete:([$rows[]|select(.expectation!="unknown")]|length>0),evidence:[$rows[]|select(.expectation!="unknown")|(.identity+":"+.expectation)]},{id:"E5",name:"Unexpected behavior",complete:$x.components.unexpected_behavior,evidence:[$rows[]|select(.classification|startswith("UNEXPECTED"))|(.identity+":"+.classification)]}],missing_proof:$x.missing_proof}|.evidence_completeness_percent=([.stages[]|select(.complete)]|length*20))],policy:{completeness_does_not_prove_impact:true}}' >"$out";log_info "[v6 chains] count=$(jq '.chains|length' "$out")"
}
phase_v6_research_optimizer(){
 local h="$APEX_RUN_DIR/reports/hypothesis_engine.json" c="$APEX_RUN_DIR/reports/evidence_chains.json" hunter="$APEX_RUN_DIR/reports/hunter_targets.json" out="$APEX_RUN_DIR/reports/research_priority_queue.json" raw="$APEX_RUN_DIR/reports/research_queue.ndjson" x target priority completeness hunter_score impact strength asset identity sensitive effort value chain f
 :>"$raw";for f in "$h" "$c" "$hunter";do [[ -s "$f" ]]||echo '{}' >"$f";done
 while IFS= read -r x;do [[ -n "$x" ]]||continue;target="$(jq -r .target<<<"$x")";priority="$(jq -r '.priority//0'<<<"$x")";chain="$(jq -c --arg t "$target" '.chains|map(select(.target==$t))[0]//{}' "$c")";completeness="$(jq -r '.evidence_completeness_percent//0'<<<"$chain")";hunter_score="$(jq -r --arg t "$target" '.targets|map(select(.target==$t))[0].priority_score//0' "$hunter")";impact=$((priority*30/100));((impact>30))&&impact=30;strength=$((completeness*25/100));asset=$((hunter_score*20/100));identity=5;[[ "$(jq -r '[.stages[]?|select(.id=="E3" and .complete)]|length>0'<<<"$chain")" == true ]]&&identity=15;sensitive=3;grep -Eqi '(invoice|account|transaction|user|file)'<<<"$(jq -r .hypothesis<<<"$x")"&&sensitive=10;effort=50;((completeness>=60))&&effort=20;value=$((impact+strength+asset+identity+sensitive-effort/4));((value<0))&&value=0;((value>100))&&value=100;jq -cn --arg id "$(jq -r .id<<<"$x")" --arg target "$target" --argjson impact "$impact" --argjson strength "$strength" --argjson asset "$asset" --argjson identity "$identity" --argjson sensitive "$sensitive" --argjson effort "$effort" --argjson completeness "$completeness" --argjson value "$value" --argjson missing "$(jq -c '.missing//[]'<<<"$x")" --arg step "$(jq -r .next_safe_step<<<"$x")" '{hypothesis_id:$id,target:$target,components:{impact_possibility:$impact,evidence_strength:$strength,asset_importance:$asset,identity_complexity:$identity,object_sensitivity:$sensitive,manual_effort_required:$effort},evidence_completeness:$completeness,missing_proof:$missing,next_safe_step:$step,expected_research_value:$value,classification:"RESEARCH_QUEUE_ITEM"}'>>"$raw";done<<<"$(jq -c '.hypotheses[]?' "$h")"
 jq -s 'sort_by(-.expected_research_value)|{classification:"OPTIMIZED_RESEARCH_QUEUE_NOT_FINDINGS",queue:.,policy:{manual_effort_is_cost:true,automatic_execution:false}}' "$raw">"$out";log_info "[v6 optimizer] queued=$(jq '.queue|length' "$out")"
}
phase_v6_manual_assistant(){
 local q="$APEX_RUN_DIR/reports/research_priority_queue.json" c="$APEX_RUN_DIR/reports/evidence_chains.json" out="$APEX_RUN_DIR/reports/manual_testing_plans.json";[[ -s "$q" ]]||jq -n '{queue:[]}' >"$q";[[ -s "$c" ]]||jq -n '{chains:[]}' >"$c"
 jq -n --slurpfile q "$q" --slurpfile c "$c" '{classification:"MANUAL_PLANS_NO_AUTOMATIC_REQUESTS",plans:[($q[0].queue[]? as$x|($c[0].chains|map(select(.target==$x.target))[0]//{})as$chain|{target:$x.target,expected_research_value:$x.expected_research_value,preparation:["Confirm written authorization and scope","Create or select two controlled test identities","Establish object ownership independently","Capture a non-destructive baseline"],question:"Can identity A observe or perform the same operation against an object independently proven to belong to identity B?",required_evidence:["Ownership proof","Identity and role metadata without secrets","Before/after response comparison","Before/after object state when safe","Referenced evidence IDs"],steps:["Record baseline with owner identity","Repeat only the same safe action with second controlled identity","Compare status, structure, visible and sensitive fields","Confirm state independently; do not infer success from HTTP status"],stop_conditions:["No independent ownership proof","Target leaves authorized scope","Action may be destructive or irreversible","Unexpected real-user data appears","Safe rollback is unavailable"],evidence_completeness:($chain.evidence_completeness_percent//0),automatic_execution:false})],requests_sent:0}' >"$out";log_info "[v6 manual] plans=$(jq '.plans|length' "$out")"
}
# APEX v6 — professional researcher report v2.
phase_v6_researcher_report(){
 local surf="$APEX_RUN_DIR/reports/attack_surface_intelligence_v2.json" q="$APEX_RUN_DIR/reports/research_priority_queue.json" reason="$APEX_RUN_DIR/reports/security_reasoning_graph.json" ev="$APEX_RUN_DIR/reports/evidence_graph.json" fp="$APEX_RUN_DIR/reports/false_positive_intelligence_v2.json" plans="$APEX_RUN_DIR/reports/manual_testing_plans.json" app="$APEX_RUN_DIR/reports/application_model.json" out="$APEX_RUN_DIR/reports/researcher_report.md" f;for f in "$surf" "$q" "$reason" "$ev" "$fp" "$plans" "$app";do [[ -s "$f" ]]||echo '{}' >"$f";done
 { printf '# APEX v6 Professional Research Report\n\n> Security research intelligence report. It is not a scanner vulnerability report.\n\n## Executive Overview\n\n';jq -nr --slurpfile s "$surf" --slurpfile q "$q" --slurpfile e "$ev" '"- Attack-surface nodes: \(($s[0].nodes//[])|length)\n- High-value research areas: \(($s[0].critical_paths//[])|length)\n- Optimized research paths: \(($q[0].queue//[])|length)\n- Referenced evidence nodes: \(($e[0].evidence//[])|length)\n- Automatic vulnerability promotions: 0\n"';printf '\n## Attack Surface Map\n\n';jq -r '.critical_paths[]?|"- [\(.priority_score)] \(.target) — \(.classification)"' "$surf";printf '\n## Highest Value Research Paths\n\n';jq -r '.queue[]?|"### \(.target)\n- Expected research value: \(.expected_research_value)\n- Evidence completeness: \(.evidence_completeness)%\n- Missing proof: \(.missing_proof|join("; "))\n- Safe next step: \(.next_safe_step)\n"' "$q";printf '\n## Reasoning Chains\n\n';jq -r '.paths[]?|"- \(.target): \(.reasoning_chain|join(" → ")) [confidence=\(.confidence)]"' "$reason";printf '\n## Confirmed Observations\n\n';jq -r '.evidence[]?|select(.fact_status=="OBSERVED")|"- [\(.source_type)] \(.claim.type): \(.claim.subject)"' "$ev";printf '\n## Rejected Signals and False-Positive Learning\n\n';jq -r '.patterns[]?|"- \(.pattern) at \(.target): \(.rejected_because|join("; "))"' "$fp";printf '\n## Manual Investigation Plans\n\n';jq -r '.plans[]?|"### \(.target)\n- Question: \(.question)\n- Required evidence: \(.required_evidence|join("; "))\n- Stop conditions: \(.stop_conditions|join("; "))\n"' "$plans";printf '\n## Evidence Gaps\n\n';jq -r '.paths[]?|select((.missing_proof|length)>0)|"- \(.target): \(.missing_proof|join("; "))"' "$reason";printf '\n## Historical Changes\n\n';jq -r '"- New endpoints: \((.historical_changes.new_endpoints//[])|length)\n- Removed endpoints: \((.historical_changes.removed_endpoints//[])|length)\n- New technologies: \((.historical_changes.new_technologies//[])|length)"' "$app";printf '\n\n## Limitations\n\n- Bash/jq performs deterministic rule-based reasoning, not AI detection.\n- Evidence completeness is not proof of impact.\n- Business intent and ownership require independent human evidence.\n- No automatic exploitation, browser runtime, or zero-false-positive claim is made.\n';}>"$out";log_info "[v6 report] $out"
}

# APEX v7 — evidence-only ownership and state-change verification.
phase_v7_state_verification(){
 local plan="$(cfg_get_default state_verification_plan '')" out="$APEX_RUN_DIR/reports/state_change_verification.json" raw="$APEX_RUN_DIR/reports/state_change_signals.ndjson" q id target object action identity before after bs as rs bh ah changed=false classification evidence_before evidence_after
 :>"$raw";if [[ ! -s "$plan" ]];then jq -n '{classification:"STATE_VERIFICATION_SIGNALS",records:[],count:0,note:"Explicit state_verification_plan required; no requests executed."}' >"$out";return;fi
 while IFS= read -r q;do [[ -n "$q" ]]||continue;jq -e '.target and .action'<<<"$q">/dev/null 2>&1||continue;id="$(jq -r '.id//empty'<<<"$q")";[[ -n "$id" ]]||id="state|$(jq -cS .<<<"$q"|apex_sha256)";target="$(jq -r .target<<<"$q")";object="$(jq -r '.object//""'<<<"$q")";action="$(jq -r '.action|ascii_downcase'<<<"$q")";identity="$(jq -r '.identity//"unknown"'<<<"$q")";before="$(jq -r '.before_file//""'<<<"$q")";after="$(jq -r '.after_file//""'<<<"$q")";bs="$(jq -r '.before_status//0'<<<"$q")";as="$(jq -r '.after_status//0'<<<"$q")";rs="$(jq -r '.request_status//0'<<<"$q")";bh="";ah="";evidence_before="";evidence_after="";changed=false
 if [[ -f "$before" ]];then bh="$(apex_sha256<"$before")";evidence_before="$(record_evidence state-before "Before snapshot hash=$bh status=$bs target=$target")";fi
 if [[ -f "$after" ]];then ah="$(apex_sha256<"$after")";evidence_after="$(record_evidence state-after "After snapshot hash=$ah status=$as target=$target")";fi
 [[ -n "$bh" && -n "$ah" && "$bh" != "$ah" ]]&&changed=true
 classification=INCONCLUSIVE_MISSING_SNAPSHOT
 if [[ "$action" == delete && "$bs" -ge 200 && "$bs" -lt 300 && ( "$as" -eq 404 || "$as" -eq 410 ) ]];then changed=true;classification=VERIFIED_STATE_CHANGE_SIGNAL
 elif [[ "$action" == create && ( "$bs" -eq 404 || "$bs" -eq 410 || "$bs" -eq 0 ) && "$as" -ge 200 && "$as" -lt 300 && "$changed" == true ]];then classification=VERIFIED_STATE_CHANGE_SIGNAL
 elif [[ "$action" == export && -f "$after" && -s "$after" ]];then changed=true;classification=EXPORT_ARTIFACT_OBSERVED_SIGNAL
 elif [[ -f "$before" && -f "$after" && "$changed" == true ]];then classification=VERIFIED_STATE_CHANGE_SIGNAL
 elif [[ "$rs" -ge 200 && "$rs" -lt 300 && "$changed" == false && -f "$before" && -f "$after" ]];then classification=HTTP_SUCCESS_WITHOUT_STATE_CHANGE
 elif [[ -f "$before" && -f "$after" ]];then classification=NO_STATE_CHANGE_OBSERVED;fi
 jq -cn --arg id "$id" --arg target "$target" --arg object "$object" --arg action "$action" --arg identity "$identity" --arg classification "$classification" --arg before_hash "$bh" --arg after_hash "$ah" --arg before_evidence "$evidence_before" --arg after_evidence "$evidence_after" --argjson before_status "$bs" --argjson after_status "$as" --argjson request_status "$rs" --argjson changed "$changed" '{id:$id,target:$target,object:$object,action:$action,identity:$identity,before:{status:$before_status,hash:(if $before_hash=="" then null else $before_hash end),evidence:(if $before_evidence=="" then null else $before_evidence end)},after:{status:$after_status,hash:(if $after_hash=="" then null else $after_hash end),evidence:(if $after_evidence=="" then null else $after_evidence end)},request_status:$request_status,state_changed:$changed,classification:$classification,observation_is_vulnerability:false,automatic_promotion:false}'>>"$raw"
 done<"$plan";jq -s '{classification:"STATE_CHANGE_RESEARCH_SIGNALS",records:.,count:length,verified_changes:([.[]|select(.state_changed)]|length),http_2xx_without_change:([.[]|select(.classification=="HTTP_SUCCESS_WITHOUT_STATE_CHANGE")]|length),requests_executed:0}' "$raw">"$out";log_info "[v7 state] records=$(jq .count "$out") verified=$(jq .verified_changes "$out")"
}
phase_v7_ownership_verification(){
 local profiles="$(cfg_get_default identity_profiles_dir '')" extra="$(cfg_get_default ownership_evidence_file '')" diff="$APEX_RUN_DIR/reports/identity_differential.json" state="$APEX_RUN_DIR/reports/state_change_verification.json" ev="$APEX_RUN_DIR/reports/evidence_graph.json" model="$APEX_RUN_DIR/reports/ownership_model.json" out="$APEX_RUN_DIR/reports/ownership_verification.json" claims="$APEX_RUN_DIR/reports/ownership_claims.ndjson" f p x verify_raw test object target analysis_key owners owner_ids owner_count owner_obs obs tested role status visible sensitive hash owner_available same owner_hash state_count state_refs classification evidence_sources
 :>"$claims";if [[ -d "$profiles" ]];then for f in "$profiles"/*.json;do [[ -s "$f" ]]||continue;while IFS= read -r x;do [[ -n "$x" ]]||continue;jq -cn --arg identity "$(jq -r .id "$f")" --arg role "$(jq -r '.role//"unknown"' "$f")" --argjson object "$x" --arg source "$f" '{identity:$identity,role:$role,object_type:($object.type//"unknown"),identifier:($object.id|tostring),relationship:($object.relationship//"observed"),source_type:"IDENTITY_PROFILE",source_ref:$source,confidence:(if($object.relationship//"")=="owner" then 75 else 50 end),fact_status:"OPERATOR_DECLARED_NOT_INDEPENDENTLY_VERIFIED"}'>>"$claims";done<<<"$(jq -c '.known_objects[]?' "$f")";done;fi
 if [[ -s "$extra" ]];then while IFS= read -r x;do [[ -n "$x" ]]||continue;jq -c '{identity,role:(.role//"unknown"),object_type:(.object_type//"unknown"),identifier:(.identifier|tostring),relationship:(.relationship//"owner"),source_type:(.source_type//"EXTERNAL_EVIDENCE"),source_ref:(.evidence_id//.source_ref//"operator-supplied"),confidence:([95,(.confidence//75)]|min),fact_status:"EVIDENCE_BACKED_OWNERSHIP_CLAIM"}'<<<"$x">>"$claims";done<"$extra";fi
 jq -s '{policy:{object_id_alone_never_proves_ownership:true,independent_evidence_required:true},claims:.,count:length}' "$claims">"$model";[[ -s "$diff" ]]||jq -n '{tests:[]}' >"$diff";[[ -s "$state" ]]||jq -n '{records:[]}' >"$state";[[ -s "$ev" ]]||jq -n '{evidence:[]}' >"$ev"
 verify_raw="$APEX_RUN_DIR/reports/ownership_verifications.ndjson";:>"$verify_raw"
 while IFS= read -r test;do
  [[ -n "$test" ]]||continue
  object="$(jq -r '.object|tostring'<<<"$test")";target="$(jq -r '.target//"unknown"'<<<"$test")";analysis_key="$(jq -r '.analysis_key//"unknown"'<<<"$test")"
  owners="$(jq -c --arg object "$object" '[.claims[]?|select(.identifier==$object and .relationship=="owner")]' "$model")";owner_ids="$(jq '[.[].identity]|unique'<<<"$owners")";owner_count="$(jq length<<<"$owners")";owner_obs="$(jq -c --argjson ids "$owner_ids" '(.observations//[])|map(select(.identity as $i|$ids|index($i)!=null))[0]//null'<<<"$test")"
  while IFS= read -r obs;do
   [[ -n "$obs" ]]||continue;tested="$(jq -r .identity<<<"$obs")";[[ "$(jq -r --arg i "$tested" 'index($i)!=null'<<<"$owner_ids")" == true ]]&&continue
   role="$(jq -r '.role//"unknown"'<<<"$obs")";status="$(jq -r '.status//0'<<<"$obs")";visible="$(jq -r '.object_reference_seen//false'<<<"$obs")";sensitive="$(jq -r '.sensitive_field_indicators//0'<<<"$obs")";hash="$(jq -r '.body_hash//""'<<<"$obs")";owner_available=false;same=false
   if [[ "$owner_obs" != null ]];then owner_available=true;owner_hash="$(jq -r '.body_hash//""'<<<"$owner_obs")";[[ -n "$hash" && "$hash" == "$owner_hash" ]]&&same=true;fi
   state_count="$(jq --arg object "$object" --arg identity "$tested" '[.records[]?|select(.object==$object and .identity==$identity and .state_changed)]|length' "$state")";state_refs="$(jq -c --arg object "$object" --arg identity "$tested" '[.records[]?|select(.object==$object and .identity==$identity and .state_changed)|.before.evidence,.after.evidence|select(.!=null)]' "$state")"
   classification=INCONCLUSIVE
   if ((owner_count==0));then classification=INCONCLUSIVE_NO_OWNERSHIP_PROOF
   elif ((state_count>0));then classification=CROSS_IDENTITY_STATE_CHANGE_SIGNAL
   elif ((status>=200&&status<300))&&{ [[ "$visible" == true ]]||((sensitive>0)); }&&[[ "$same" == true ]];then classification=CROSS_IDENTITY_ACCESS_SIGNAL
   elif [[ "$status" == 401 || "$status" == 403 || "$status" == 404 ]];then classification=EXPECTED_ISOLATION;fi
   evidence_sources="$(jq -cn --argjson owners "$owners" --argjson state "$state_refs" --arg identity "$tested" --slurpfile e "$ev" '([$owners[].source_ref]+$state+[$e[0].evidence[]?|select((.claim.identity//"")==$identity)|.id])|unique')"
   jq -cn --arg analysis_key "$analysis_key" --arg target "$target" --arg object "$object" --arg tested "$tested" --arg role "$role" --arg classification "$classification" --argjson owners "$owners" --argjson sources "$evidence_sources" --argjson status "$status" --argjson visible "$visible" --argjson sensitive "$sensitive" --argjson owner_available "$owner_available" --argjson same "$same" --argjson state_change "$([[ $state_count -gt 0 ]]&&echo true||echo false)" '{analysis_key:$analysis_key,target:$target,object:$object,owner_evidence:$owners,tested_identity:$tested,tested_role:$role,owner_response_available:$owner_available,comparison:{status:$status,object_visible:$visible,sensitive_fields:$sensitive,same_owner_fingerprint:$same,state_change_verified:$state_change},evidence_sources:$sources,classification:$classification,automatic_vulnerability:false}'>>"$verify_raw"
  done<<<"$(jq -c '.observations[]?'<<<"$test")"
 done<<<"$(jq -c '.tests[]?' "$diff")"
 jq -s '{classification:"OWNERSHIP_RESEARCH_SIGNALS",verifications:.,policy:{allowed_classifications:["CROSS_IDENTITY_ACCESS_SIGNAL","CROSS_IDENTITY_STATE_CHANGE_SIGNAL","EXPECTED_ISOLATION","INCONCLUSIVE_NO_OWNERSHIP_PROOF","INCONCLUSIVE"],quality_gate_required:true,automatic_promotion:false}}' "$verify_raw">"$out";log_info "[v7 ownership] checks=$(jq '.verifications|length' "$out")"
}
# APEX v7 — per-program intelligence memory and import-only OOB correlation.
phase_v7_program_memory(){
 local src="$(cfg_get_default program_profile_file '')" kb="$(vmax_kb_init)" out="$APEX_RUN_DIR/reports/program_intelligence_memory.json" ctx="$APEX_RUN_DIR/reports/program_priority_context.json" id safe persist
 if [[ ! -s "$src" ]];then jq -n '{program:null,note:"No program_profile_file supplied; no priority assumptions created."}' >"$out";jq -n '{adjustments:[],confidence_adjustment:0}' >"$ctx";return;fi
 jq -e '.program_id' "$src">/dev/null||{ jq -n '{error:"invalid program profile"}' >"$out";return;};id="$(jq -r .program_id "$src")";safe="$(printf '%s' "$id"|tr -cs 'A-Za-z0-9._-' '_')";mkdir -p "$kb/programs";persist="$kb/programs/$safe.json"
 jq '{program_id,name:(.name//.program_id),assets:(.assets//[]|map({match,value:(.value//0),reason:(.reason//"program profile")})),policies:(.policies//[]),accepted_reports:(.accepted_reports//[]),duplicate_reports:(.duplicate_reports//[]),rejected_reports:(.rejected_reports//[]),updated_at:(now|todate),policy:{priority_only:true,confidence_adjustment:0,secrets_stored:false}}' "$src">"$out";cp "$out" "$persist.tmp";mv "$persist.tmp" "$persist"
 jq '{program_id,adjustments:[.assets[]?|{match,priority_bonus:([30,.value]|min),reason}],accepted_patterns:[.accepted_reports[]?.pattern],duplicate_patterns:[.duplicate_reports[]?.pattern],rejected_patterns:[.rejected_reports[]?.pattern],confidence_adjustment:0,note:"Program knowledge changes priority only; it never raises evidence confidence."}' "$out">"$ctx";log_info "[v7 program-memory] program=$id assets=$(jq '.assets|length' "$out")"
}
phase_v7_oob_integration(){
 local registry="$(cfg_get_default oob_registry_file '')" events="$(cfg_get_default oob_events_file '')" enabled="$(cfg_get_default enable_oob_import false)" provider="$(cfg_get_default oob_provider interactsh)" regout="$APEX_RUN_DIR/reports/oob_registry.ndjson" raw="$APEX_RUN_DIR/reports/oob_callbacks.ndjson" out="$APEX_RUN_DIR/reports/oob_research.json" r e cid target vector event_cid protocol remote event_hash evidence
 :>"$regout";:>"$raw";if [[ "$enabled" != true ]];then jq -n --arg provider "$provider" '{provider:$provider,enabled:false,callbacks:[],classification:"OOB_DISABLED",note:"Import is opt-in; no OOB client executed."}' >"$out";return;fi
 if [[ -s "$registry" ]];then while IFS= read -r r;do [[ -n "$r" ]]||continue;cid="$(jq -r '.correlation_id//empty'<<<"$r")";[[ -n "$cid" ]]||cid="oob-$(jq -cS .<<<"$r"|apex_sha256|cut -c1-20)";jq -c --arg cid "$cid" --arg provider "$provider" '.+{correlation_id:$cid,provider:$provider,automatic_probe:false}'<<<"$r">>"$regout";done<"$registry";fi
 if [[ -s "$events" ]];then while IFS= read -r e;do [[ -n "$e" ]]||continue;event_cid="$(jq -r '.correlation_id//."unique-id"//."full-id"//empty'<<<"$e")";[[ -n "$event_cid" ]]||continue;r="$(jq -c --arg c "$event_cid" '. as $r|select($r.correlation_id==$c or ($c|contains($r.correlation_id)))' "$regout"|head -1)";[[ -n "$r" ]]||continue;cid="$(jq -r .correlation_id<<<"$r")";target="$(jq -r '.target//"unknown"'<<<"$r")";vector="$(jq -r '.vector//"unknown"'<<<"$r")";protocol="$(jq -r '.protocol//.type//"unknown"'<<<"$e")";remote="$(jq -r '."remote-address"//.remote_address//"unknown"'<<<"$e")";event_hash="$(jq -cS .<<<"$e"|apex_sha256)";evidence="$(record_evidence oob-callback "provider=$provider correlation_id=$cid target=$target vector=$vector protocol=$protocol remote=$remote event_sha256=$event_hash")";jq -cn --arg cid "$cid" --arg target "$target" --arg vector "$vector" --arg provider "$provider" --arg protocol "$protocol" --arg remote "$remote" --arg hash "$event_hash" --arg evidence "$evidence" '{correlation_id:$cid,target:$target,vector:$vector,provider:$provider,protocol:$protocol,remote_address:$remote,event_sha256:$hash,evidence_id:$evidence,classification:"CALLBACK_OBSERVED_SIGNAL",quality_gate_required:true,automatic_vulnerability:false,raw_event_stored:false}'>>"$raw";done<"$events";fi
 jq -s --arg provider "$provider" --slurpfile registry "$regout" '{provider:$provider,enabled:true,registry:$registry,callbacks:.,count:length,classification:"OOB_RESEARCH_SIGNALS",client_execution:"NONE_IMPORT_ONLY",quality_gate_required:true}' "$raw">"$out";log_info "[v7 oob] callbacks=$(jq .count "$out")"
}
# APEX v7 — bounded lexical JavaScript relationship intelligence.
phase_v7_advanced_js(){
 local deep="$APEX_RUN_DIR/reports/deep_javascript_map.json" basic="$APEX_RUN_DIR/reports/javascript_map.json" out="$APEX_RUN_DIR/reports/advanced_javascript_intelligence.json" raw="$APEX_RUN_DIR/reports/js_relationships.ndjson" c endpoint family object role auth resolution confidence action
 :>"$raw";[[ -s "$deep" ]]||jq -n '{calls:[]}' >"$deep";[[ -s "$basic" ]]||jq -n '{auth_flows:[],feature_flags:[],source_maps:[]}' >"$basic"
 while IFS= read -r c;do [[ -n "$c" ]]||continue;endpoint="$(jq -r .endpoint<<<"$c")";family="$(v5_endpoint_family "$endpoint")";object="$(v5_object_type "$family")";role="$(jq -r '.client_role_guard//"unknown"'<<<"$c")";resolution="$(jq -r '.resolution//"static_reference"'<<<"$c")";confidence="$(jq -r '.confidence//50'<<<"$c")";action="$(v5_action UNKNOWN "$endpoint")";auth="$(jq -c '.auth_flows//[]' "$basic")";jq -cn --arg endpoint "$endpoint" --arg family "$family" --arg object "$object" --arg role "$role" --arg resolution "$resolution" --arg action "$action" --argjson auth "$auth" --argjson confidence "$confidence" '{endpoint:$endpoint,endpoint_family:$family,object_type:$object,role_indicator:(if $role=="unknown" then null else $role end),authentication_flow_indicators:$auth,action:$action,source:"STATIC_JAVASCRIPT",discovery_method:$resolution,confidence:([75,$confidence]|min),classification:"STATIC_LEXICAL_RELATION",runtime_verified:false,server_authorization_proven:false}'>>"$raw";done<<<"$(jq -c '.calls[]?' "$deep")"
 jq -s --slurpfile basic "$basic" '{analysis:"BOUNDED_LEXICAL_RELATIONSHIPS_NOT_SEMANTIC_AST",relationships:.,endpoint_object_edges:[.[]|{from:.endpoint,to:("object:"+.object_type),type:"CLIENT_REFERENCES_OBJECT",confidence:.confidence}],endpoint_role_edges:[.[]|select(.role_indicator!=null)|{from:.role_indicator,to:.endpoint,type:"CLIENT_ROLE_GUARD_REFERENCE",confidence:.confidence}],authentication_flows:($basic[0].auth_flows//[]),source_maps:($basic[0].source_maps//[]),limitations:["No browser runtime","No semantic AST","No proof of server-side authorization","Dynamic values may be unresolved"]}' "$raw">"$out";log_info "[v7 advanced-js] relationships=$(jq '.relationships|length' "$out")"
}
# APEX v7 — submission-ready reports only for findings that already passed the existing quality gate.
v7_cwe(){ case "${1,,}" in *idor*|*bola*|*authorization*)echo CWE-639;;*xss*)echo CWE-79;;*sql*)echo CWE-89;;*ssrf*)echo CWE-918;;*cors*)echo CWE-942;;*secret*|*exposed*)echo CWE-200;;*)echo CWE-Other;;esac; }
v7_fix(){ case "${1,,}" in *idor*|*bola*|*authorization*)echo 'Enforce server-side object authorization on every action and derive ownership from the authenticated principal, not client identifiers.';;*xss*)echo 'Apply context-aware output encoding, input validation, and an appropriate Content Security Policy.';;*sql*)echo 'Use parameterized queries and least-privileged database identities.';;*ssrf*)echo 'Allowlist destinations, block private/link-local ranges after DNS resolution, and enforce egress controls.';;*)echo 'Apply server-side validation, least privilege, and regression tests for the demonstrated condition.';;esac; }
phase_v7_bug_bounty_reports(){
 local gate="$APEX_RUN_DIR/reports/quality_gate.json" findings="$APEX_RUN_DIR/db/findings.ndjson" dir="$APEX_RUN_DIR/reports/bug_bounty_reports" index="$APEX_RUN_DIR/reports/bug_bounty_report_index.json" raw="$APEX_RUN_DIR/reports/bug_bounty_report_rows.ndjson" id f category target severity confidence cwe fix file safe evidence
 mkdir -p "$dir";rm -f "$dir"/*.md;:>"$raw";[[ -s "$gate" ]]||jq -n '{records:[]}' >"$gate";[[ -f "$findings" ]]||:>"$findings"
 while IFS= read -r id;do [[ -n "$id" ]]||continue;f="$(jq -c --arg id "$id" 'select(.id==$id and .reportability=="REPORTABLE")' "$findings"|head -1)";[[ -n "$f" ]]||continue;category="$(jq -r .category<<<"$f")";target="$(jq -r .target<<<"$f")";severity="$(jq -r .severity<<<"$f")";confidence="$(jq -r '.confidence_score//0'<<<"$f")";cwe="$(v7_cwe "$category")";fix="$(v7_fix "$category")";safe="$(printf '%s-%s' "$category" "$id"|tr -cs 'A-Za-z0-9._-' '_'|cut -c1-100)";file="$dir/$safe.md";evidence="$(jq -c '.evidence//[]'<<<"$f")";{
 printf '# %s affecting %s\n\n' "$category" "$target";printf '## Severity rationale\n\n%s severity with confidence %s/100. This report was generated only after the existing scope, evidence, validation, confidence, and duplicate gates passed.\n\n' "$severity" "$confidence";printf '## CWE\n\n%s\n\n' "$cwe";printf '## Affected assets\n\n- %s\n\n' "$target";printf '## Reproduction\n\n%s\n\n' "$(jq -r '.reproduction//"See validated evidence and supporting material."'<<<"$f")";printf '## Evidence\n\n';jq -r '.[]|"- "+.'<<<"$evidence";printf '\n## Impact\n\n%s\n\n' "$(jq -r '.impact//"Validated security impact described by the confirmed finding."'<<<"$f")";printf '## Suggested fix\n\n%s\n\n' "$fix";printf '## Supporting material\n\n- Finding ID: %s\n- Validation status: %s\n- Confidence: %s/100\n- Evidence references are stored in the APEX Evidence Store.\n' "$id" "$(jq -r .validation_status<<<"$f")" "$confidence";}>"$file";jq -cn --arg id "$id" --arg file "$file" --arg title "$category affecting $target" --arg cwe "$cwe" '{finding_id:$id,file:$file,title:$title,cwe:$cwe,quality_gate_passed:true}'>>"$raw";done<<<"$(jq -r '.records[]?|select(.passes_vulnerability_gate==true)|.finding_id' "$gate")"
 jq -s '{classification:"QUALITY_GATED_SUBMISSION_REPORTS",reports:.,count:length,research_signals_excluded:true,quality_gate_required:true}' "$raw">"$index";if [[ "$(jq .count "$index")" -eq 0 ]];then printf '# No submission-ready finding\n\nNo finding passed the existing five-part quality gate. Research signals were not converted into reports.\n' >"$dir/README.md";fi;log_info "[v7 bounty-report] reports=$(jq .count "$index")"
}

# ===== lib/main.sh =====
# APEX :: lib/main.sh
# CLI dispatcher shared by the modular launcher and the single-file bundle.

: "${APEX_VERSION:=2.0.0}"

# Best-effort cleanup of scratch working files on exit (keeps db/, evidence/,
# reports/, logs/). FIX: temp files were accumulating in the run dir.
apex_cleanup() {
  local rc=$?
  [[ -n "${APEX_RUN_DIR:-}" && -d "$APEX_RUN_DIR/raw" ]] || return $rc
  find "$APEX_RUN_DIR/raw" -type f \( -name '*.tok' -o -name '*.match' -o -name '*.clean' \
    -o -name '*.body' -o -name '*.jsl' -o -name '*.sorted' \) -delete 2>/dev/null || true
  return $rc
}

apex_usage() {
  cat <<EOF
APEX Security Automation v${APEX_VERSION}

USAGE:
  apex.sh <command> [--key=value ...] [scope ...]

COMMANDS:
  scan   <domain|file|*> ...   Run the full 16-phase pipeline against authorized scope
  doctor                       Health check, dependency + environment validation
  config                       Print effective configuration (after all overrides)
  version                      Print version
  help                         Show this help

SCOPE:
  example.com          apex + all sub-domains
  '*.example.com'      apex + all sub-domains (wildcard)
  '*'                  ALLOW-ALL (wildcard/VDP programs with no scope limit)
  '!dev.example.com'   EXCLUDE this host/subtree (out-of-scope; overrides inclusions)
  scope.txt            a file with one entry per line (# comments allowed)

EOF
  cfg_usage
  cat <<EOF

SAFETY:
  Passive OSINT (subdomain APIs, crt.sh) always runs.
  Target-touching phases need consent: --authorized=true (or --local_lab=true, or ALLOW-ALL).
  Intrusive phases (SSRF/XSS/open-redirect/race) also need --enable_active=true.
  Empty scope with no ALLOW-ALL denies everything (fail-closed).
EOF
}

apex_doctor() {
  local rc=0
  echo "=================================================="
  echo " APEX doctor — health & environment validation"
  echo "=================================================="
  echo
  echo "Environment:"
  printf '  bash version : %s\n' "${BASH_VERSION}"
  if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0]==4 && BASH_VERSINFO[1]<3) )); then
    echo "  [FAIL] bash >= 4.3 required"; rc=1
  else
    echo "  [OK]   bash is recent enough"
  fi
  [[ -w "${TMPDIR:-/tmp}" ]] && echo "  [OK]   temp dir writable" || { echo "  [FAIL] temp dir not writable"; rc=1; }
  echo
  echo "Core dependencies (required):"
  deps_check_core || rc=1
  echo
  echo "Optional tools (stages auto-skip if missing — install with bin/install_tools.sh):"
  deps_check_optional
  echo
  if [[ -n "${APEX_HOME:-}" && -f "$APEX_HOME/tests/run_tests.sh" ]]; then
    echo "Self-test of core libraries:"
    if bash "$APEX_HOME/tests/run_tests.sh" >/tmp/apex_selftest.log 2>&1; then
      echo "  [OK]   all unit tests passed"
    else
      echo "  [FAIL] unit tests failed — see /tmp/apex_selftest.log"; rc=1
    fi
    echo
  fi
  (( rc == 0 )) && echo "RESULT: healthy ✅" || echo "RESULT: problems detected ⚠️"
  return "$rc"
}

apex_main() {
  cfg_defaults
  [[ -n "${APEX_HOME:-}" && -f "$APEX_HOME/config/default.conf" ]] && cfg_load_file "$APEX_HOME/config/default.conf"

  local cmd="${1:-help}"; shift || true
  local flags=() positional=() a
  for a in "$@"; do
    case "$a" in
      --*=*) flags+=("$a") ;;
      *)     positional+=("$a") ;;
    esac
  done

  case "$cmd" in
    help|-h|--help)     apex_usage; return 0 ;;
    version|-v|--version) printf '%s\n' "$APEX_VERSION"; return 0 ;;
    doctor)             apex_doctor; return $? ;;
  esac

  cfg_load_env
  cfg_apply_cli "${flags[@]:-}" || { apex_usage; return "$APEX_E_USAGE"; }
  apex_apply_mode || { apex_usage; return "$APEX_E_CONFIG"; }
  APEX_LOG_LEVEL="$(cfg_get log_level)"; export APEX_LOG_LEVEL
  APEX_LOG_JSON="$(cfg_get log_json)";  export APEX_LOG_JSON

  case "$cmd" in
    config) cfg_dump; return 0 ;;
    scan)
      (( ${#positional[@]} > 0 )) || apex_die "$APEX_E_USAGE" "scan requires at least one scope (domain, file, or '*')"
      scope_load "${positional[@]}"
      cfg_bool scope_allow_all && scope_enable_allow_all
      cfg_bool scope_default_allow && scope_set_default_allow 1
      if (( ${#APEX_SCOPE[@]} == 0 )) && (( ${APEX_SCOPE_ALLOW_ALL:-0} == 0 )); then
        apex_die "$APEX_E_SCOPE" "no valid scope parsed and ALLOW-ALL not set (fail-closed)"
      fi
      # Seeds for enumeration = explicit apex domains (not the '*' token).
      APEX_SEEDS=()
      for a in "${positional[@]}"; do
        case "$a" in
          '*'|'!'*) : ;;
          '*.'*)    APEX_SEEDS+=("${a#*.}") ;;
          *)        [[ -f "$a" ]] || APEX_SEEDS+=("${a,,}") ;;
        esac
      done
      if (( ${#APEX_SEEDS[@]} == 0 )); then
        # allow reading seeds from a scope file's inclusion entries
        local h; for h in "${APEX_SCOPE[@]}"; do APEX_SEEDS+=("$h"); done
      fi
      (( ${APEX_SCOPE_ALLOW_ALL:-0} == 1 )) && log_warn "ALLOW-ALL scope active — use only for programs that explicitly permit it."

      local ts out_dir
      ts="$(date -u +%Y%m%dT%H%M%SZ)"
      out_dir="$(cfg_get out_dir)"
      [[ -n "$out_dir" ]] || out_dir="$PWD/apex_runs/${APEX_SEEDS[0]:-scope}_${ts}"
      store_init "$out_dir" || apex_die "$APEX_E_GENERAL" "cannot init run dir: $out_dir"
      APEX_LOG_FILE="$out_dir/logs/apex.log"; export APEX_LOG_FILE
      redact_init
      APEX_STATE_DIR="$out_dir/.state"; mkdir -p "$APEX_STATE_DIR"; export APEX_STATE_DIR
      APEX_EXEC_RETRIES="$(cfg_get retries)"; export APEX_EXEC_RETRIES
      trap 'apex_cleanup' EXIT
      # FIX 3.8: resume state must match the settings it was produced under.
      # Fingerprint the effective config; if --resume is requested but the config
      # changed since the last run, discard stale .done markers so we never
      # resume phases under different settings (avoids inconsistent state).
      local _cfgfp _prevfp
      _cfgfp="$(cfg_dump | apex_sha256)"
      _prevfp="$(cat "$APEX_STATE_DIR/config.fp" 2>/dev/null || true)"
      if cfg_bool resume && [[ -n "$_prevfp" && "$_prevfp" != "$_cfgfp" ]]; then
        log_warn "resume: configuration changed since last run — invalidating stale phase state"
        find "$APEX_STATE_DIR" -name '*.done' -delete 2>/dev/null || true
      fi
      printf '%s\n' "$_cfgfp" > "$APEX_STATE_DIR/config.fp" 2>/dev/null || true

      if cfg_bool enable_active && ! _recon_ok; then
        apex_die "$APEX_E_SCOPE" "active tests requested without consent (set --authorized=true)"
      fi
      log_info "scope: $(scope_summary)"
      log_info "seeds: ${APEX_SEEDS[*]:-<none>} | out: $out_dir"
      pipeline_run
      log_info "reports in: $out_dir/reports/"
      printf '%s\n' "$out_dir"
      return 0 ;;
    *)
      log_error "unknown command: $cmd"; apex_usage; return "$APEX_E_USAGE" ;;
  esac
}

# ===== entry point =====
apex_main "$@"
